INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('2907bc57-8828-4905-98e7-7a3140907267', 'คืนค่าเวลาเริ่มต้นของวันนี้', 'get_today_ISOString', 'exec', 19, 18, '{"code":"module.exports = async function(data) {\n\tconst today = new Date ()\n    today.setUTCHours(0, 0, 0, 0)\n    \n\treturn today.toISOString();\n}"}', 'c65f98e1-b9f0-4d5a-a48e-3df83195c86d', NULL, '62c45fee-1f13-4c6f-b11b-d156f06626df', '2025-09-17 07:04:10.232+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
