INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('31bc574c-8fbf-4567-9436-008d23aed035', 'check_queue_status_1', 'check_queue_status_1', 'exec', 3, 18, '{"code":"module.exports = async function(data) {\n    let queue = {{$trigger.payload}};\n\t//1 เรียกคิว 2 เสร็จสิ้น 0 รอเรียกคิว\n    if (queue.status == 1) {\n        return \"1\"; \n    } else if (queue.status == 2) {\n        return \"2\"; \n    } else if (queue.status == 0) {\n        return \"0\"; \n    }\n    throw new Error(''สถานะคิวผิดพลาด''); \n\n};\n"}', 'c45f66f6-75f7-4b12-be01-39cdaa820a0f', NULL, '89677e2f-7d1b-4e9c-8853-2e23650f65ac', '2024-10-07 07:07:16.141+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
