INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('19731793-b1f5-4cf3-b739-a49f2857a459', 'เช็คคิวเป็นคิว R เพื่อส่งค่า progress title ตัวแทน , ผู้มาตรวจ', 'check_first_progress_agent', 'exec', 37, 1, '{"code":"module.exports = async function(data) {\n    const queue = {{read_data_queue}};\n    let result = \"ผู้มาตรวจ\";\n\n    if (queue.queue_type == \"R\" &&  queue.agent_first_name) {\n        result = ''ตัวแทน'';\n    } \n\n    return {\n        result\n    };\n}\n"}', '69afe606-dcac-4260-b00b-a33d7a902767', NULL, '2722e204-00c5-4b1f-86a8-49b5ffef95ba', '2024-10-28 05:28:57.755+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
