INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('29749c4d-a5ff-49e0-8d9f-989de46f0cc5', 'check_socid_hn', 'check_socid_hn', 'exec', 38, 18, '{"code":"module.exports = async function(data, { services, exceptions } = {}) {\n  // เข้าถึง payload จาก trigger\n  const citizen_id = \"{{read_data_queue.citizen_id}}\";\n  const hn = \"{{read_data_queue.hn}}\";\n\n  // สร้างอาเรย์สำหรับเก็บฟิลเตอร์\n  let filters = [];\n\n  // ตรวจสอบว่า citizen_id ไม่เป็นค่าว่าง\n  if (citizen_id && citizen_id !== \"\") {\n    filters.push({\n      \"soc_id\": {\n        \"_eq\": citizen_id,\n        \"_neq\": \"\"\n      }\n    });\n  }\n\n  // ตรวจสอบว่า hn ไม่เป็นค่าว่าง\n  if (hn && hn !== \"\") {\n    filters.push({\n      \"hn\": {\n        \"_eq\": hn,\n        \"_neq\": \"\"\n      }\n    });\n  }\n\n  // ถ้าไม่มีฟิลเตอร์ใด ๆ แสดงว่าทั้งสองค่าเป็นค่าว่าง\n  if (filters.length === 0) {\n    if (exceptions) {\n      // โยนข้อผิดพลาดเพื่อหยุดการทำงานของ Flow\n      throw new exceptions.Forbidden(\"กรุณาระบุ citizen_id หรือ hn อย่างน้อยหนึ่งค่า\");\n    } else {\n      // ถ้าไม่มี exceptions ให้โยนข้อผิดพลาดทั่วไป\n      throw new Error(\"กรุณาระบุ citizen_id หรือ hn อย่างน้อยหนึ่งค่า\");\n    }\n  }\n\n  // รวมฟิลเตอร์ด้วยตัวดำเนินการ _or\n  const queryFilter = {\n    \"filter\": {\n      \"_or\": filters\n    }\n  };\n\n  // ส่ง queryFilter กลับไปเพื่อใช้ในขั้นตอนถัดไป\n  return queryFilter;\n};\n"}', '184f36b8-e482-4802-a07e-a376177a8938', NULL, '5563ef7b-949d-46c7-b3ae-5d7d187b7e72', '2024-10-15 03:05:14.915+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('5ab2dc21-7380-4ffd-863c-f843022e78db', 'Update Data', 'item_update_p5rf3', 'item-update', 40, 47, '{"collection":"worklist","payload":{"end_time":"{{current_time.currentTime}}"},"key":["{{read_data_queue.worklist[0]}}"],"permissions":"$full"}', '18d43680-4c8a-41a5-9695-5a6b74ee682e', NULL, '89677e2f-7d1b-4e9c-8853-2e23650f65ac', '2024-10-07 07:07:15.913+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('dcd027ff-23db-411b-9580-8711230d5dc9', 'check_last_progress (รับผล)', 'exec_q5wil', 'exec', 59, 82, '{"code":"module.exports = async function(data) {\n\tlet lastProgressTitle = \"{{read_data_last_progress.title}}\"; \n    if (lastProgressTitle != \"รับผล\") {\n        return true; \n    } \n\n    throw new Error(''Progress title ตัวสุดท้ายเป็นรับผล''); \n\n};\n"}', 'f4e2e70b-9c86-484a-b919-1f5d5b9b9be7', NULL, 'e2646ed5-054d-47a0-9237-070f20b2760f', '2024-11-18 06:58:16.295+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('021cd600-e57b-4d74-8ac9-62e50618e7b6', 'check_queue_status_3', 'check_queue_status_2_xybwp', 'exec', 21, 47, '{"code":"module.exports = async function(data) {\n    if ({{check_queue_status_1}} == \"2\") {\n        return true; \n    } \n    throw new Error(''สถานะคิวไม่ใช่เสร็จสิ้น''); \n\n};\n"}', '5ab2dc21-7380-4ffd-863c-f843022e78db', '5d3a3c32-d077-4f1d-b381-5144bf94e416', '89677e2f-7d1b-4e9c-8853-2e23650f65ac', '2024-10-28 03:55:57.063+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('d414e8a3-dee0-4698-b5a0-5e009789a74b', 'last_no_progress', 'last_no_progress', 'exec', 113, 1, '{"code":"module.exports = async function(data) {\n    const progressArray = {{read_data_worklist.progress}};\n\n    // เช็คว่า progress array มีค่าหรือไม่ และมีข้อมูลอยู่\n    if (progressArray && progressArray.length > 0) {\n        // จัดเรียง progress ตามไอดีจากน้อยไปมาก\n        const sortedProgressArray = progressArray.sort((a, b) => a - b);\n\n        // ดึง progress ID ตัวสุดท้ายหลังจากจัดเรียง\n        const lastProgressId = sortedProgressArray[sortedProgressArray.length - 1];\n\n        return {\n            lastProgressId: lastProgressId\n        };\n    } else {\n        return {\n            message: ''No progress data found''\n        };\n    }\n};\n"}', 'b5d95e32-7633-4e47-beaa-c88bdba34352', NULL, '440911df-8ca7-45e3-ad93-9e6587180683', '2024-10-16 07:45:14.249+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
