INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('2f1e2676-5796-4388-8b23-05c7f7829188', 'เช็คว่า status เป็นค่า ยกเลิก ใช่หรือไม่', 'exec_wvr55_crgxd_fxefa_lcuyy', 'exec', 4, 116, '{"code":"module.exports = async function(data) {\n    const statusTriggerFlows = \"{{$trigger.payload.status_trigger_flows}}\";\n    const statusExam = \"{{$trigger.payload.status}}\";\n    \n    //ยกเลิก\n    if (statusExam === \"7\" && statusTriggerFlows !== \"undefined\") {\n        return true; \n    } \n\n    throw new Error(''statusExam ไม่เท่ากับ ยกเลิก''); \n\n};\n"}', 'bb20cfdd-c509-4e7e-9627-bfee9f06bd85', NULL, 'cbd6eeeb-ea02-40ee-be82-36164ee8b18c', '2026-09-21 05:55:41.487+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
