INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('5d198dff-33cd-48e7-b6a0-a3570330adde', 'เช็คว่า queue เป็นตัวแทนมารับผล หรือไม่', 'check_agent', 'exec', 73, 1, '{"code":"module.exports = async function(data) {\n\tconst agentPrefix = \"{{read_data_queue.agent_prefix}}\";\n\tconst agentFirstName = \"{{read_data_queue.agent_first_name}}\";\n\tconst agentLastName = \"{{read_data_queue.agent_last_name}}\";\n\n\tif (agentPrefix && agentFirstName && agentLastName) {\n    \treturn \"ตัวแทน\"; \n\t} else {\n    \treturn \"คนไข้\"; \n\t}\n}"}', '82ef2c5b-32d0-472f-bf70-a29e9e0e2291', NULL, 'e2646ed5-054d-47a0-9237-070f20b2760f', '2024-10-17 09:45:20.99+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
