INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('eabc22bb-d1a1-4854-b26f-8ab18a7f458f', 'check_patient_result_status', 'exec_fq585', 'exec', 37, 1, '{"code":"module.exports = async function(data) {\n    let patientResult = {{read_data_patient_result}};\n\n\t// 4= เสร็จสิ้น\n    if (patientResult.status != \"4\") {\n        return true;\n    }\n\n    throw new Error(''สถานะรับเป็นเสร็จสิ้น'');\n    return false;\n}"}', '8ae6b53f-45ac-4b18-a052-d0a18b5471fd', NULL, '3d941e73-445e-466c-b537-c1fa1d85d7fd', '2024-10-28 03:22:56.27+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('3a6e5e87-5b75-4df3-82f9-b2b11fe7c877', 'check_queue_status_1', 'check_queue_status_1', 'exec', 3, 19, '{"code":"module.exports = async function(data) {\n    let queue = {{$trigger.payload}};\n\t//1 เรียกคิว 2 เสร็จสิ้น\n    if (queue.status == 1) {\n        return 1; \n    } else if (queue.status == 2) {\n        return 2; \n    }else if (queue.status == 0) {\n        return 0; \n    }\n    throw new Error(''สถานะคิวไม่ใช่เรียกแล้ว หรือเสร็จสิ้น รอเรียกคิว''); \n\n};\n"}', '59a17f21-3642-498a-b3fe-85544288f339', NULL, '440911df-8ca7-45e3-ad93-9e6587180683', '2024-10-04 05:39:10.118+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
