INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('8307f441-16ff-495a-81ee-e7d5afb325df', 'สร้าง payload สำหรับ update ข้อมูล', 'create_payload', 'exec', 37, 1, '{"code":"module.exports = async function(data) {\n    const payload = {};\n    const num_of_mam = {{$trigger.payload.num_of_mam}};\n\tconst num_of_spot = {{$trigger.payload.num_of_spot}};\n\tconst num_of_implant = {{$trigger.payload.num_of_implant}};\n\tif(num_of_mam) {\n        payload.num_of_mam = num_of_mam\n    };\n\tif(num_of_spot) {\n        payload.num_of_spot = num_of_spot\n    };\n\tif(num_of_implant) {\n        payload.num_of_implant = num_of_implant\n    }\n\t\n\n\treturn payload;\n}"}', 'df94a8e5-92f4-4f31-93bb-240e94944fee', NULL, '3d94c102-f959-4758-bf95-58c7f165f1d3', '2025-06-18 08:49:33.414+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
