INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('1f81adf9-8311-481d-b8f7-b8d83ff5dcd7', 'check_last_progress (รับผล)', 'check_last_progress', 'exec', 57, 19, '{"code":"module.exports = async function(data) {\n\tlet lastProgressTitle = \"{{read_data_last_progress.title}}\"; \n    if (lastProgressTitle == \"รับผล\") {\n        return true; \n    } \n\n    throw new Error(''Progress title ตัวสุดท้ายไม่ใช่รับผล''); \n\n};\n"}', '963f9585-25e2-4da8-91b7-f974e1f5a8ed', '8f2a3c87-1377-4d95-a75f-548349f88d48', 'e2646ed5-054d-47a0-9237-070f20b2760f', '2024-11-18 05:53:31.366+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
