INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('baa79662-0543-4504-b26f-63aaf1f11ad0', 'สร้าง progress จัดส่งผลตรวจ', 'item_create_rz6s8', 'item-create', 39, 19, '{"collection":"progress","payload":{"title":"เจ้าหน้าที่ Front จัดส่งผลตรวจ","admission_time":"{{current_time.currentTime}}","status":"รอดำเนินการ","department":"Front","worklist":"{{read_data_queue.worklist[0]}}"}}', NULL, NULL, '2e907bc7-59b0-451c-bf25-8bc2cd332ec8', '2024-10-28 04:28:47.603+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
