INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('2da1a53b-1f8b-4aed-9748-9f60ce16e6c1', 'สร้าง doctor_work', 'create_doctor_work', 'item-create', 21, 35, '{"collection":"doctor_work","emitEvents":true,"permissions":"$full","payload":{"doctor":"{{$trigger.payload.bx_doctor}}","appointment":"{{read_nurse_work.appointment}}","exam":"{{read_exam[0].id}}","nurse_work":"{{$trigger.keys[0]}}","status":"1"}}', 'bcea9282-8325-4ede-9acb-e0c0351cb528', NULL, '9b45be8e-0df7-4e1a-b3ca-2a1686ecaba9', '2026-11-17 10:57:09.141+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('3a154f8b-6fe7-4014-a31a-a163f0efe3d8', 'อ่านข้อมูลจาก pacs_sync_info', 'read_pacs_sync_info', 'item-read', 19, 1, '{"key":"{{$last}}","query":{"fields":["id, date_created, accession_id, modality, ris_code","patient.id, patient.date_of_birth, patient.pid, patient.hn, patient.gender","patient.prefix_en, patient.first_name_en,  patient.last_name_en"]},"collection":"pacs_sync_info"}', '74379349-c07a-4b8d-a544-543eff96bce2', NULL, '0aea1f43-6123-4e3b-8bbc-7dcc606e2646', '2026-09-01 09:28:06.695+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
