INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('b16b54a4-fd7f-44ad-8c15-eb0d210127b7', 'อ่านข้อมูล Coordinate', 'read_data_coordinate', 'item-read', 19, 1, '{"collection":"coordinate","key":["{{$trigger.keys[0]}}"],"permissions":"$full"}', '419b1bd0-140a-4e20-bac2-584b353ac34a', NULL, '32de3302-0f95-4186-81e2-955100e34997', '2025-02-06 16:30:04.41+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('b16e6226-a2ad-4a0f-87cb-aa826413f181', 'นำข้อมูลจาก revision 2 ตัวสุดท้าย มาเทียบกัน', 'sort_second_last_data', 'exec', 55, 1, '{"code":"module.exports = async function(data) {\n  try {\n    // ดึงข้อมูลจาก response\n    const data2 = {{request_revisions_appointment.data.data}};\n\n    // ตรวจสอบและกรองข้อมูล null ออก\n    const validData = data2.filter(item => item && item.data && item.data.date_updated);\n\n    // ตรวจสอบว่ามีข้อมูลเพียงพอที่จะนำมาเปรียบเทียบหรือไม่\n    if (validData.length < 2) {\n      throw new Error(\"Not enough valid data for comparison.\");\n    }\n\n    // เรียงลำดับข้อมูลตาม date_updated จากเก่าไปใหม่\n    const sortedData = validData.sort((a, b) => new Date(a.data.date_updated) - new Date(b.data.date_updated));\n\n    // ดึงสองข้อมูลสุดท้าย\n    const secondLast = sortedData[sortedData.length - 2];\n    const last = sortedData[sortedData.length - 1];\n\n    // ฟังก์ชั่นสำหรับแยกวันที่\n    const getDateOnly = (dateTime) => dateTime.split(''T'')[0];\n\n    // แยกวันที่จาก datetime\n    const lastDate = getDateOnly(last.data.appointment_datetime);\n    const secondLastDate = getDateOnly(secondLast.data.appointment_datetime);\n\n    // ตรวจสอบการเปลี่ยนแปลงวันที่\n    const dateChanged = lastDate !== secondLastDate;\n\n    // ตรวจสอบการเปลี่ยนแปลง time_slot\n    const lastTimeSlot = last.data.time_slot;\n    const secondLastTimeSlot = secondLast.data.time_slot;\n    const timeSlotChanged = lastTimeSlot !== secondLastTimeSlot;\n\n    // ส่งข้อมูลไปยัง Flow ถัดไป\n    return {\n      secondLast,\n      last,\n      dateChanged,\n      timeSlotChanged\n    };\n  } catch (error) {\n    console.error(\"Error in script:\", error);\n    throw error; // ส่งต่อข้อผิดพลาดไปยัง Flow\n  }\n};"}', '8ccaffe4-ac01-43bf-bab4-2f5427f4272c', NULL, 'b1e04a8c-e551-468e-b336-820154f3ac1b', '2024-10-03 04:31:50.547+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('da1dc4dc-26b2-4113-a24c-5d6c04381386', 'check_service_type_title', 'check_service_type_title', 'exec', 39, 18, '{"code":"module.exports = async function(data) {\n    if (\"{{read_data_queue.service_type}}\" == \"สร้าง ID ผู้ป่วยใหม่\") {\n        return \"สร้างข้อมูลผู้มาตรวจ\"; \n    } \n    else {\n        return \"เจ้าหน้าที่ Front ถ่ายเพิ่ม\"; \n    } \n};\n"}', '65c2eeeb-4b8c-4e91-aab8-9411cac478e6', NULL, '89677e2f-7d1b-4e9c-8853-2e23650f65ac', '2024-10-28 03:58:11.327+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('c45f66f6-75f7-4b12-be01-39cdaa820a0f', 'check_queue_status_2', 'check_queue_status_2', 'exec', 21, 18, '{"code":"module.exports = async function(data) {\n    if ({{check_queue_status_1}} == \"1\") {\n        return true; \n    } \n    throw new Error(''สถานะคิวไม่ใช่เรียกแล้ว''); \n\n};\n"}', 'da1dc4dc-26b2-4113-a24c-5d6c04381386', '021cd600-e57b-4d74-8ac9-62e50618e7b6', '89677e2f-7d1b-4e9c-8853-2e23650f65ac', '2024-10-07 07:07:16.108+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
