INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('13d6161f-737f-41df-8f21-16876fd9f5ff', 'อ่านข้อมูล appointment', 'read_data_appointment', 'item-read', 3, 19, '{"collection":"appointment","key":["{{read_data_billing.appointment}}"],"permissions":"$full"}', 'da83e3bc-6ba1-4960-b31d-29b343ca41f6', NULL, 'afbac7d9-554e-4ab6-a1c8-cd0a649312ae', '2025-03-10 09:59:46.084+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('7a51392d-35b0-485b-92db-8f027177fdb1', 'check_queue_status_1', 'check_queue_status_1', 'exec', 3, 20, '{"code":"module.exports = async function(data) {\n    let queue = {{read_data_queue}};\n\t//1 เรียกคิว 2 เสร็จสิ้น 0 รอเรียกคิว 4 กำลังดำเนินการ\n    if (queue.status == 0) {\n        return \"0\"; \n    } else if (queue.status == 1) {\n        return \"1\"; \n    } else if (queue.status == 2) {\n        return \"2\"; \n    } else if (queue.status == 4) {\n        return \"4\"; \n    } \n};\n"}', 'c23cbf7f-d3a5-4925-ba2e-f92297cba54f', NULL, 'af896f59-cef0-47ab-b0ac-efdb21df529f', '2024-10-18 02:52:27.051+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('543b9a72-5768-4bc0-8136-8bb385434488', 'เช็คว่า exam เป็นสถานะ รอปรึกษาแพทย์ หรือไม่', 'exec_hb7dh_oxfvj', 'exec', 37, 53, '{"code":"module.exports = async function(data) {\n    const examStatus = \"{{$trigger.payload.status}}\";\n\n    //รอปรึกษาแพทย์\n    if (examStatus === \"2\") {\n        return true;\n    }\n\n    throw new Error(''ไม่ใช่สถานะ รอปรึกษาแพทย์'');\n    return false;\n}"}', 'd3d569a5-5c42-4aa7-89f9-14cd7176625b', NULL, 'e472714e-dd02-4bfc-8038-133053a0a457', '2025-03-18 07:37:47.373+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('ab83ee75-50ac-4b9c-8d45-a8412d5cd7c8', 'เช็คว่า trigger_flows เป็น "doctor_work" หรือไม่ ', 'check_trigger_flows_doctor_work', 'exec', 37, 17, '{"code":"module.exports = async function(data) {\n    const triggerFlows = \"{{$trigger.payload.status_trigger_flows}}\";\n\n    if (triggerFlows !== \"doctor_work\") {\n\t\tthrow new Error(''ไม่มี triggerFlows หรือไม่ใช่ doctor_work'');\n    } \n\n}"}', 'e145b84c-4403-416f-a7f4-eb91c0be5980', NULL, 'd0764ae1-0dd4-43fc-bb30-8ed60868e7b1', '2025-07-16 03:18:56.236+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
