INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('4e50f4f4-2557-4a1e-892e-03e772f9d6a5', 'เช็คว่าเคยทำ mam มาแล้วหรือยัง', 'check_is_mam_done', 'exec', 19, 18, '{"code":"module.exports = async function(data) {\n\tconst currentUltrasoundWork = {{read_current_ultrasound_work}}\n\tconst mamPacsSyncInfos = currentUltrasoundWork?.exam?.pacs_sync_infos?.filter(\n        ({ modality, is_mark_del, end_time }) => modality===\"MG\" && !is_mark_del && end_time\n    ) ?? []\n    \n    if(mamPacsSyncInfos?.length === 0) {\n    \tthrow new Error(''เคสนี้ไม่เคยทำ mam'')\n    }\n\n}"}', '53c6b9fc-8fa0-4fe2-9c48-cf20151e25d3', '665df4b0-a862-47e5-8ef9-37fc04f90fcb', 'b44bbffe-cbe8-4363-86b3-5c5841fd2e0c', '2025-09-05 09:18:10.266+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
