INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('728f0f98-c077-448a-944b-9740b0018744', 'เช็คว่า exam ที่ผูกกับ ultrasound นี้เป็นตัวล่าสุดไหม', 'check_is_lastest_exam', 'exec', 55, 18, '{"code":"module.exports = async function(data) {\n\tconst lastTenExam =  {{read_last_10_examination}};\n\tconst currentExamId = {{read_current_ultrasound.exam}};\n\n\tif (lastTenExam.findIndex(({ id }) => id === currentExamId) !== 0) {\n        throw new Error(''ไม่ใช่ exam ตัวล่าสุดที่ sign to pacs'')\n    }\n}"}', '318742c6-3dd8-490b-a5a5-f2e208602021', NULL, '62c45fee-1f13-4c6f-b11b-d156f06626df', '2025-09-17 07:36:37.885+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
