INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('3ae6685f-b135-4460-8054-e80ea3be05db', 'เช็ค status ของ exam ว่าเป็น "ปิดเคส" ไหม', 'check_exam_status', 'exec', 19, 1, '{"code":"module.exports = async function(data) {\nconst status = \"{{$trigger.payload.status}}\";\n\nconst acceptedStatuses = [\n    \"ส่ง MAM - ปิดเคส\", // เคสถ่าย mam ปกติ\n  \t\"15\", // เคสถ่ายเพิ่ม\n \t\"16\", // เคสปรึกษาแพทย์\n    \"20\" // เคสถ่ายหลัง us\n];\n    \n    if(!acceptedStatuses.includes(status)) {\n      throw new Error(''ไม่ใช่สถานะ ปิดเคส'');\n    }\n\n}"}', 'e10cfe20-5c83-4f56-9630-580c94ee0194', NULL, 'a6078515-a2aa-435a-9862-4abe646ae8cc', '2025-02-25 11:44:45.947+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
