INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('8cf5fa4d-6f3d-41d6-81fd-a0f2ba93301d', 'เช็คว่าเป็นการ assign หมอของเคสเปลี่ยนแพทย์หรือไม่', 'check_status_of_doctor_change', 'exec', 19, 1, '{"code":"module.exports = async function(data) {\n    if (\n      \"{{$trigger.payload.status_trigger_flows}}\" === \"undefined\" ||\n      \"{{$trigger.payload.status}}\" !== \"11\" ||\n      \"{{$trigger.payload.doctor_change}}\" !== \"true\"\n    ) {\n      throw new Error(\"ไม่ใช้การ assign หมอของเคสเปลี่ยนแพทย์\");\n    }\n}"}', 'faea10cd-aa69-4d33-b770-0f224f3f77d6', NULL, '41a5a56f-a402-4c2d-af82-734c4c1b4aaf', '2025-11-12 16:55:50.366+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
