INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('d61ba106-f516-48de-a02a-04ea535174a4', 'return ค่า array ของ ID ทั้งหมดจาก notifications', 'map_ids_notifications', 'exec', 3, 70, '{"code":"module.exports = async function(data) {\n  const notifications = {{read_data_notification}};\n\n  // Extracting the IDs\n  const ids = notifications.map(noti => noti.notification);\n\n  // Function to process IDs (e.g., logging or further processing)\n  function processIds(...ids) {\n    console.log(...ids); // This will log each ID as a separate argument\n    return ids; // or do other operations with the separate IDs\n  }\n\n  return processIds(...ids); // Spread the IDs into separate arguments\n}\n"}', 'd71d902c-f182-4ec8-98dd-1c7498a403dd', NULL, '55b25593-7665-4f37-83f5-9e691af6b979', '2025-07-31 11:25:26.87+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('83ef9e30-dd7d-49c3-9adc-04c19541aa94', 'เข้า Trigger Flow Progress Created', 'trigger_flow_progress_created_nxndg_nvvgg', 'trigger', 75, 67, '{"flow":"91f7c920-9249-42c7-9215-cf7a2a4eb971","payload":"{{create_progress_send_us}}"}', '13f5e1dc-2b60-400f-a62d-e746fef930fa', NULL, 'ed9487b5-5316-42b2-96ee-6c58162b72bb', '2025-09-01 10:00:30.844+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
