INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('a483747f-7f49-4516-9c8d-2ef073721d9b', 'อ่านข้อมูล exam_cost', 'read_data_examination_cost', 'item-read', 21, 52, '{"collection":"exam_costs","permissions":"$full"}', 'efd05623-3596-450e-8cb1-0e983f4c6e6d', NULL, '32de3302-0f95-4186-81e2-955100e34997', '2025-02-19 08:15:04.806+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('68f48c30-c81d-43a1-a183-e7100e34d095', 'return ค่าวัน-เวลาของตอนนี้', 'current_time', 'exec', 37, 1, '{"code":"module.exports = async function(data) {\n    return {\n        currentTime: new Date().toISOString()\n    };\n};"}', '13d6161f-737f-41df-8f21-16876fd9f5ff', NULL, 'afbac7d9-554e-4ab6-a1c8-cd0a649312ae', '2025-03-10 09:59:46.133+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('edc8c116-452e-4650-8bea-100510e807f2', 'คิดเลขใบเสร็จ', 'gen_receipt_number', 'exec', 4, 19, '{"code":"module.exports = async function (data) {\n  const allItems = {{read_all_data_center_income}} || [];\n  const currentItem = {{read_data_center_income}};\n  if (!currentItem || !currentItem.date_created) return {};\n\n  const currentDate = new Date(currentItem.date_created);\n  const buddhistYear = currentDate.getFullYear() + 543;\n  const month = String(currentDate.getMonth() + 1).padStart(2, \"0\");\n  const year = currentDate.getFullYear();\n  const monthIndex = currentDate.getMonth();\n\n  const filteredItems = allItems.filter((item) => {\n    const itemDate = new Date(item.date_created);\n    return (\n      itemDate.getFullYear() === year &&\n      itemDate.getMonth() === monthIndex &&\n      item.receipt_number?.startsWith(`${buddhistYear}/${month}`)\n    );\n  });\n\n  const maxNumber = filteredItems.reduce((max, item) => {\n    const match = item.receipt_number?.match(/-(\\d+)$/);\n    const num = match ? parseInt(match[1], 10) : 0;\n    return Math.max(max, num);\n  }, 0);\n\n  const nextNumber = String(maxNumber + 1).padStart(6, \"0\");\n  const receipt_number = `${buddhistYear}/${month}-${nextNumber}`;\n\n  return {\n    receipt_number,\n  };\n};\n"}', '3d6774bd-b1c7-4046-be66-7e2300af6d08', NULL, 'c14d1c54-2b3b-45d6-a1db-43fc6f5d94b6', '2025-05-05 15:12:39.602+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('e5125879-3f3a-4d0b-96f8-dc76a5187002', 'อ่านข้อมูล Center income', 'read_data_center_income', 'item-read', 19, 1, '{"collection":"center_income","key":["{{$trigger.key}}"],"permissions":"$full"}', '1f29fc1a-4dc5-4030-8363-191baa73f9b9', NULL, 'c14d1c54-2b3b-45d6-a1db-43fc6f5d94b6', '2025-05-05 15:02:13.561+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('37861d8b-26d6-4dec-b64a-6a256596db34', 'check_patient_info', 'check_patient_info', 'exec', 19, 1, '{"code":"module.exports = async function(data) {\n\tlet queue = {{$trigger.payload}}\n\n    if (queue.patient_info) {\n        return true;\n    }\n\n    throw new Error(''Queue not have patient_info'');\n    return false;\n}"}', '46d2e5bb-a790-4335-bd13-a43837e6d80a', NULL, 'df03660a-3cf7-4069-ad4f-0a92fec2ae9e', '2024-12-15 16:06:18.735+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('ea0ba221-8ff0-4e62-a667-ac5d4209eefb', 'อ่านค่า recommend_bx_form ทั้งหมดของเดือนนี้', 'read_recommend_bx_form', 'item-read', 37, 1, '{"permissions":"$full","collection":"recommend_bx_form","query":{"filter":{"date_created":{"_gte":"{{get_date_range.from}}","_lte":"{{get_date_range.to}}"}}}}', '62918153-63fc-4ec4-8ddd-54aae1c7f801', NULL, '784933e7-b375-4551-954b-ab894d350f6c', '2025-09-02 10:32:43.83+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('53f5f969-727e-4ac5-b7a4-f95f66cab980', 'ส่ง id และ status (ใหม่) ออกมา', 'get_doctor_work_data', 'exec', 55, 1, '{"code":"module.exports = async function(data) {\n\tconst targetDoctorWork = {{read_doctor_work[0]}};\n    let newStatus;\n    switch(targetDoctorWork.status){\n        case \"4\": newStatus = \"0\";\n            break;\n    }\n    \n\treturn {\n        id:targetDoctorWork.id, \n        status:newStatus\n    };\n}"}', '2217a3bb-a397-4365-98d7-479c940ea216', NULL, '7ab7b1a9-793a-47ac-9092-675603a60a54', '2025-05-07 08:08:11.596+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('686f8f72-f5e5-423d-9a8c-c29f7d8132fc', 'เช็คว่า progress ตัวสุดท้ายไม่ใช่ เจ้าหน้าที่บันทึกเลขที่ใบเสร็จ', 'exec_5epwde', 'exec', 57, 53, '{"code":"module.exports = async function(data) {\n    let titleProgress = \"{{read_data_last_progress.title}}\";\n\n    if (titleProgress != \"เจ้าหน้าที่บันทึกเลขที่ใบเสร็จ\") {\n        return true;\n    }\n\n    throw new Error(''progress ตัวสุดท้ายคือ เจ้าหน้าที่บันทึกเลขที่ใบเสร็จ'');\n    return false;\n}"}', 'c76bb48f-7f93-4e14-9e87-b0f25209a16e', NULL, 'afbac7d9-554e-4ab6-a1c8-cd0a649312ae', '2025-03-10 12:11:12.746+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('75aae28f-d234-477b-9e9d-6b5d1560ca27', 'เช็คว่า progress ตัวสุดท้ายไม่ใช่แพทย์ส่ง US', 'exec_9j8jk_kduen', 'exec', 21, 67, '{"code":"module.exports = async function(data) {\n\tlet lastProgressTitle = \"{{read_data_last_progress.title}}\"; \n    if (lastProgressTitle != \"แพทย์ส่ง US\") {\n        return true; \n    } \n\n    throw new Error(''Progress title ตัวสุดท้ายคือแพทย์ส่ง US''); \n\n};\n"}', 'ce79afdb-237d-4889-9f12-12b84b9fa9ee', NULL, 'ed9487b5-5316-42b2-96ee-6c58162b72bb', '2025-09-01 10:00:30.98+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
