INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('7af05002-f036-4097-9460-1f18015ada72', 'เช็คว่ามี statusTriggerFlows หรือไม่', 'status_trigger_flows_gysgm', 'exec', 3, 69, '{"code":"module.exports = async function(data) {\n    const statusTriggerFlows = \"{{$trigger.payload.status_trigger_flows}}\";\n    const status = \"{{$trigger.payload.status}}\";\n    const receipt_no = \"{{read_data_billing.receipt_no}}\";\n    \n    //บันทึกผล\n    if (statusTriggerFlows === \"trigger\" && receipt_no != \"null\") {\n        return true; \n    } \n\n    throw new Error(''ไม่มี statusTriggerFlows''); \n\n};\n"}', 'a1636f97-46e6-4846-8479-c705c8c21a87', '06d3eb40-94e1-4bf0-8471-9e203d3ec8a1', 'afbac7d9-554e-4ab6-a1c8-cd0a649312ae', '2025-06-18 17:21:39.254+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
