INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('d0aed853-9e61-4baf-8926-c3c91df65dbd', 'เช็คว่า status เป็นกรณี "รับเคส" หรือไม่', 'check_status_recieve', 'exec', 41, 1, '{"code":"module.exports = async function(data) {\nconst status = \"{{$trigger.payload.status}}\";\n\nconst acceptedStatuses = [\n  \"ส่ง MAM - รับเคส\",\n  \"11\", // spot ก่อน us\n  \"13\", // ปรึกษาแพทย์\n  \"18\"  // spot หลัง us\n];\n    \n    if(!acceptedStatuses.includes(status)) {\n        throw new Error(''ไม่ใช่สถานะ รับเคส'');\n    }\n\n\n}"}', '34a54a3d-c779-4928-a141-00d0bd44d311', 'c4efc049-c7af-483a-8461-3dd682af83fc', '74c5ff61-80ae-49e8-a670-1e23e42a78be', '2025-04-22 12:32:32.752+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
