INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('c4efc049-c7af-483a-8461-3dd682af83fc', 'เช็คว่า status เป็นกรณี "คืนเคส" หรือไม่', 'check_status_return', 'exec', 41, 18, '{"code":"module.exports = async function(data) {\nconst status = \"{{$trigger.payload.status}}\";\n\nconst acceptedStatuses = [\n  \"ส่ง MAM - รอเรียกคิว\",\n  \"10\", // ถ่ายเพิ่มก่อน US - รอเรียกคิว\n  \"3\" // แพทย์ตอบกลับ - รอเรียกคิว\n];\n\n    if(acceptedStatuses.includes(status)) {\n        return true\n    } else {\n        throw new Error(''ไม่ใช่สถานะ คืนเคส'');\n    return false\n    }\n}"}', '767d7834-fffc-4b11-b4cf-18b742d9822e', '23a61051-137a-4bdc-85de-ac1da8bda431', '74c5ff61-80ae-49e8-a670-1e23e42a78be', '2025-04-22 12:49:25.412+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
