INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('37c4e88f-a4d8-4c2f-bdad-28a788940f76', 'เช็คว่ามี triggerFlows และ action หรือไม่', 'trigger_flows_action', 'exec', 19, 1, '{"code":"module.exports = async function(data) {\n    const status_trigger_flows = \"{{$trigger.payload.status_trigger_flows}}\";\n\tconst action = \"{{$trigger.payload.action}}\";\n\n    if (status_trigger_flows === \"undefined\" || action === \"undefined\") {\n        throw new Error(''ไม่มี action หรือ triggerFlows ไม่มีค่า'');\n    }\n}"}', 'ad564ea8-1d44-494a-b088-c5b0a8ceb0f0', NULL, 'b8f2bdb4-070f-41a0-afc6-f5363c254fdc', '2025-07-23 04:20:01.708+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('abffb104-2300-44bf-a38c-db99044a3ee7', 'เช็คว่ามี statusTriggerFlows หรือไม่', 'status_trigger_flows', 'exec', 3, 53, '{"code":"module.exports = async function(data) {\n    const statusTriggerFlows = \"{{$trigger.payload.status_trigger_flows}}\";\n    const status = \"{{$trigger.payload.status}}\";\n    const receipt_no = \"{{read_data_billing.receipt_no}}\";\n    \n    //บันทึกผล\n    if (statusTriggerFlows === \"trigger\" && receipt_no == \"null\") {\n        return true; \n    } \n\n    throw new Error(''ไม่มี statusTriggerFlows''); \n\n};\n"}', '838f0829-3341-40ef-89f7-d6983445ea0a', '7af05002-f036-4097-9460-1f18015ada72', 'afbac7d9-554e-4ab6-a1c8-cd0a649312ae', '2025-03-10 09:59:45.857+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('e273937b-6760-411f-bbd2-c143eb7e2245', 'เช็คว่าเป็น ultrasound เก่า + สถานะเป็น sign to pacs หรือไม่', 'check_prevoius_ultrasound', 'exec', 37, 1, '{"code":"module.exports = async function(data) {\n\tconst today = new Date()\n    const ultrasound = {{read_current_ultrasound}}\n\tconst ultrasound_date = new Date(ultrasound?.date_created)\n    \n\tif (\n  \t\t(today.getUTCFullYear() === ultrasound_date.getUTCFullYear() &&\n    \ttoday.getUTCMonth() === ultrasound_date.getUTCMonth() &&\n    \ttoday.getUTCDate() === ultrasound_date.getUTCDate()) ||\n  \t\tultrasound.state !== \"3\"\n\t) {\n \t\t throw new Error(\"ข้อมูลไม่ตรงตามเงื่อนไข\");\n\t}\n}"}', '7b0984ee-138f-4aa5-9c65-e173b9c5b7cb', NULL, '62c45fee-1f13-4c6f-b11b-d156f06626df', '2025-09-17 05:20:48.406+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
