INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('5b042759-8849-45ec-bf1c-5185520d1f64', 'เช็ค Triggerflows และสถานะ us_work ว่าเป็น รอดำเนินการ ใช่หรือไม่', 'exec_o3yma', 'exec', 37, 1, '{"code":"module.exports = async function(data) {\n\t// รอดำเนินการ\n    const ultrasoundStatus = \"{{$trigger.payload.status}}\";\n\tconst triggerFlows = \"{{$trigger.payload.status_trigger_flows}}\";\n    const acceptanceStatus = [\n        \"0\", // คืนคิว\n        \"7\" // ขอเปลี่ยนเตียง\n    ]\n\n    if ([\"0\",\"7\"].includes(ultrasoundStatus) && triggerFlows !== \"undefined\") {\n        return true;\n    }\n\n    throw new Error(''สถานะไม่ใช่ รอดำเนินการ หรือ  triggerFlows ไม่มีค่า'');\n    return false;\n}"}', '54dbe423-a960-4bab-8716-e176a93d6511', '7767f57f-572b-4354-84ad-608eccd69933', '8dd34a74-0ce8-4d19-b333-786c90851a77', '2025-06-25 02:53:37.627+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
