INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('62918153-63fc-4ec4-8ddd-54aae1c7f801', 'ส่งค่าหมายเลขแบบฟอร์มออกมา', 'get_form_number', 'exec', 55, 1, '{"code":"module.exports = async function(data) {\n\tconst now = new Date();\n    const thisMounth = String(now.getMonth() + 1).padStart(2, \"0\");\n    const thisYear = now.getFullYear() + 543;\n    const order = String({{read_recommend_bx_form}}.length).padStart(6, \"0\");\n    \n\treturn `${thisYear}/${thisMounth}-${order}`;\n}"}', 'b6e61aa7-982a-4458-9146-04b7f7eaa65b', NULL, '784933e7-b375-4551-954b-ab894d350f6c', '2025-09-02 10:52:50.266+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
