INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('defc8da9-0ae5-4e5a-9657-6a1e0c6970b0', 'เช็คว่ามี statusTriggerFlows และ status เป็น รับเคส (US) หรือไม่', 'exec_qg6x7_joxdn', 'exec', 3, 67, '{"code":"module.exports = async function(data) {\n    const statusTriggerFlows = \"{{$trigger.payload.status_trigger_flows}}\";\n    const status = \"{{$trigger.payload.status}}\";\n    \n    //รับเคส(US)\n    if (statusTriggerFlows === \"trigger\" && status === \"11\") {\n        return true; \n    } \n\n    throw new Error(''ไม่มี statusTriggerFlows หรือ status ไม่เท่ากับ 11''); \n\n};\n"}', '75aae28f-d234-477b-9e9d-6b5d1560ca27', '3a4d3f4d-0fc0-45f2-a61a-96c98199710b', 'ed9487b5-5316-42b2-96ee-6c58162b72bb', '2025-09-01 10:00:31.878+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('aa2ce143-e25a-4e07-aea4-569df9111064', 'return ค่าวัน-เวลาของตอนนี้', 'current_time', 'exec', 37, 1, '{"code":"module.exports = async function(data) {\n    return {\n        currentTime: new Date().toISOString()\n    };\n};"}', '69b45fa0-9c5f-48f9-a106-39c3ae282202', NULL, 'ed9487b5-5316-42b2-96ee-6c58162b72bb', '2025-02-26 10:48:49.265+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('7f0dfae3-5bdd-46ac-a883-6769d15551f5', 'สร้าง coordinate ที่ F14 แบบ "ปล่อยเคสกลับบ้าน"', 'create_coordinate_f14', 'item-create', 55, 1, '{"collection":"coordinate","permissions":"$full","emitEvents":true,"payload":{"exam":"{{read_current_ultrasound_work.exam.id}}","appointment":"{{read_current_ultrasound_work.exam.appointment}}","doctor":"{{read_current_ultrasound_work.exam.case_owner_doctor}}","doctor_work":"{{read_current_ultrasound_work.doctor_work}}","status":"2","data_tag":"0","case_tag":"4","reason":"{{$trigger.payload.cancel_reason}}","detail":"{{$trigger.payload.cancel_detail}}","location":"{{read_current_ultrasound_work.location}}","case_owner_staff":"{{$trigger.payload.case_owner_staff}}","case_owner_doctor":"{{read_current_ultrasound_work.exam.case_owner_doctor}}"}}', '4e50f4f4-2557-4a1e-892e-03e772f9d6a5', NULL, 'b44bbffe-cbe8-4363-86b3-5c5841fd2e0c', '2025-09-05 10:18:57.118+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('c76bb48f-7f93-4e14-9e87-b0f25209a16e', 'สร้าง progress บันทึกเลขใบเสร็จ', 'create_progress_save_receipt', 'item-create', 75, 53, '{"payload":{"title":"เจ้าหน้าที่บันทึกเลขที่ใบเสร็จ","admission_time":"{{current_time.currentTime}}","close_case_time":"{{current_time.currentTime}}","status":"รอดำเนินการ","department":"การเงิน","worklist":"{{read_data_queue.worklist[0]}}"},"collection":"progress"}', 'd4a08706-1932-4d2a-8534-ebeb21edbbd1', NULL, 'afbac7d9-554e-4ab6-a1c8-cd0a649312ae', '2025-03-10 09:59:45.692+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('7b5aa404-5fb8-4eea-a4f9-34da82d5dc48', 'เช็คว่าหมอกดรับเคสเอง', 'exec_ml5z2', 'exec', 94, 51, '{"code":"module.exports = async function(data) {\n    const statusTriggerFlows = \"{{$trigger.payload.status_trigger_flows}}\";\n    const self_assign = {{$trigger.payload.self_assign}};\n    \n    if (statusTriggerFlows === \"trigger\" && self_assign === true) {\n        return true; \n    } \n\n    throw new Error(''ไม่มี statusTriggerFlows หรือ หมอไม่ได้กดรับเคสเอง''); \n};\n"}', NULL, '26b2bc43-cf77-465b-b60a-c0a09bfaa4e4', 'ed9487b5-5316-42b2-96ee-6c58162b72bb', '2026-09-21 06:32:28.445+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('2448046c-41e6-4179-bfa1-0adf218e40ae', 'อัพเดทฟิลด์ status, close_case_time ของ progress ตัวสุดท้าย', 'status_close_case_time_progress_gulsg_roxym_vozys', 'item-update', 39, 51, '{"collection":"progress","payload":{"close_case_time":"{{current_time.currentTime}}","status":"เสร็จสิ้น"},"key":["{{last_no_progress.lastProgressId}}"],"permissions":"$full"}', '0d34d7fe-a28d-4c8b-9716-9ebfce149b34', NULL, 'ed9487b5-5316-42b2-96ee-6c58162b72bb', '2025-09-02 02:53:05.007+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('63c4303a-3998-43f8-9820-dbcf009bd10e', 'เช็คว่า progress ตัวสุดท้ายไม่ใช่แพทย์วินิจฉัย', 'exec_9j8jk', 'exec', 21, 51, '{"code":"module.exports = async function(data) {\n\tlet lastProgressTitle = \"{{read_data_last_progress.title}}\"; \n    if (lastProgressTitle != \"แพทย์วินิจฉัย\") {\n        return true; \n    } \n\n    throw new Error(''Progress title ตัวสุดท้ายคือแพทย์วินิจฉัย''); \n\n};\n"}', '2448046c-41e6-4179-bfa1-0adf218e40ae', NULL, 'ed9487b5-5316-42b2-96ee-6c58162b72bb', '2025-05-26 12:53:30.803+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('4724eab2-403d-4a8e-aa39-c59808a0838e', 'สร้างข้อมูล Coordinate', 'create_coordinate', 'item-create', 73, 17, '{"collection":"coordinate","permissions":"$full","emitEvents":true,"payload":{"exam":"{{read_data_doctor_work[0].exam}}","appointment":"{{read_data_doctor_work[0].appointment}}","status":"2","data_tag":"0","case_tag":"3","location":"{{$trigger.payload.location}}"}}', '39f8a264-f903-4b6e-9bf6-a55944886f78', NULL, 'd0764ae1-0dd4-43fc-bb30-8ed60868e7b1', '2025-07-15 14:56:28.619+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
