INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('65bb8d9a-e19e-44f3-8ddb-d04082ec27fc', 'เข้า Trigger Flow ของ read_environment data', 'read_environment', 'trigger', 40, 44, '{"flow":"f5ad1f92-3584-40cb-8931-926f1cd88ff1"}', '1ead5467-a819-4f93-bcc1-de37c73b7290', NULL, '8dd34a74-0ce8-4d19-b333-786c90851a77', '2025-07-04 08:14:16.135+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('541d3ee3-55dd-468c-9303-16a815b012e2', 'อ่านข้อมูล Patient_info', 'read_data_patient_info', 'item-read', 39, 17, '{"collection":"patient_info","key":["{{read_data_appointment.patient_info}}"],"permissions":"$full"}', 'f3cd0901-e20c-42bb-b4f3-c59e113b04d8', NULL, '4978440d-6b21-4b42-bf79-b63cdb9dd1be', '2025-05-09 05:43:38.612+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('a6fd97a2-37b2-496f-93b9-1529bf9afa81', 'เช็ค appointment ว่ารับผล copy_cd ไหม', 'check_copy_cd', 'exec', 21, 19, '{"code":"module.exports = async function(data) {\n    const appointment = {{read_data_appointment}};\n\n    if (Array.isArray(appointment.front_note_1) &&\n        appointment.front_note_1.includes(\"รับผลเป็น CD\")) {\n    return true;\n  }\n\n    throw new Error(''ไม่รับผล CD'');\n    return false;\n}"}', '379b1df9-9555-4bdd-a28b-8fec7a6db122', NULL, '69f5e99d-d7b5-4afd-94ef-770ec1a60747', '2025-04-22 05:57:50.676+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('f8acc5fa-4af4-4279-affa-14b23c36dbf2', 'Check DELETE', 'check_delete', 'exec', 3, 81, '{"code":"module.exports = async function(data) {\n    const copyCdChange = \"{{$trigger.payload.copy_cd}}\";\n    \n    if (copyCdChange === \"DELETE\") {\n        return true; \n    } \n\n    throw new Error(''ไม่ใช่ DELETE''); \n\n};\n"}', '850fc90c-3363-40ca-ac03-3edf2a1a4118', NULL, '4978440d-6b21-4b42-bf79-b63cdb9dd1be', '2025-05-09 05:36:12.105+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('7767f57f-572b-4354-84ad-608eccd69933', 'เช็ค Triggerflows และสถานะ us_work ว่าเป็น ถ่ายสำเร็จ ใช่หรือไม่', 'exec_o3yma_qvlxa', 'exec', 19, 17, '{"code":"module.exports = async function(data) {\n\t// ถ่ายสำเร็จ\n    const ultrasoundStatus = {{$trigger.payload.status}};\n\tconst triggerFlows = \"{{$trigger.payload.status_trigger_flows}}\";\n\n    if (ultrasoundStatus == \"6\" && triggerFlows !== \"undefined\") {\n        return true;\n    }\n\n    throw new Error(''สถานะไม่ใช่ ถ่ายสำเร็จ หรือ  triggerFlows ไม่มีค่า'');\n    return false;\n}"}', 'd9d63157-7f39-401c-ab60-21bf0dc7c7dd', NULL, '8dd34a74-0ce8-4d19-b333-786c90851a77', '2025-07-04 07:08:39.521+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('ece3c6a2-3fb2-4fa2-a6a0-b4d099831021', 'อ่านข้อมูล coordinate', 'read_data_coordinate', 'item-read', 19, 1, '{"collection":"coordinate","key":["{{$trigger.keys[0]}}"],"permissions":"$full"}', 'aa2ce143-e25a-4e07-aea4-569df9111064', NULL, 'ed9487b5-5316-42b2-96ee-6c58162b72bb', '2025-02-26 10:48:49.35+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('18186e5b-aec7-46b5-bb18-a0226cfbb62e', 'return ค่า id ตัวสุดท้ายของ progress', 'last_no_progress', 'exec', 3, 19, '{"code":"module.exports = async function(data) {\n    const progressArray = {{read_data_worklist.progress}};\n\n    // เช็คว่า progress array มีค่าหรือไม่ และมีข้อมูลอยู่\n    if (progressArray && progressArray.length > 0) {\n        // จัดเรียง progress ตามไอดีจากน้อยไปมาก\n        const sortedProgressArray = progressArray.sort((a, b) => a - b);\n\n        // ดึง progress ID ตัวสุดท้ายหลังจากจัดเรียง\n        const lastProgressId = sortedProgressArray[sortedProgressArray.length - 1];\n        \n        const secondLastProgressId = sortedProgressArray.length > 1 \n            ? sortedProgressArray[sortedProgressArray.length - 2] \n            : null; \n\n        return {\n            lastProgressId: lastProgressId,\n            secondLastProgressId: secondLastProgressId\n        };\n    } else {\n        return {\n            message: ''No progress data found''\n        };\n    }\n};\n"}', 'dbcd4000-2aab-4ecf-a67f-e82ea393195d', NULL, 'e2646ed5-054d-47a0-9237-070f20b2760f', '2024-10-16 11:39:20.606+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('82ef2c5b-32d0-472f-bf70-a29e9e0e2291', 'return ค่าวัน-เวลาของตอนนี้', 'current_time', 'exec', 91, 1, '{"code":"module.exports = async function(data) {\n    return {\n        currentTime: new Date().toISOString()\n    };\n};"}', '18186e5b-aec7-46b5-bb18-a0226cfbb62e', NULL, 'e2646ed5-054d-47a0-9237-070f20b2760f', '2024-10-16 11:39:20.68+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('5971225b-7962-49af-b5a3-5ef7b8ea4206', 'เช็คสถานะของ queue ว่าเป็น ยกเลิก ใช่หรือไม่', 'check_queue_status', 'exec', 21, 20, '{"code":"module.exports = async function(data) {\n    let queue = {{read_data_queue}};\n\n    if (queue.status == 3) {\n        return true; \n    } \n    throw new Error(''สถานะคิว ไม่ใช่ยกเลิก''); \n\n};\n"}', 'd34de265-d94c-44cd-95c1-7a5d6b3b3ae9', NULL, '2cf897be-be84-42be-b293-aa16e9f8885f', '2024-10-18 05:55:22.918+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('37089f4f-86f7-4565-9952-a9eb5ea38651', 'return วัน-เวลาของปัจจุบัน', 'current_time', 'exec', 3, 20, '{"code":"module.exports = async function(data) {\n    return {\n        currentTime: new Date().toISOString()\n    };\n};"}', '5971225b-7962-49af-b5a3-5ef7b8ea4206', NULL, '2cf897be-be84-42be-b293-aa16e9f8885f', '2024-10-18 06:03:27.84+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('15da3db4-92d0-4915-97bf-6d3aa45a62c5', 'filter หา center income ที่เป็น copy cd', 'filter_center_income_copy_cd', 'request', 21, 33, '{"url":"https://dev.bis-backoffice.bytebetter.io/items/center_income","headers":[{"header":"Content-Type","value":"application/json"},{"header":"Authorization","value":"Bearer {{read_environment.access_token}}"}],"body":"{\n  \"filter\": {\n    \"id\": {\n      \"_in\": {{read_data_billing.data.center_incomes}}\n    },\n    \"type\": {\n      \"_eq\": 1\n    },\n    \"service_fee\": {\n      \"_eq\": 1\n    }\n  },\n  \"fields\": [\"id\"]\n}\n"}', NULL, NULL, '4978440d-6b21-4b42-bf79-b63cdb9dd1be', '2025-05-26 02:22:40.142+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('2cf6c3c7-5473-40db-918b-20026a2d8ba7', 'เข้า Trigger Flow Read environment data', 'read_environment', 'trigger', 3, 33, '{"flow":"f5ad1f92-3584-40cb-8931-926f1cd88ff1"}', '15da3db4-92d0-4915-97bf-6d3aa45a62c5', NULL, '4978440d-6b21-4b42-bf79-b63cdb9dd1be', '2025-05-26 02:22:40.203+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
