INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('9c34d5cb-4e86-4576-bc98-15ada08dbeef', 'เช็ค action officer', 'check_officer', 'exec', 3, 36, '{"code":"module.exports = async function(data) {\n    const action = \"{{$trigger.action}}\";\n\n    if (action === \"officer\") {\n        return true; \n    }\n\n    throw new Error(''action ไม่ใช่ officer''); \n}"}', '2731ac71-d478-4144-9bb4-8e955f3f08c5', '22d78396-c087-4c64-9bf7-4d9056374427', '89be6643-9611-41be-8186-059689a6c8d3', '2026-06-29 03:23:38.658+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
