INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('6d169668-7aa9-41f6-adf5-98ee8c3f896e', 'return id ของ progress ตัวสุดท้าย', 'last_no_progress', 'exec', 73, 1, '{"code":"module.exports = async function(data) {\n    const progressArray = {{read_data_worklist.progress}};\n\n    // เช็คว่า progress array มีค่าหรือไม่ และมีข้อมูลอยู่\n    if (progressArray && progressArray.length > 0) {\n        // จัดเรียง progress ตามไอดีจากน้อยไปมาก\n        const sortedProgressArray = progressArray.sort((a, b) => a - b);\n\n        // ดึง progress ID ตัวสุดท้ายหลังจากจัดเรียง\n        const lastProgressId = sortedProgressArray[sortedProgressArray.length - 1];\n\n        return {\n            lastProgressId: lastProgressId\n        };\n    } else {\n        return {\n            message: ''No progress data found''\n        };\n    }\n};"}', '17b4d5f1-639e-4108-b79b-336097ca100a', NULL, '2e907bc7-59b0-451c-bf25-8bc2cd332ec8', '2024-10-28 04:28:47.73+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
