INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('6aa00178-227d-4a04-a9e4-8a1cdea3c1de', 'อัพเดต noti ให้เป็นอ่านแล้ว', 'update_notification_read', 'item-update', 55, 1, '{"query":{"filter":{"_and":[{"subject":{"_eq":"ส่งทำ Ultrasound"}},{"to_dept":{"_eq":"US"}},{"appointment":{"_eq":"{{read_current_ultrasound_work.appointment}}"}},{"status":{"_eq":"inbox"}}]}},"payload":{"status":"read"},"emitEvents":true,"permissions":"$full","collection":"notification"}', NULL, NULL, '84da7d5b-50b0-4660-a4af-485543cf73f7', '2025-11-13 03:03:19.572+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('61e3b98c-e518-49a0-9600-e48cc3091635', 'เช็คสถานะ patient_result ว่าเป็น จัดส่งแล้ว หรือไม่', 'check_status_send_snacy', 'exec', 21, 37, '{"code":"module.exports = async function(data) {\n    let patientResult = {{read_data_patient_result}};\n\n    if (patientResult.status == \"5\") {\n        return true;\n    }\n\n    throw new Error(''สถานะไม่ใช่จัดส่งแล้ว'');\n    return false;\n}"}', 'a31e7db7-ae56-4012-8d80-9c6368a68672', NULL, '2e907bc7-59b0-451c-bf25-8bc2cd332ec8', '2024-10-28 04:28:47.565+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
