INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('47c671ed-b692-4e7f-9b1e-0672be9d1b63', 'เช็คว่ามี ultrasound_work ไหม', 'check_ultrasound_work', 'exec', 55, 1, '{"code":"module.exports = async function(data) {\n    const ultrasound_works = {{read_ultrasound_work}} ?? []\n\n\tif(ultrasound_works.length === 0) {\n    \tthrow new Error(''เคสนี้ไม่มี ultrasound_work'')\n    }\n\n\treturn ultrasound_works[0]\n}"}', '209ef837-dda3-4c9f-8428-ef9cc6d682b8', NULL, '95fa6dda-c2a3-43a3-9ff6-dbf26cfb5025', '2025-09-05 11:40:22.98+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
