INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('3755a54d-74a8-45db-8c11-364bb0948e3c', 'เช็คว่าเป็นเคสส่งทำ ultrasound หรือไม่', 'check_is_us', 'exec', 57, 1, '{"code":"module.exports = async function(data) {\n    const isUltrasound = {{$trigger.payload.is_ultrasound}};\n\n    if (!isUltrasound) {\n       throw new Error(''ไม่ใช่เคส ultrasound'');\n    }\n\n}"}', 'c80ec306-91ce-4c7d-a50a-d739013ac9a9', 'b54c528e-42c7-4f7f-a3aa-f8d8f6b335f0', 'e472714e-dd02-4bfc-8038-133053a0a457', '2025-06-10 10:10:41.938+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('1ead5467-a819-4f93-bcc1-de37c73b7290', 'ไปอัพเดต notifications ให้เป็น "achieve"', 'update_notification_achieve', 'request', 58, 44, '{"method":"PATCH","url":"{{read_environment.url}}/notifications/{{read_data_notification.notification}}","headers":[{"header":"Authorization","value":"Bearer {{read_environment.access_token}}"}],"body":"{\n       \"status\": \"archive\"\n}"}', NULL, NULL, '8dd34a74-0ce8-4d19-b333-786c90851a77', '2025-07-04 08:14:16.066+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
