INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('96d74505-3f96-4643-bea6-3f04bff32ba0', 'เข้า Trigger Flow Progress Created (v.ส่ง id)', 'trigger_flow_progress_created_nxndg_ruefc_dogyw_rmugs_eltht', 'trigger', 74, 103, '{"payload":{"action":"doctor","user":"{{read_data_doctor_work.doctor}}","progress":"{{create_progress_mammogram}}"},"flow":"89be6643-9611-41be-8186-059689a6c8d3"}', '99a1e5fc-14b4-4523-8a21-23e63668deb6', NULL, '7f07d6c2-0785-4b82-b2ba-4003555b0576', '2026-06-29 11:31:23.643+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('90636ef6-44fb-42e6-b4d9-a4c1832c9aab', 'อัพเดทฟิลด์ status, close_case_time ของ progress ตัวสุดท้าย', 'status_close_case_time_progress_gulsg_roxym_vozys_drvte_wtvkm', 'item-update', 21, 81, '{"permissions":"$full","payload":{"close_case_time":"{{current_time.currentTime}}","status":"เสร็จสิ้น"},"collection":"progress","key":["{{last_no_progress.lastProgressId}}"]}', 'f767d8b7-aa3f-47d9-b10e-9036d8b5be36', NULL, '38e52e80-eabb-4db2-8ee3-6de19379ff4f', '2025-09-03 01:53:20.27+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('742cc2f8-c972-45e7-8c70-fcaf24f13a99', 'เช็คว่ามี triggerFlows และ status ว่าเป็น ขอเปลี่ยนแพทย์ ใช่หรือไม่', 'exec_3f9bu', 'exec', 37, 1, '{"code":"module.exports = async function(data) {\n    const status_trigger_flows = \"{{$trigger.payload.status_trigger_flows}}\";\n\tconst status = \"{{read_data_ultrasound_work.status}}\";\n\n    //ขอเปลี่ยนแพทย์\n    if (status_trigger_flows === \"undefined\" || status !== \"9\") {\n        throw new Error(''status ไม่ใช่ ขอเปลี่ยนแพทย์ หรือ triggerFlows ไม่มีค่า'');\n    }\n}"}', '382cae8e-eb2a-4d2b-9dcd-31285fb4a690', NULL, '55b25593-7665-4f37-83f5-9e691af6b979', '2025-07-25 10:00:40.323+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('1a9c5c91-9c11-4904-8cce-8b42f14d3364', 'เข้า Trigger Flow Progress Created', 'trigger_flow_progress_created_ttvvk_frisb', 'trigger', 94, 84, '{"flow":"91f7c920-9249-42c7-9215-cf7a2a4eb971","payload":"{{create_progress_send_doctor}}"}', NULL, NULL, 'cbd6eeeb-ea02-40ee-be82-36164ee8b18c', '2025-02-24 01:59:00.185+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('54194ca9-bc82-4954-a334-fc5a31dc52ef', 'เช็คว่าสถานะ Coordinat ถูกอัพเดทเป็น รับเคสแล้ว ใช่หรือไม่', 'check_status_coordinate', 'exec', 19, 18, '{"code":"module.exports = async function(data) {\n    let payload = {{$trigger.payload}};\n\tconst acceptanceStatuses = [\"1\",\"9\",\"11\"]\n\n\t// \"1\" = รับเคสแล้ว\n\t// \"9\" = รับเคสแล้ว(ปรึกษาแพทย์)\n\t// \"11\" = รับเคสแล้ว (US)\n    // \"12\" = เปลี่ยนแพทย์ US\n    if (acceptanceStatuses.includes(payload.status) && payload.status) {\n        return true;\n    }else if (payload.status == 12 && payload.action !== \"คืนเคส\") {\n        return true;\n    }\n\n    throw new Error(''coordinate ไม่ใช่สถานะ รับเคสแล้ว'');\n    return false;\n}"}', 'e4322816-86bb-49a7-aa93-300cf7e10ee0', 'f9865b18-2aa1-40ee-85ac-17e423dfe7dd', 'baa6bf9a-4a45-475e-9aa9-93d402672662', '2025-01-28 13:33:02.085+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('c24d515b-ac1c-4334-94f2-99399e1044ee', 'หน่วงเวลาเปลี่ยนสถานะ', 'set_time_out_examination', 'sleep', 37, 18, '{"milliseconds":10000}', '8ac1acd0-96af-4c40-a6ef-30930492c1e4', NULL, 'd555b629-b0a2-4177-a879-10f65d083aaa', '2024-12-18 01:57:02.037+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
