INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('ce671c3a-a057-4f0a-87d1-857b2c40da9c', 'read_last_examination', 'read_last_examination', 'item-read', 21, 52, '{"collection":"examination","query":{"filter":{"patient":{"_eq":"{{read_appointment[0].patient_info}}"}},"sort":["-created_date"],"offset":1,"limit":1}}', 'e23c300e-c0ee-4a50-aaed-441c7026ab32', NULL, 'd555b629-b0a2-4177-a879-10f65d083aaa', '2024-12-18 02:17:49.015+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('00d43bb2-6e3f-4340-a071-5ecd2e288d84', 'check_queue_m', 'check_queue_m', 'exec', 91, 1, '{"code":"module.exports = async function(data) {\n    let queue = {{read_data_queue}};\n\n    if (queue.queue_type == \"M\") {\n        return true;\n    }\n\n    throw new Error(''queue_type not M'');\n    return false;\n}"}', '7a51392d-35b0-485b-92db-8f027177fdb1', NULL, 'af896f59-cef0-47ab-b0ac-efdb21df529f', '2024-10-18 02:52:27.108+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('5cef6beb-e3ce-4311-9698-64448f0104d9', 'เช็คว่ามี ultrasound_work ส่งมาไหม', 'has_ultrasound_work', 'exec', 19, 1, '{"code":"module.exports = async function(data) {\n    if(\"{{$trigger.payload.ultrasound_work}}\" !== \"undefined\") {\n    \tthrow new Error(''ไม่ใช่เคสจากหน้าหมอ'')\n    }\n}"}', 'c1d46765-2a91-4f98-a146-1e34421cf023', NULL, '95fa6dda-c2a3-43a3-9ff6-dbf26cfb5025', '2025-09-05 11:29:18.379+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('3e774713-7aae-442a-9f89-49eec553fcf2', 'อัพเดทข้อมูล notifications', 'notifications_update', 'request', 35, 50, '{"method":"PATCH","url":"{{read_environment.url}}/notifications","body":"{\n    \"keys\": {{map_ids_notifications}},\n    \"data\": {\n        \"status\": \"archive\",\n        \"stop\": true\n    }\n}","headers":[{"header":"Authorization","value":"Bearer {{read_environment.access_token}}"}]}', NULL, NULL, '5b6e538c-4ccb-4ce0-b266-b48257d08bf6', '2025-07-17 03:08:07.326+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('bc6b8896-d250-474f-9739-2c14e44166ef', 'เช็คว่ามี statusTriggerFlows และสถานะเป็น ทำ Mammogram หรือไม่', 'status_trigger_flows_status_signtopacs_ferrt_zpbkc_rhxej', 'exec', 3, 103, '{"code":"module.exports = async function(data) {\n    const statusTriggerFlows = \"{{$trigger.payload.status_trigger_flows}}\";\n    const status = \"{{$trigger.payload.status}}\";\n    \n    //ทำ Mammogram หรือ ทำ mam หลัง us\n    if ((status === \"4\" || status === \"12\") && statusTriggerFlows !== \"undefined\") {\n        return true; \n    } \n\n    throw new Error(''ไม่มี statusTriggerFlows หรือ status ไม่ใช่ ทำ Mammogram''); \n\n};\n"}', '4faa0d8b-c341-4b29-8570-4524d9732cce', NULL, '7f07d6c2-0785-4b82-b2ba-4003555b0576', '2025-09-12 02:32:58.626+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('db84d91a-9199-4bba-a8c8-3f0d95f887a8', 'ลบเวลาเริ่มใน pacs_sync_info ที่เกี่ยวข้องทั้งหมด', 'delete_all_pacs_sync_info_start_time', 'item-update', 55, 1, '{"query":{"filter":{"_and":[{"modality":{"_eq":"US"}},{"is_mark_del":{"_eq":false}},{"exam":{"_eq":"{{read_current_ultrasound_work.exam}}"}},{"end_time":{"_null":true}}]}},"emitEvents":true,"collection":"pacs_sync_info","payload":{"start_time":null}}', NULL, NULL, '9fefa146-297d-4afd-b1d6-0710f75a25c8', '2025-11-21 02:34:20.615+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('38ba3113-40c8-42db-866d-3d46c9fda454', 'เช็คว่า bx_status = 25 ใช่หรือไม่', 'check_send_us', 'exec', 19, 1, '{"code":"module.exports = async function (data) {\n  const p = data.$trigger.payload;\n  if (\n    String(p.bx_status) !== \"25\" ||\n    p.status_trigger_flows !== \"trigger\" ||\n    !p.bx_doctor\n  ) {\n    throw new Error(\"ไม่ใช่เคสพยาบาลส่งถ่าย US ก่อนเจาะ\");\n  }\n  return true;\n};\n"}', '9a362427-5210-45d3-9e4c-d7e62b965312', NULL, '9b45be8e-0df7-4e1a-b3ca-2a1686ecaba9', '2026-11-17 10:57:11.147+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('09a14f22-5260-410b-8d92-f58dcc2abe34', 'อัพเดทข้อมูล Coordinate', 'coordinate', 'item-update', 3, 37, '{"collection":"coordinate","payload":{"status":"12","data_tag":"1","detail":"{{read_data_ultrasound_work.note_us}}","doctor":"{{read_data_doctor_work.doctor}}","doctor_work":"{{read_data_doctor_work.id}}"},"key":["{{read_data_coordinate[0].id}}"],"permissions":"$full","emitEvents":true}', '5e6d7c12-f3fe-4f83-a053-35c37c7e7783', NULL, '55b25593-7665-4f37-83f5-9e691af6b979', '2025-07-30 03:14:33.457+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('382cae8e-eb2a-4d2b-9dcd-31285fb4a690', 'อ่านข้อมูล Doctor_work', 'read_data_doctor_work', 'item-read', 3, 19, '{"permissions":"$full","collection":"doctor_work","key":["{{read_data_ultrasound_work.doctor_work}}"]}', '21336352-4333-4015-bd6b-5cdeb3b298d1', NULL, '55b25593-7665-4f37-83f5-9e691af6b979', '2025-07-29 04:12:55.153+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('f02e6194-90b6-41b7-9d05-b1b0c56c7a73', 'อ่าน ultrasound_work', 'read_current_ultrasound_work', 'item-read', 37, 1, '{"permissions":"$full","collection":"ultrasound_work","key":"{{$trigger.keys[0]}}"}', 'db84d91a-9199-4bba-a8c8-3f0d95f887a8', NULL, '9fefa146-297d-4afd-b1d6-0710f75a25c8', '2025-11-21 02:26:07.023+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('037668f4-9ddd-44ad-ad81-a8c0a2ccade4', 'เช็คว่า status coordinate เป็นอะไรแล้ว return status ของ doctor_work ออกไป', 'check_status_coordinated', 'exec', 55, 1, '{"code":"module.exports = async function(data) {\n    const doctor_consult = {{$trigger.payload.doctor_consult}};\n\tconst coordinate_status = {{$trigger.payload.status}};\n\tconst action = \"{{$trigger.payload.action}}\";\n\tconst doctor_change = {{$trigger.payload.doctor_change}};\n\n    let status = \"\";\n\tlet doctorChange = false;\n\n\tif(doctor_change){\n        doctorChange = doctor_change;\n    }\n    if (doctor_consult) {\n        status = \"5\";\n    } else {\n        if (coordinate_status === 1 || (coordinate_status === 12 && action !== \"คืนเคส\")) {\n            // coordinate_status === 1: รับเคสแล้ว\n            // coordinate_status === 12: เปลี่ยนแพทย์ US\n        \tstatus = \"0\"\n        } else if (coordinate_status === 11) {\n            // coordinate_status === 11: รับเคสแล้ว (US)\n            status = \"1\"\n        }\n    }\n\n    return {\n        status,\n        doctorChange\n    };\n}\n"}', '54194ca9-bc82-4954-a334-fc5a31dc52ef', NULL, 'baa6bf9a-4a45-475e-9aa9-93d402672662', '2025-04-04 08:47:13.858+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('e511b6f6-9131-44ec-9100-265b1de52c1d', 'check_information_type', 'check_information_type', 'exec', 57, 19, '{"code":"module.exports = async function(data) {\n    const informationType = \"{{read_data_queue.information_type}}\";\n    let result;\n\n    if (informationType === ''คนทั่วไป'') {\n        result = ''คนทั่วไปติดต่อสอบถาม'';\n    } else if (informationType === ''ผู้มาตรวจ'') {\n        result = ''ผู้มาตรวจติดต่อสอบถาม'';\n    } else {\n        result = ''ไม่ตรงกับเงื่อนไขที่กำหนด'';\n    }\n\n    return {\n        result\n    };\n}\n"}', '0dcf1930-8eaa-4091-ac22-4c620edb0f10', NULL, '2770ae3f-8314-4d3f-a4f8-4d58da1ec279', '2024-10-16 06:07:36.038+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('a7612dcc-1ccb-4cff-addd-a7386682d468', 'update status และล้าง doctor_work ออก', 'update_status', 'item-update', 56, 18, '{"payload":{"status":"{{$trigger.payload.status}}","doctor_work":null},"collection":"notification","permissions":"$full","emitEvents":true,"key":["{{read_data_notification[0].id}}"]}', NULL, NULL, '4c95d232-9f2a-49cd-8d54-da7d96c85f9e', '2025-06-30 11:13:03.877+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('9da8aec5-9cf5-44d5-924b-d180391029d2', 'check_queue_s', 'check_queue_s', 'exec', 91, 1, '{"code":"module.exports = async function(data) {\n    let queue = {{read_data_queue}};\n\n    if (queue.queue_type == \"S\") {\n        return true;\n    }\n\n    throw new Error(''queue_type not S'');\n    return false;\n}"}', 'fdf3b17e-b70b-4de2-bc84-8ee938c1b1fd', NULL, '2770ae3f-8314-4d3f-a4f8-4d58da1ec279', '2024-10-07 06:15:51.347+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('91ebada2-4f75-450a-a23b-d9944c01ba56', 'เช็คว่ามี examination หรือยัง', 'check_exam', 'exec', 3, 35, '{"code":"module.exports = async function (data) {\n  const exam = data.read_exam?.[0];\n  if (!exam?.id) throw new Error(\"นัดนี้ยังไม่มี examination\");\n  return true;\n};\n"}', '2da1a53b-1f8b-4aed-9748-9f60ce16e6c1', NULL, '9b45be8e-0df7-4e1a-b3ca-2a1686ecaba9', '2026-11-17 10:57:09.396+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('277135a6-a366-4017-8ca0-5a509b9692a1', 'อัพเดทฟิลด์ doctor ของ progress', 'item_update_doctor', 'item-update', 21, 52, '{"collection":"progress","permissions":"$full","payload":{"doctor":"{{query_user.data.data.first_name}} {{query_user.data.data.last_name}}"},"key":["{{read_data_progress.id}}"]}', NULL, NULL, '89be6643-9611-41be-8186-059689a6c8d3', '2026-06-29 03:23:38.326+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('22d78396-c087-4c64-9bf7-4d9056374427', 'เช็ค action doctor', 'check_doctor', 'exec', 3, 52, '{"code":"module.exports = async function(data) {\n    const action = \"{{$trigger.action}}\";\n\n    if (action === \"doctor\") {\n        return true; \n    }\n\n    throw new Error(''action ไม่ใช่ doctor''); \n}"}', '277135a6-a366-4017-8ca0-5a509b9692a1', NULL, '89be6643-9611-41be-8186-059689a6c8d3', '2026-06-29 03:23:38.353+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('a7c71161-35c4-4810-9446-3d678e707998', 'อ่านข้อมูล examination', 'read_exam', 'item-read', 39, 19, '{"permissions":"$full","collection":"examination","query":{"filter":{"_and":[{"appointment":{"_eq":"{{read_nurse_work.appointment}}"}},{"_or":[{"is_duplicate":{"_null":true}},{"is_duplicate":{"_eq":false}}]}]},"fields":["id","location"],"sort":["-id"],"limit":1}}', '91ebada2-4f75-450a-a23b-d9944c01ba56', NULL, '9b45be8e-0df7-4e1a-b3ca-2a1686ecaba9', '2026-11-17 10:57:09.766+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('8a4decb4-5288-4845-878c-10381a0a2c87', 'เช็ค triggerFlows และ action ว่ามีค่าหรือไม่', 'trigger_flows_action', 'exec', 37, 1, '{"code":"module.exports = async function(data) {\n    const action = \"{{$trigger.payload.action}}\";\n\tconst triggerFlows = \"{{$trigger.payload.status_trigger_flows}}\";\n\n    if (action === \"undefined\" || triggerFlows === \"undefined\") {\n        throw new Error(''ไม่มี action หรือ triggerFlows ไม่มีค่า'');\n    }\n}"}', '98980d81-f462-42be-a800-6e3fc96d3bd9', NULL, '5b6e538c-4ccb-4ce0-b266-b48257d08bf6', '2025-07-17 03:08:07.691+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('c10c1486-f31f-4c37-a478-7231340e35b5', 'อ่านข้อมูล Coordinate', 'read_data_coordinate', 'item-read', 39, 19, '{"permissions":"$full","collection":"coordinate","key":[],"query":{"filter":{"_and":[{"date_created":{"_gte":"{{current_day.today_start}}"}},{"date_created":{"_lt":"{{current_day.today_end}}"}},{"appointment":"{{read_data_ultrasound_work.appointment}}"},{"exam":"{{read_data_ultrasound_work.exam}}"}]}}}', '09a14f22-5260-410b-8d92-f58dcc2abe34', NULL, '55b25593-7665-4f37-83f5-9e691af6b979', '2025-07-30 03:13:39.053+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('d95d5fca-0d3b-4338-99da-6037a1299825', 'เช็คว่าเป็นเคสเปลี่ยนเตียง/แพทย์หรือไม่', 'check_is_change', 'exec', 19, 1, '{"code":"module.exports = async function(data) {\n\tconst changeStatus = \"{{$trigger.payload.status}}\"\n    const trigger = \"{{$trigger.payload.status_trigger_flows}}\"\n\t\n    if(![\"7\",\"9\"].includes(changeStatus) || trigger === \"undefined\"){\n        throw new Error(''ไม่ใช่เคสเปลี่ยนเตียง/แพทย์'')\n    }\n}"}', 'f02e6194-90b6-41b7-9d05-b1b0c56c7a73', NULL, '9fefa146-297d-4afd-b1d6-0710f75a25c8', '2025-11-21 02:26:07.039+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('7cc45765-3563-48b4-8dbe-0a2098211b4d', 'เช็คว่า หมอปล่อยกลับบ้านที่ Location ics ใช่หรือไม่', 'exec_758kk_uzkbh_dwiab', 'exec', 40, 20, '{"code":"module.exports = async function(data) {\n    const location = \"{{$trigger.payload.location}}\";\n\n    //3 = ics\n    if (location === \"3\") {\n        return true;\n    }\n\n    throw new Error(''ไม่ใช่ location ics'');\n    return false;\n}"}', '4e9ef285-0c71-4b5c-a9a2-5a8acce37e89', '7ed20ba4-a505-428d-8fc5-dbc5b22d7875', 'cdfc74cd-8e37-4fbd-b333-622e244a8e63', '2026-09-25 03:49:05.366+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('ef0b9191-7acd-4125-a026-aab20927b81d', 'อัพเดทเวลาถ่ายเพิ่ม', 'item_update_cuya6', 'item-update', 37, 17, '{"collection":"pacs_sync_info","permissions":"$full","emitEvents":true,"key":[],"payload":"{{check_pacs_sync_info_us}}"}', NULL, NULL, 'f41fb7e9-e20d-405f-955d-3e03d7bf74a3', '2025-07-08 06:46:17.75+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('0fa988ab-3f45-446e-aa17-1ffaba583b41', 'เช็ค Triggerflows และสถานะ us_work ว่าเป็น เริ่มถ่าย ใช่หรือไม่', 'exec_7u3kb', 'exec', 19, 1, '{"code":"module.exports = async function(data) {\n\t// เริ่มถ่าย\n    const ultrasoundStatus = {{$trigger.payload.status}};\n\tconst triggerFlows = \"{{$trigger.payload.status_trigger_flows}}\";\n\n    if (ultrasoundStatus == \"4\" && triggerFlows !== \"undefined\") {\n        return true;\n    }\n\n    throw new Error(''สถานะไม่ใช่ เริ่มถ่าย หรือ  triggerFlows ไม่มีค่า'');\n    return false;\n}"}', 'b0682e18-4238-41dd-8f50-cb749206d544', NULL, 'f41fb7e9-e20d-405f-955d-3e03d7bf74a3', '2025-07-08 06:19:36.424+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('ac0dbe08-f44f-42c0-bb31-c678c9c01c59', 'เช็คว่ามี doctor_work หรือยัง', 'check_no_doctor_work', 'exec', 21, 19, '{"code":"module.exports = async function (data) {\n  const list = data.read_doctor_work;\n  if (Array.isArray(list) && list.length > 0) {\n    throw new Error(\"nurse_work นี้มี doctor_work อยู่แล้ว\");\n  }\n  return true;\n};\n"}', 'a7c71161-35c4-4810-9446-3d678e707998', NULL, '9b45be8e-0df7-4e1a-b3ca-2a1686ecaba9', '2026-11-17 10:57:10.269+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('9a362427-5210-45d3-9e4c-d7e62b965312', 'อ่านข้อมูล nurse_work', 'read_nurse_work', 'item-read', 37, 1, '{"permissions":"$full","collection":"nurse_work","query":null,"key":["{{$trigger.keys[0]}}"]}', '8f66785c-e989-43e6-bbcf-86eac55ddfa7', NULL, '9b45be8e-0df7-4e1a-b3ca-2a1686ecaba9', '2026-11-17 10:57:10.861+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('781dd8e5-109b-4eef-b37c-1387ed408406', 'return id ของ progress ตัวสุดท้าย', 'last_no_progress', 'exec', 55, 1, '{"code":"module.exports = async function(data) {\n    const progressArray = {{read_data_worklist.progress}};\n\n    // เช็คว่า progress array มีค่าหรือไม่ และมีข้อมูลอยู่\n    if (progressArray && progressArray.length > 0) {\n        // จัดเรียง progress ตามไอดีจากน้อยไปมาก\n        const sortedProgressArray = progressArray.sort((a, b) => a - b);\n\n        // ดึง progress ID ตัวสุดท้ายหลังจากจัดเรียง\n        const lastProgressId = sortedProgressArray[sortedProgressArray.length - 1];\n\n        return {\n            lastProgressId: lastProgressId\n        };\n    } else {\n        return {\n            message: ''No progress data found''\n        };\n    }\n};"}', '37089f4f-86f7-4565-9952-a9eb5ea38651', NULL, '2cf897be-be84-42be-b293-aa16e9f8885f', '2024-10-18 06:01:01.658+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('9bac2d89-e960-4aad-ab39-a41b926e9aca', 'อ่านข้อมูล queue ที่ถูก trigger', 'read_data_queue', 'item-read', 19, 1, '{"collection":"queue","key":["{{$trigger.keys[0]}}"],"permissions":"$full"}', '29b22aee-3c8e-4f10-9305-37d858f8cea3', NULL, '2cf897be-be84-42be-b293-aa16e9f8885f', '2024-10-17 11:03:29.424+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('8271f639-cbfb-4902-b3a9-8fe17357924b', 'สร้าง progress แจ้งชำระเงิน', 'create_progress_send_doctor', 'item-create', 39, 54, '{"payload":{"title":"เจ้าหน้าที่ Front(F14) แจ้งให้ไปชำระเงิน","admission_time":"{{current_time.currentTime}}","status":"รอดำเนินการ","department":"Front(F14)","worklist":"{{read_data_queue.worklist[0]}}"},"collection":"progress"}', '8a1c6a8f-4841-4286-8dda-d0d896868237', NULL, '7f07d6c2-0785-4b82-b2ba-4003555b0576', '2025-03-08 15:48:23.471+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('c41dd34f-b59d-4571-82e8-8c04a7d7de83', 'หา pacs_sync_info ของ US', 'check_pacs_sync_info_us', 'exec', 19, 17, '{"code":"module.exports = async function (data) {\n  const pacsData = {{read_data_pacs_sync_info}} ?? [];\n\n  const target = pacsData.filter(\n    (item) => item.modality === \"US\" && \n      item.is_mark_del === false &&\n      !item.start_time && \n      !item.end_time\n  );\n\n  if (target.length === 0) {\n  \tthrow new Error(''ไม่พบ pacs_sync_info ของ us'')\n  };\n\n  return target.map(({ id }) => ({\n  \t  id,\n      start_time: new Date().toISOString()\n    })\n  )\n};"}', 'ef0b9191-7acd-4125-a026-aab20927b81d', NULL, 'f41fb7e9-e20d-405f-955d-3e03d7bf74a3', '2025-07-08 06:34:48.778+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('e10cfe20-5c83-4f56-9630-580c94ee0194', 'เช็ค confirm จำนวนรูป', 'return_confirm_pic_values', 'exec', 37, 1, '{"code":"module.exports = async function(data) {\n\tlet confirm_num_of_mam = 0;\n    let confirm_num_of_spot = 0;\n    let confirm_num_of_implant = 0;\n    \n    if({{$trigger.payload.confirm_num_of_mam}} !== undefined) {\n        confirm_num_of_mam = {{$trigger.payload.confirm_num_of_mam}}\n    }\n\n\tif({{$trigger.payload.confirm_num_of_spot}} !== undefined) {\n        confirm_num_of_spot = {{$trigger.payload.confirm_num_of_spot}}\n    }\n    \n    if({{$trigger.payload.confirm_num_of_implant}} !== undefined) {\n        confirm_num_of_implant = {{$trigger.payload.confirm_num_of_implant}}\n    }\n    \n\treturn {\n        confirm_num_of_mam,\n        confirm_num_of_spot,\n        confirm_num_of_implant,\n    };\n}"}', '2160b79a-b00f-4a2e-bbce-aa218100fc4f', NULL, 'a6078515-a2aa-435a-9862-4abe646ae8cc', '2025-04-30 02:22:14.325+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('f9e05871-9549-4fd8-b879-9c0bbbf41665', 'อ่านข้อมูล pacs_sync_info', 'read_data_pacs_sync_info', 'item-read', 21, 68, '{"permissions":"$full","collection":"pacs_sync_info","query":{"filter":{"exam":{"_eq":"{{read_data_ultrasound_work.exam}}"},"_or":[{"is_mark_del":{"_eq":false}},{"is_mark_del":{"_null":true}}]}}}', '8a8e99d3-f47a-461b-a2f5-28069795c100', NULL, '52bed9fc-4f3a-4b41-9c82-07cea484cb76', '2025-07-06 04:21:38.03+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('69b45fa0-9c5f-48f9-a106-39c3ae282202', 'อ่านข้อมูล appointment', 'read_data_appointment', 'item-read', 3, 18, '{"collection":"appointment","key":["{{read_data_coordinate.appointment}}"],"permissions":"$full"}', '92d73fb2-cb8e-49d9-b69d-c9cfda1be346', NULL, 'ed9487b5-5316-42b2-96ee-6c58162b72bb', '2025-02-26 10:48:49.238+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('21336352-4333-4015-bd6b-5cdeb3b298d1', 'return ค่าของวันนี้', 'current_day', 'exec', 21, 19, '{"code":"module.exports = async function(data) {\n  const now = new Date();\n\n  // เวลาเริ่มต้นของวันนี้ (00:00:00.000)\n  const startOfToday = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 0, 0, 0);\n\n  // เวลา 23:59:59.999 ของวันนี้ (สิ้นสุดวัน)\n  const endOfToday = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 23, 59, 59, 999);\n\n  return {\n    today_start: startOfToday.toISOString(),\n    today_end: endOfToday.toISOString()\n  };\n};\n"}', 'c10c1486-f31f-4c37-a478-7231340e35b5', NULL, '55b25593-7665-4f37-83f5-9e691af6b979', '2025-07-31 04:12:38.446+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('e8935944-6534-41f1-a15c-15a42517f7ed', 'สร้าง ultrasound_work ใหม่', 'create_ultrasound_work', 'item-create', 129, 1, '{"collection":"ultrasound_work","emitEvents":true,"payload":{"exam":"{{read_data_examination.id}}","appointment":"{{read_data_examination.appointment}}","doctor_work":"{{read_doctor_work[0].id}}","doctor_change":"{{read_doctor_work[0].doctor_change}}","location":"{{read_data_examination.location}}"}}', NULL, NULL, 'e472714e-dd02-4bfc-8038-133053a0a457', '2025-08-26 11:19:13.667+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('8b5dacae-859b-4aa5-aa08-623eacefbf16', 'เช็คว่า F14 Report คือ ยกเลิกเคส หรือไม่', 'check_cancel_case_report', 'exec', 38, 55, '{"code":"module.exports = async function(data) {\n    const F14Reason = \"{{$trigger.payload.reason}}\";\n    let status = \"null\";\n\n    //ยกเลิกเคส\n    if(F14Reason === \"1\"){\n        status = 5;\n    }\n    else if(F14Reason === \"2\"){\n        status = 6;\n    }\n\n    return {\n        status: status\n    };\n\n}"}', NULL, NULL, 'cdfc74cd-8e37-4fbd-b333-622e244a8e63', '2025-03-18 08:30:47.213+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('36bbf4da-28bd-4ec2-aad9-29dbfbc33b67', 'อ่านข้อมูล queue', 'read_data_queue', 'item-read', 57, 53, '{"permissions":"$full","collection":"queue","key":["{{read_data_appointment.queue[0]}}"]}', NULL, NULL, '55b25593-7665-4f37-83f5-9e691af6b979', '2025-10-24 10:50:11.917+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('ce63b7a1-d71c-4e0e-8c5a-492052c83732', 'อ่านข้อมูล examination', 'read_data_examination', 'item-read', 21, 17, '{"permissions":"$full","collection":"examination","key":["{{read_data_ultrasound_work.exam}}"],"query":{"fields":["spot_technicians.directus_users_id.id","*"]}}', 'c2af3dfb-6550-414f-b337-13ec7113eb30', NULL, '38e52e80-eabb-4db2-8ee3-6de19379ff4f', '2026-08-18 09:18:39.796+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('6ea1cabe-973f-489c-abe7-d106b2e002ef', 'เช็คว่าสถานะเกี่ยวข้องกับการส่งไปหาแพทย์หรือไม่', 'check_exam_status', 'exec', 19, 1, '{"code":"module.exports = async function(data) {\n    const examStatus = \"{{$trigger.payload.status}}\";\n\tconst acceptedStatus = [\n        \"15\", // ถ่ายเพิ่มก่อน US (ปิดเคส)\n        \"16\", // ปรึกษาแพทย์ (ปิดเคส)\n        \"20\" // ถ่ายเพิ่มหลัง US (ปิดเคส)\n    ]\n\n    if (!acceptedStatus.includes(examStatus)) {\n        throw new Error(''ไม่ใช่สถานะ ส่งต่อแพทย์'');\n    }\n    \n    let doctor_work_status;\n    switch(examStatus) {\n        case \"15\":\n            doctor_work_status = \"6\" // รออ่านผล/MAM เพิ่ม\n            break;\n        case \"16\": \n            doctor_work_status = \"0\" // รออ่านผล\n            break;\n        case \"20\":\n            doctor_work_status = \"12\" // รออ่านผล/MAM เพิ่ม (หลัง US)\n            break;\n    }\n    \n    return {doctor_work_status}\n}"}', '7c870612-af16-44b0-8824-fab06d638b5d', NULL, '7ab7b1a9-793a-47ac-9092-675603a60a54', '2025-05-07 05:04:55.902+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('4ff132d2-f3d9-4e1b-bb4d-c1851837948c', 'สร้าง Coordinate ที่ F14 แบบ "ปล่อยเคสกลับบ้าน"', 'create_coordinate', 'item-create', 37, 1, '{"collection":"coordinate","permissions":"$full","emitEvents":true,"payload":{"appointment":"{{$trigger.keys[0]}}","status":"2","data_tag":"0","case_tag":"4","reason":"{{$trigger.payload.cancel_reason}}","detail":"{{$trigger.payload.cancel_detail}}","location":"{{$trigger.payload.location}}"}}', NULL, NULL, 'bed2e574-ce79-4612-8cbc-30b8da6078e7', '2025-12-10 04:28:44.841+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('2731ac71-d478-4144-9bb4-8e955f3f08c5', 'อัพเดทฟิลด์ officer ของ progress', 'item_update_officer', 'item-update', 21, 36, '{"collection":"progress","permissions":"$full","payload":{"officer":"{{query_user.data.data.first_name}} {{query_user.data.data.last_name}}"},"key":["{{read_data_progress.id}}"]}', NULL, NULL, '89be6643-9611-41be-8186-059689a6c8d3', '2026-06-29 03:23:38.514+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('de807d21-4ef0-45af-b0a2-c486d8cfbed3', 'เข้า Trigger Flow Progress Created', 'trigger_flow_progress_created_nxndg_hhgvy_dsgiq_jewcc_euxpw_dyofv_dlxlc', 'trigger', 92, 132, '{"flow":"91f7c920-9249-42c7-9215-cf7a2a4eb971","payload":"{{create_progress_cancel_us}}"}', NULL, NULL, '38e52e80-eabb-4db2-8ee3-6de19379ff4f', '2025-09-16 02:53:32.156+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('fe01278e-edce-4f6d-8e35-c88fd019c4b7', 'อัพเดทฟิลด์ is_change_time_slot, is_insert_queue, appointment_status, queue ของ appointment ที่ถูก trigger', 'item_update_zvv0l_mmjoc', 'item-update', 93, 19, '{"collection":"appointment","payload":{"is_change_time_slot":false,"is_insert_queue":false,"appointment_status":"ยังไม่ถึงเวลานัด/ยังไม่มา","queue":[]},"key":["{{$trigger.keys[0]}}"],"permissions":"$full"}', '88cd3f5c-8397-49b7-8dbf-ebc45be5a116', NULL, 'b1e04a8c-e551-468e-b336-820154f3ac1b', '2024-10-03 04:31:50.061+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('1f65eef0-0048-4780-bfea-875d0b173010', 'check_queue_status_2', 'exec_syxed_wbnqh_lspdy', 'exec', 19, 18, '{"code":"module.exports = async function(data) {\n    if ({{check_queue_status_1}} == 1) {\n        return true; \n    } \n    throw new Error(''สถานะคิวไม่ใช่เรียกแล้ว''); \n\n};\n"}', '29749c4d-a5ff-49e0-8d9f-989de46f0cc5', '61e4a1b2-1b1a-4685-9040-9c8f6ee36418', '5563ef7b-949d-46c7-b3ae-5d7d187b7e72', '2024-10-02 11:59:30.973+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('d45119b7-0d47-4bff-a007-e3568b0544a6', 'check_queue_k', 'exec_syxed', 'exec', 92, 1, '{"code":"module.exports = async function(data) {\n    let queue = {{read_data_queue}};\n\n    if (queue.queue_type == \"K\") {\n        return true;\n    }\n\n    throw new Error(''queue_type not K'');\n    return false;\n}"}', '03e28967-cd40-4807-85ab-fa9e321f4de8', NULL, '5563ef7b-949d-46c7-b3ae-5d7d187b7e72', '2024-10-02 11:28:58.136+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('a9b38de3-3c19-44a0-9f4f-f0f40c89947c', 'last_no_progress', 'last_no_progress', 'exec', 74, 1, '{"code":"module.exports = async function(data) {\n    const progressArray = {{read_data_worklist.progress}};\n\n    // เช็คว่า progress array มีค่าหรือไม่ และมีข้อมูลอยู่\n    if (progressArray && progressArray.length > 0) {\n        // จัดเรียง progress ตามไอดีจากน้อยไปมาก\n        const sortedProgressArray = progressArray.sort((a, b) => a - b);\n\n        // ดึง progress ID ตัวสุดท้ายหลังจากจัดเรียง\n        const lastProgressId = sortedProgressArray[sortedProgressArray.length - 1];\n\n        return {\n            lastProgressId: lastProgressId\n        };\n    } else {\n        return {\n            message: ''No progress data found''\n        };\n    }\n};"}', 'd45119b7-0d47-4bff-a007-e3568b0544a6', NULL, '5563ef7b-949d-46c7-b3ae-5d7d187b7e72', '2024-10-15 02:58:50.967+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('446502c8-9229-46ac-adaa-3cc98bda1abb', 'read_data_queue', 'read_data_queue', 'item-read', 20, 1, '{"collection":"queue","key":["{{$trigger.keys[0]}}"],"permissions":"$full"}', '1345e278-0f35-44f0-b55a-4e0b208ef5dd', NULL, '5563ef7b-949d-46c7-b3ae-5d7d187b7e72', '2024-10-02 11:32:57.721+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('84f127d2-4a56-4ee3-93aa-6e988edb5af2', 'Create Data', 'item_create_jtmlb_mburm', 'item-create', 73, 72, '{"payload":{"title":"ผู้มาตรวจรับบัตรคิว","admission_time":"{{current_time.currentTime}}","status":"รอดำเนินการ","department":"Front","worklist":"{{read_data_queue.worklist[0]}}"},"collection":"progress"}', '99a9bab8-367d-4e18-aa46-ab6235dfa247', NULL, '5563ef7b-949d-46c7-b3ae-5d7d187b7e72', '2024-10-17 04:26:32.475+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('93c548a5-e656-477e-abb0-ed878de9f79b', 'Update Data', 'item_update_qnbbc', 'item-update', 57, 36, '{"payload":{"end_time":"{{current_time.currentTime}}"},"collection":"worklist","key":["{{read_data_queue.worklist[0]}}"],"permissions":"$full"}', '2cf69929-ad17-4355-b5d8-2db8e20483c4', NULL, 'af896f59-cef0-47ab-b0ac-efdb21df529f', '2024-10-21 05:18:13.68+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('404b3ce4-95de-4340-82cc-0052f568cd11', 'last_no_progress', 'last_no_progress', 'exec', 73, 1, '{"code":"module.exports = async function(data) {\n    const progressArray = {{read_data_worklist.progress}};\n\n    // เช็คว่า progress array มีค่าหรือไม่ และมีข้อมูลอยู่\n    if (progressArray && progressArray.length > 0) {\n        // จัดเรียง progress ตามไอดีจากน้อยไปมาก\n        const sortedProgressArray = progressArray.sort((a, b) => a - b);\n\n        // ดึง progress ID ตัวสุดท้ายหลังจากจัดเรียง\n        const lastProgressId = sortedProgressArray[sortedProgressArray.length - 1];\n\n        return {\n            lastProgressId: lastProgressId\n        };\n    } else {\n        return {\n            message: ''No progress data found''\n        };\n    }\n};"}', '00d43bb2-6e3f-4340-a071-5ecd2e288d84', NULL, 'af896f59-cef0-47ab-b0ac-efdb21df529f', '2024-10-18 02:52:27.142+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('42f2a014-5485-4557-822e-c39ea232fa82', 'อัพเดทข้อมูล notification', 'notification_update_thqop', 'request', 21, 53, '{"method":"PATCH","url":"{{read_environment.url}}/items/notification","headers":[{"header":"Authorization","value":"Bearer {{read_environment.access_token}}"}],"body":"{\n    \"keys\": {{map_ids_notification}},\n    \"data\": {\n        \"status\": \"archive\",\n        \"doctor_work\": null\n    }\n}"}', '7cd09f3a-d73d-486c-b593-e09dc27c9292', NULL, '55b25593-7665-4f37-83f5-9e691af6b979', '2025-07-31 11:25:26.718+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('f8ed4e09-1a5a-4f4b-add4-f1f40105ae83', 'last_no_progress', 'last_no_progress', 'exec', 73, 1, '{"code":"module.exports = async function(data) {\n    const progressArray = {{read_data_worklist.progress}};\n\n    // เช็คว่า progress array มีค่าหรือไม่ และมีข้อมูลอยู่\n    if (progressArray && progressArray.length > 0) {\n        // จัดเรียง progress ตามไอดีจากน้อยไปมาก\n        const sortedProgressArray = progressArray.sort((a, b) => a - b);\n\n        // ดึง progress ID ตัวสุดท้ายหลังจากจัดเรียง\n        const lastProgressId = sortedProgressArray[sortedProgressArray.length - 1];\n\n        return {\n            lastProgressId: lastProgressId\n        };\n    } else {\n        return {\n            message: ''No progress data found''\n        };\n    }\n};\n"}', '9da8aec5-9cf5-44d5-924b-d180391029d2', NULL, '2770ae3f-8314-4d3f-a4f8-4d58da1ec279', '2024-10-15 05:47:05.362+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('4b3e80ef-7763-45bc-a400-c5772b121e87', 'เช็คว่ามี statusTriggerFlows และ status เป็น แจ้งแอดมินแล้ว หรือไม่', 'exec_qg6x7_xhzcd_tistu', 'exec', 3, 115, '{"code":"module.exports = async function(data) {\n    const statusTriggerFlows = \"{{$trigger.payload.status_trigger_flows}}\";\n    const status = \"{{$trigger.payload.status}}\";\n    \n    //แจ้งแอดมินแล้ว\n    if (statusTriggerFlows === \"trigger\" && status === \"7\") {\n        return true; \n    } \n\n    throw new Error(''ไม่มี statusTriggerFlows หรือ status ไม่เท่ากับ 7''); \n\n};\n"}', '1fbd7ea3-06be-412f-9ad8-e38ca83bf398', NULL, 'ed9487b5-5316-42b2-96ee-6c58162b72bb', '2025-10-08 10:22:31.744+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('c35e0bb8-bcdc-4067-92c2-fec71bd6c0a3', 'เช็คว่ามี statusTriggerFlows และ status เป็น ถ่ายสำเร็จ หรือไม่', 'status_trigger_flows_status_xqxfz_xzbdf_xylgt_tnhsk', 'exec', 3, 98, '{"code":"module.exports = async function(data) {\n    const statusTriggerFlows = \"{{$trigger.payload.status_trigger_flows}}\";\n    const status = \"{{$trigger.payload.status}}\";\n    \n    //ถ่ายสำเร็จ\n    if (statusTriggerFlows === \"trigger\" && status === \"6\") {\n        return true; \n    } \n\n    throw new Error(''ไม่มี statusTriggerFlows หรือ status ไม่เท่ากับ 6''); \n\n};\n"}', '083d26f5-d4f1-437a-a6f7-30fc9f91b456', 'd309a5ad-d197-4bba-bcc8-e74267537d80', '38e52e80-eabb-4db2-8ee3-6de19379ff4f', '2025-09-03 01:53:20.337+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('016ec2ca-e989-459a-b466-cb3e4f185b66', 'เช็คว่า appointment_datetime ไม่ใช่วันนี้ ใช่หรือไม่', 'check_today', 'exec', 75, 19, '{"code":"module.exports = async function(data) {\n    // ดึงวันที่ปัจจุบัน\n    const today = new Date().toISOString().split(''T'')[0];\n\n    // ดึงข้อมูล inputDate จาก data ที่ส่งเข้ามาใน Flow\n    const inputDate = data.read_data_appointment.appointment_datetime;\n\n    if (!inputDate) {\n        throw new Error(\"inputDate ไม่ถูกต้องหรือไม่ได้รับการส่งเข้ามา\");\n    }\n\n    // ตรวจสอบว่าตรงกับวันนี้หรือไม่\n    const formattedInputDate = new Date(inputDate).toISOString().split(''T'')[0];\n\n    if (today !== formattedInputDate) {\n        console.log(\"ไม่ใช่วันนี้ ไปต่อ\");\n        return true;\n    } \n\t\n    throw new Error(''วันนี้ ไม่ไปต่อ'');\n    return false;\n}\n"}', 'fe01278e-edce-4f6d-8e35-c88fd019c4b7', NULL, 'b1e04a8c-e551-468e-b336-820154f3ac1b', '2024-10-03 04:31:50.12+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('515ba19f-a8ee-413e-b70f-288b360c64f2', 'return ค่า array ของ ID ทั้งหมดจาก notification', 'map_ids_notification', 'exec', 39, 19, '{"code":"module.exports = async function(data) {\n  const notification = {{read_data_notification}};\n\n  // Extracting the IDs\n  const ids = notification.filter(noti => !noti.is_front_noti).map(noti => noti.id);\n\n  // Function to process IDs (e.g., logging or further processing)\n  function processIds(...ids) {\n    console.log(...ids); // This will log each ID as a separate argument\n    return ids; // or do other operations with the separate IDs\n  }\n\n  return processIds(...ids); // Spread the IDs into separate arguments\n}\n"}', 'abc2ef17-79cb-4527-bdf2-a03ba18fc93f', NULL, '5b6e538c-4ccb-4ce0-b266-b48257d08bf6', '2025-07-17 03:08:07.298+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('33317b1a-d05b-4470-b3a4-d2069395b97a', 'เปลี่ยน has_recommend_bx_form เป็น true', 'has_recommend_bx_form_true', 'item-update', 19, 1, '{"collection":"examination","permissions":"$full","key":"{{$trigger.payload.examination}}","payload":{"has_recommend_bx_form":true}}', NULL, NULL, '69b706c1-8a99-4ff9-9f97-eeb7c9244b7f', '2025-08-28 10:57:14.352+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('1b3e6c1f-1e69-4cd0-bc3a-ccd4ff8f9bab', 'อ่านค่าเวลาต้น+สิ้นเดือนปัจจุบัน', 'get_date_range', 'exec', 19, 1, '{"code":"module.exports = async function(data) {\n    const now = new Date()\n    \n\tconst startOfMonth = (date) => \n    \tnew Date(date.getFullYear(), date.getMonth(), 1, 0, 0, 0, 0);\n    \n    const endOfMonth = (date) => \n    \tnew Date(date.getFullYear(), date.getMonth() + 1, 0, 23, 59, 59, 999);\n    \n\treturn {\n        from:startOfMonth(now).toISOString(),\n        to: endOfMonth(now).toISOString(),\n    };\n}"}', 'ea0ba221-8ff0-4e62-a667-ac5d4209eefb', NULL, '784933e7-b375-4551-954b-ab894d350f6c', '2025-09-02 10:29:06.398+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('7bfea05c-5bad-4136-b0a8-124c5dd5349a', 'อัพเดทฟิลด์ status, close_case_time ของ progress ตัวสุดท้าย', 'status_close_case_time_progress_gulsg_roxym_wdxhi', 'item-update', 39, 99, '{"collection":"progress","payload":{"close_case_time":"{{current_time.currentTime}}","status":"เสร็จสิ้น"},"key":["{{last_no_progress.lastProgressId}}"],"permissions":"$full"}', 'd680693d-2b49-4c5a-a485-95bbfa1d89e5', NULL, 'ed9487b5-5316-42b2-96ee-6c58162b72bb', '2025-09-02 02:59:19.503+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('d71d902c-f182-4ec8-98dd-1c7498a403dd', 'อัพเดทข้อมูล notifications', 'notifications_update', 'request', 21, 70, '{"method":"PATCH","url":"{{read_environment.url}}/notifications","headers":[{"header":"Authorization","value":"Bearer {{read_environment.access_token}}"}],"body":"{\n    \"keys\": {{map_ids_notifications}},\n    \"data\": {\n        \"status\": \"archive\",\n        \"stop\": true\n    }\n}"}', NULL, NULL, '55b25593-7665-4f37-83f5-9e691af6b979', '2025-07-31 11:25:26.767+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
