INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('99299cc4-f98c-4950-b194-6b14b8e1788e', 'เช็คว่ามี statusTriggerFlows และ status เป็น รับเคส หรือไม่', 'exec_qg6x7', 'exec', 3, 51, '{"code":"module.exports = async function(data) {\n    const statusTriggerFlows = \"{{$trigger.payload.status_trigger_flows}}\";\n    const status = \"{{$trigger.payload.status}}\";\n    \n    //รับเคส\n    if (statusTriggerFlows === \"trigger\" && status === \"1\") {\n        return true; \n    } \n\n    throw new Error(''ไม่มี statusTriggerFlows หรือ status ไม่เท่ากับ 1''); \n\n};\n"}', '63c4303a-3998-43f8-9820-dbcf009bd10e', 'defc8da9-0ae5-4e5a-9657-6a1e0c6970b0', 'ed9487b5-5316-42b2-96ee-6c58162b72bb', '2025-03-08 15:29:14.846+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
