INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('d309a5ad-d197-4bba-bcc8-e74267537d80', 'เช็คว่ามี statusTriggerFlows และ status เป็น ยกเลิก หรือไม่', 'status_trigger_flows_status_xqxfz_xzbdf_xylgt_tnhsk_llqcs', 'exec', 3, 132, '{"code":"module.exports = async function(data) {\n    const statusTriggerFlows = \"{{$trigger.payload.status_trigger_flows}}\";\n    const status = \"{{$trigger.payload.status}}\";\n    \n    //ยกเลิก\n    if (statusTriggerFlows === \"trigger\" && status === \"8\") {\n        return true; \n    } \n\n    throw new Error(''ไม่มี statusTriggerFlows หรือ status ไม่เท่ากับ 8''); \n\n};\n"}', '623ed232-ba3d-4707-ac3e-90e6a5a6959e', NULL, '38e52e80-eabb-4db2-8ee3-6de19379ff4f', '2025-09-08 14:54:08.048+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('de045926-46dd-4988-a03c-17de022191aa', 'สร้าง progress แพทย์อ่านผลเพิ่มเติม', 'create_progress_doctor_reads_results', 'item-create', 57, 114, '{"collection":"progress","payload":{"title":"แพทย์อ่านผลเพิ่มเติม","admission_time":"{{current_time.currentTime}}","status":"รอดำเนินการ","department":"แพทย์","worklist":"{{read_data_queue.worklist[0]}}"}}', 'eb673619-c46f-42e9-8d07-908482611878', NULL, '38e52e80-eabb-4db2-8ee3-6de19379ff4f', '2025-09-03 02:15:54.486+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
