INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('bba0c2db-7908-4c75-b724-be3ed790bd57', 'อ่านข้อมูล financa_work', 'read_data_finance_work', 'item-read', 225, 20, '{"collection":"finance_work","key":["{{create_finance_work[0]}}"],"permissions":"$full","query":null}', '716baf61-077c-47e7-8af7-8e7db7615de3', NULL, 'cdfc74cd-8e37-4fbd-b333-622e244a8e63', '2026-09-25 06:40:14.038+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('06b08916-3876-4153-b70c-d747ee970b92', 'อ่านข้อมูล coordinate', 'read_data_coordinate', 'item-read', 37, 19, '{"collection":"coordinate","key":[],"permissions":"$full","query":{"filter":{"_and":[{"exam":{"_eq":"{{$trigger.keys[0]}}"}},{"appointment":{"_eq":"{{read_data_examination.appointment}}"}}]}}}', 'cc9f080a-8264-4672-8d43-d5949d3cbf13', NULL, 'e472714e-dd02-4bfc-8038-133053a0a457', '2025-09-10 03:36:32.062+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('48f72ef2-fe49-41ee-bff1-27b2a4937247', 'เช็ค + return array ของ exam.id ออกมา', 'get_examinations_id', 'exec', 55, 1, '{"code":"module.exports = async function(data) {\n\tconst examinationArray = {{read_all_examination}}\n    if(!Array.isArray(examinationArray) || examinationArray.length === 0) {\n    \tthrow new Error(''ไม่พบ examination'')\n    }\n\n\treturn examinationArray.map(({id})=>id);\n}"}', '1627869e-b77a-4b13-a172-af92c3b92b02', NULL, '934f9b7b-6974-4d18-abde-8b6aee1307f9', '2025-09-10 07:47:42.104+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('838f0829-3341-40ef-89f7-d6983445ea0a', 'อัพเดทฟิลด์ status, close_case_time ของ progress ตัวสุดท้าย', 'status_close_case_time_progress', 'item-update', 21, 53, '{"payload":{"close_case_time":"{{current_time.currentTime}}","status":"เสร็จสิ้น"},"collection":"progress","key":["{{last_no_progress.lastProgressId}}"],"permissions":"$full"}', '8dc73caf-5382-4dcc-9695-7c54332d85de', NULL, 'afbac7d9-554e-4ab6-a1c8-cd0a649312ae', '2025-03-10 09:59:45.798+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('44c5f0e1-ba3c-4263-9207-178a470d126f', 'สร้าง payload โดยแยก case ตาม status ', 'get_payload', 'exec', 37, 1, '{"code":"module.exports = async function(data) {\n\tconst completeDoctorWork = {{read_completed_doctor_work}}\n\n\tif(!Array.isArray(completeDoctorWork) || completeDoctorWork.length === 0) {\n    \tthrow new Error(''ไม่พบข้อมูลที่ต้องการอัพเดต'')\n    }\n\t\n\tconst getNewStatue = (status) => {\n    \tswitch(status) {\n            case \"2\": return \"17\";\n            case \"10\": return \"16\";   \n        }\n    }\n\n\treturn completeDoctorWork.map(({ id, status: oldStatus }) => ({\n        id,\n        status: getNewStatue(oldStatus)\n    }));\n}"}', '24ae1511-7a3b-4ffa-9eb4-b306b3ad2085', NULL, '9c0642e6-8c23-403f-b833-cc2c7f0c7524', '2025-09-11 06:33:19.782+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('4ca1b1e1-b95b-4461-b63d-f2f8ccbeb3e1', 'อ่านค่า doctor_work ทั้งหมดที่มี status เป็น "F14/ยกเลิก" และ "จ่ายเงินแล้ว"', 'read_completed_doctor_work', 'item-read', 19, 1, '{"query":{"filter":{"_or":[{"status":{"_eq":"2"}},{"status":{"_eq":"10"}}]}},"collection":"doctor_work","permissions":"$full"}', '44c5f0e1-ba3c-4263-9207-178a470d126f', NULL, '9c0642e6-8c23-403f-b833-cc2c7f0c7524', '2025-09-11 06:33:19.814+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('a28eb49b-8467-463d-bc2b-8f9b6214d648', 'check_last_progress', 'check_last_progress', 'exec', 111, 35, '{"code":"module.exports = async function(data) {\n\tconst lastProgress = {{read_data_last_progress}};\n\n    if (lastProgress.title !== \"ลงทะเบียนผู้มาตรวจและสร้างนัดหมาย\") {\n        return true;\n    }\n\n    throw new Error(\"title คือลงทะเบียนผู้มาตรวจและสร้างนัดหมาย\");\n    return false;\n}\n"}', '6308e3ba-cef8-422c-b67c-f3136b3ca23e', NULL, '5563ef7b-949d-46c7-b3ae-5d7d187b7e72', '2024-12-12 03:19:26.781+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('1627869e-b77a-4b13-a172-af92c3b92b02', 'อ่านค่า ultrasound ทั้งหมด ของ patient คนนี้', 'read_all_ultrasound', 'item-read', 19, 19, '{"collection":"ultrasound","query":{"filter":{"_and":[{"exam":{"_in":"{{get_examinations_id}}"}},{"state":{"_eq":"3"}}]},"sort":"-date_created","fields":["exam"]},"permissions":"$full"}', '3b37f37d-94da-4eb1-bc79-bdd37a06a9be', NULL, '934f9b7b-6974-4d18-abde-8b6aee1307f9', '2025-09-10 07:47:42.095+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('58e5ec36-c069-4cb6-ad84-2b306cd76507', 'สร้าง progress ถ่าย ยกเลิกทำ US', 'create_progress_cancel_us', 'item-create', 75, 132, '{"collection":"progress","payload":{"title":"ยกเลิกทำ US","admission_time":"{{current_time.currentTime}}","status":"รอดำเนินการ","department":"{{check_mammogram.department}}","worklist":"{{read_data_queue.worklist[0]}}"}}', 'de807d21-4ef0-45af-b0a2-c486d8cfbed3', NULL, '38e52e80-eabb-4db2-8ee3-6de19379ff4f', '2025-09-08 15:04:41.005+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('623ed232-ba3d-4707-ac3e-90e6a5a6959e', 'อัพเดทฟิลด์ status, close_case_time ของ progress ตัวสุดท้าย', 'status_close_case_time_progress_gulsg_roxym_vozys_drvte_wtvkm_xveqh_znhuf_elruv_iphod', 'item-update', 22, 132, '{"permissions":"$full","payload":{"close_case_time":"{{current_time.currentTime}}","status":"เสร็จสิ้น"},"collection":"progress","key":["{{last_no_progress.lastProgressId}}"]}', '882cb9c2-ac2c-4a21-a790-5359d163ae78', NULL, '38e52e80-eabb-4db2-8ee3-6de19379ff4f', '2025-09-08 15:04:41.09+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('e4dcc5e5-8652-48e8-ad70-562e1bbfeb9e', 'last_no_progress', 'last_no_progress', 'exec', 73, 1, '{"code":"module.exports = async function(data) {\n    const progressArray = {{read_data_worklist.progress}};\n\n    // เช็คว่า progress array มีค่าหรือไม่ และมีข้อมูลอยู่\n    if (progressArray && progressArray.length > 0) {\n        // จัดเรียง progress ตามไอดีจากน้อยไปมาก\n        const sortedProgressArray = progressArray.sort((a, b) => a - b);\n\n        // ดึง progress ID ตัวสุดท้ายหลังจากจัดเรียง\n        const lastProgressId = sortedProgressArray[sortedProgressArray.length - 1];\n\n        return {\n            lastProgressId: lastProgressId\n        };\n    } else {\n        return {\n            message: ''No progress data found''\n        };\n    }\n};"}', 'eec9d453-8492-423d-876d-73f2ca4d9345', NULL, '89677e2f-7d1b-4e9c-8853-2e23650f65ac', '2024-10-28 03:44:44.985+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('1daa21e5-3b4f-4d94-999f-a1599fb83a81', 'เช็คสถานะ patient_result ว่าเป็น รอจัดส่ง หรือไม่', 'check_status_send', 'exec', 21, 19, '{"code":"module.exports = async function(data) {\n    let patientResult = {{read_data_patient_result}};\n\n    if (patientResult.status == \"3\") {\n        return true;\n    }\n\n    throw new Error(''สถานะไม่ใช่รอจัดส่ง'');\n    return false;\n}"}', 'baa79662-0543-4504-b26f-63aaf1f11ad0', '61e3b98c-e518-49a0-9600-e48cc3091635', '2e907bc7-59b0-451c-bf25-8bc2cd332ec8', '2024-10-28 04:28:47.642+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('4e6528da-8c02-4865-9d91-6d91afe28911', 'อ่านข้อมูล appointment', 'read_data_appointment', 'item-read', 3, 19, '{"collection":"appointment","key":["{{read_data_doctor_work.appointment}}"],"permissions":"$full"}', '3bef5176-57c7-438c-95f5-94b6e6157d0e', NULL, '7f07d6c2-0785-4b82-b2ba-4003555b0576', '2025-02-27 02:23:10.079+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('8ca7f653-b1b1-4b75-ab83-20e902d3718c', 'return ค่าวัน-เวลาของตอนนี้', 'current_time', 'exec', 37, 1, '{"code":"module.exports = async function(data) {\n    return {\n        currentTime: new Date().toISOString()\n    };\n};"}', '4e6528da-8c02-4865-9d91-6d91afe28911', NULL, '7f07d6c2-0785-4b82-b2ba-4003555b0576', '2025-02-27 02:23:10.185+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('b597abd0-fc07-4f3c-9ca7-9b7588ff2c5e', 'return ค่า array ของ ID ทั้งหมดจาก notifications', 'map_ids_notifications', 'exec', 18, 50, '{"code":"module.exports = async function(data) {\n  const notifications = {{read_data_notification}};\n\n  // Extracting the IDs\n  const ids = notifications.filter(noti => !noti.is_front_noti).map(noti => noti.notification);\n\n  // Function to process IDs (e.g., logging or further processing)\n  function processIds(...ids) {\n    console.log(...ids); // This will log each ID as a separate argument\n    return ids; // or do other operations with the separate IDs\n  }\n\n  return processIds(...ids); // Spread the IDs into separate arguments\n}\n"}', '3e774713-7aae-442a-9f89-49eec553fcf2', NULL, '5b6e538c-4ccb-4ce0-b266-b48257d08bf6', '2025-07-17 03:08:07.435+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('727c0ffd-9a67-40ba-bc8e-f7a902b53989', 'เช็คว่า status เป็นค่า รอปรึกษาแพทย์ ใช่หรือไม่', 'exec_wvr55_crgxd_fxefa', 'exec', 4, 100, '{"code":"module.exports = async function(data) {\n    const statusTriggerFlows = \"{{$trigger.payload.status_trigger_flows}}\";\n    const statusExam = \"{{$trigger.payload.status}}\";\n    \n    //รอปรึกษาแพทย์\n    if (statusExam === \"2\" && statusTriggerFlows !== \"undefined\") {\n        return true; \n    } \n\n    throw new Error(''statusExam ไม่เท่ากับ รอปรึกษาแพทย์''); \n\n};\n"}', '157f568a-644d-42d0-97ea-5603d4944a50', '2f1e2676-5796-4388-8b23-05c7f7829188', 'cbd6eeeb-ea02-40ee-be82-36164ee8b18c', '2025-09-12 03:19:44.643+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('4e485d5f-dfff-4c60-a19c-d8ec12425270', 'เข้า Trigger Flow Progress Created (v.ส่ง id)', 'trigger_flow_progress_created_ttvvk_frisb_fimne', 'trigger', 75, 68, '{"flow":"89be6643-9611-41be-8186-059689a6c8d3","payload":{"action":"doctor","user":"{{read_data_examination.case_owner_doctor}}","progress":"{{create_progress_doctor_dx}}"}}', NULL, NULL, 'cbd6eeeb-ea02-40ee-be82-36164ee8b18c', '2025-09-04 09:37:00.045+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('4b04350f-a32a-4547-a314-e0da694df9b8', 'สร้าง progress สัมภาษณ์', 'create_progress_interview', 'item-create', 39, 35, '{"payload":{"title":"เจ้าหน้าที่ Tech สัมภาษณ์","admission_time":"{{current_time.currentTime}}","status":"รอดำเนินการ","department":"Tech","worklist":"{{read_data_queue.worklist[0]}}"},"collection":"progress"}', '590b68b7-8cc1-4e66-917f-63ba77dfa9a2', NULL, 'cbd6eeeb-ea02-40ee-be82-36164ee8b18c', '2025-02-18 16:19:40.779+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('2c04badc-ab9e-41e5-8962-aa34cbf0935a', 'เช็ค doctor_id และ status_trigger_flows มีค่าหรือไม่', 'exec_ltda8', 'exec', 19, 1, '{"code":"module.exports = async function(data) {\n    const status_trigger_flows = \"{{$trigger.payload.status_trigger_flows}}\";\n\tconst doctor_id = \"{{$trigger.payload.doctor_id}}\";\n    const status = \"{{$trigger.payload.status}}\";\n\n    if (status_trigger_flows !== \"undefined\" && doctor_id !== \"undefined\" && status === \"9\") {\n        return;\n    }\n    \n    throw new Error(''ไม่มี doctor_id หรือ triggerFlows ไม่มีค่า'');\n}"}', 'aed4b285-333a-4198-9106-5c630c478f96', NULL, '0bdb2833-d4c9-4c47-b433-2c48260d59c2', '2025-07-22 04:05:29.889+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('2681240f-3d6c-4cea-a323-6343c645e8a2', 'เช็คว่ามี statusTriggerFlows และ action เป็น แพทย์อ่านผลเพิ่ม หรือไม่', 'status_trigger_flows_status_xqxfz_xzbdf_xylgt_tnhsk_lrplf_zjewr', 'exec', 22, 114, '{"code":"module.exports = async function(data) {\n    const statusTriggerFlows = \"{{$trigger.payload.status_trigger_flows}}\";\n    const action = \"{{$trigger.payload.action}}\";\n    \n    if (statusTriggerFlows === \"trigger\" && action === \"แพทย์อ่านผลเพิ่ม\") {\n        return true; \n    } \n\n    throw new Error(''ไม่มี statusTriggerFlows หรือ status ไม่เท่ากับ แพทย์อ่านผลเพิ่ม''); \n\n};\n"}', '8b493d3c-c8b5-43f0-ba9c-88fc57b16a76', NULL, '38e52e80-eabb-4db2-8ee3-6de19379ff4f', '2025-09-03 02:08:46.931+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
