INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('1630c621-d1c2-4595-b70c-b0489e6d0f74', 'เช็คว่ามี triggerFlows หรือไม่', 'exec_6rlzp', 'exec', 3, 20, '{"code":"module.exports = async function(data) {\n    const triggerFlows = \"{{$trigger.payload.status_trigger_flows}}\";\n\n    if (triggerFlows !== \"undefined\") {\n        return true;\n    }\n\n    throw new Error(''ไม่มี triggerFlows'');\n    return false;\n}"}', 'c5a36c4d-9311-4ec3-85ec-d91722f6e7c5', NULL, 'cdfc74cd-8e37-4fbd-b333-622e244a8e63', '2025-03-19 12:34:21.001+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
