INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('d55376a9-be58-4473-a594-024771b82997', 'สร้างข้อมูล billing', 'create_billing', 'item-create', 116, 20, '{"collection":"billing","emitEvents":true,"permissions":"$full","payload":{"appointment":"{{read_data_appointment.id}}","appointment_datetime":"{{read_data_appointment.appointment_datetime}}","an":"{{read_data_appointment.an}}","room":"{{read_data_appointment.room}}","building":"{{read_data_appointment.building}}","patient":"{{read_data_appointment.patient_info}}","hn":"{{read_data_patient_info.hn}}","exam":"{{read_data_examination.id}}","exam_datetime":"{{read_data_examination.exam_date}}","finance_work":"{{create_finance_work[0]}}","patient_category":"{{read_data_patient_info.patient_category}}"}}', 'f438a67d-64ba-48a4-9eee-d112b1b4ccc9', NULL, 'cdfc74cd-8e37-4fbd-b333-622e244a8e63', '2026-09-25 06:34:02.012+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('083d26f5-d4f1-437a-a6f7-30fc9f91b456', 'เช็คว่ามี statusTriggerFlows และ action เป็น ปล่อยกลับบ้าน, Confirm Bx หรือไม่', 'status_trigger_flows_status_xqxfz_xzbdf_xylgt_tnhsk_lrplf', 'exec', 21, 98, '{"code":"module.exports = async function(data) {\n    const statusTriggerFlows = \"{{$trigger.payload.status_trigger_flows}}\";\n    const action = \"{{$trigger.payload.action}}\";\n    \n    if (statusTriggerFlows === \"trigger\" && action === \"ปล่อยกลับบ้าน\" || action === \"Confirm Bx\") {\n        return true; \n    } \n\n    throw new Error(''ไม่มี statusTriggerFlows หรือ status ไม่เท่ากับ ปล่อยกลับบ้าน หรือ Confirm Bx''); \n\n};\n"}', '09e2281e-acde-47e9-9784-89a58af6d670', '2681240f-3d6c-4cea-a323-6343c645e8a2', '38e52e80-eabb-4db2-8ee3-6de19379ff4f', '2025-09-03 02:08:47.009+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('a9c41096-0580-43c7-a774-6e08ffb0bf8f', 'สร้าง progress ขอเปลี่ยนเตียง', 'create_progress_req_change_bed', 'item-create', 39, 65, '{"collection":"progress","payload":{"title":"ขอเปลี่ยนเตียง","admission_time":"{{current_time.currentTime}}","status":"รอดำเนินการ","department":"US (Center)","worklist":"{{read_data_queue.worklist[0]}}"}}', '961c0a9f-0190-43b8-98a4-e7d5bb470e61', NULL, '38e52e80-eabb-4db2-8ee3-6de19379ff4f', '2025-09-02 04:59:59.457+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('8ed16748-d00d-4ae6-a9fb-80d8a9bf2a50', 'return ค่า id ของ progress ตัวสุดท้าย จากข้อมูล worklist ที่ถูกอ่านมาก่อนหน้านี้', 'last_no_progress', 'exec', 3, 36, '{"code":"module.exports = async function(data) {\n    const progressArray = {{read_data_worklist.progress}};\n\n    // เช็คว่า progress array มีค่าหรือไม่ และมีข้อมูลอยู่\n    if (progressArray && progressArray.length > 0) {\n        // จัดเรียง progress ตามไอดีจากน้อยไปมาก\n        const sortedProgressArray = progressArray.sort((a, b) => a - b);\n\n        // ดึง progress ID ตัวสุดท้ายหลังจากจัดเรียง\n        const lastProgressId = sortedProgressArray[sortedProgressArray.length - 1];\n\n        return {\n            lastProgressId: lastProgressId\n        };\n    } else {\n        return {\n            message: ''No progress data found''\n        };\n    }\n};"}', 'ff06a3b9-939f-4b4c-be8b-de419b41e81c', NULL, '7f07d6c2-0785-4b82-b2ba-4003555b0576', '2025-02-27 02:23:09.946+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('36e844d0-50e2-430b-bf2a-d0799bd5ef3b', 'อ่านข้อมูล patient_info', 'read_data_patient_info', 'item-read', 98, 20, '{"collection":"patient_info","key":["{{read_data_appointment.patient_info}}"],"permissions":"$full"}', 'd55376a9-be58-4473-a594-024771b82997', NULL, 'cdfc74cd-8e37-4fbd-b333-622e244a8e63', '2026-09-25 06:34:02.199+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
