INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('eeadcddb-cad4-4d9a-b045-eadd1bcdba51', 'return ค่า array ของ ID ทั้งหมดจาก notification', 'map_ids_notification', 'exec', 3, 53, '{"code":"module.exports = async function(data) {\n  const notification = {{read_data_notification}};\n\n  // Extracting the IDs\n  const ids = notification.map(noti => noti.id);\n\n  // Function to process IDs (e.g., logging or further processing)\n  function processIds(...ids) {\n    console.log(...ids); // This will log each ID as a separate argument\n    return ids; // or do other operations with the separate IDs\n  }\n\n  return processIds(...ids); // Spread the IDs into separate arguments\n}\n"}', '42f2a014-5485-4557-822e-c39ea232fa82', NULL, '55b25593-7665-4f37-83f5-9e691af6b979', '2025-07-31 11:25:26.732+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('c8a677e3-5147-4fbc-b034-135fc70f518f', 'เช็คว่ามี statusTriggerFlows และสถานะเป็น F14/ยกเลิก หรือไม่', 'status_trigger_flows_status_signtopacs_ferrt_zpbkc', 'exec', 3, 86, '{"code":"module.exports = async function(data) {\n    const statusTriggerFlows = \"{{$trigger.payload.status_trigger_flows}}\";\n    const status = \"{{$trigger.payload.status}}\";\n    \n    //F14/ยกเลิก\n    if (status === \"2\" && statusTriggerFlows !== \"undefined\") {\n        return true; \n    } \n\n    throw new Error(''ไม่มี statusTriggerFlows หรือ status ไม่ใช่ F14/ยกเลิก''); \n\n};\n"}', 'df2d66cc-9523-43dd-9b11-8ce4ebde585e', 'bc6b8896-d250-474f-9739-2c14e44166ef', '7f07d6c2-0785-4b82-b2ba-4003555b0576', '2025-06-18 17:26:12.835+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
