INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('0a55c8a6-550d-465d-84c1-cfb2e5f98037', 'อัพเดทจำนวนเงิน', 'item_update_fkv42', 'item-update', 261, 20, '{"collection":"billing","emitEvents":true,"permissions":"$full","payload":{"a":"{{calculate_price.a}}","a_price":"{{calculate_price.a_price}}","b":"{{calculate_price.b}}","b_price":"{{calculate_price.b_price}}","c":"{{calculate_price.c}}","c_price":"{{calculate_price.c_price}}","d":"{{calculate_price.d}}","d_price":"{{calculate_price.d_price}}","e":"{{calculate_price.e}}","e_price":"{{calculate_price.e_price}}","total":"{{calculate_price.total}}","is_out_patient":"{{calculate_price.is_out_patient}}","is_overtime":"{{calculate_price.is_overtime}}","is_foreigner":"{{calculate_price.is_foreigner}}","foreigner_fee":"{{calculate_price.foreigner_fee}}","care_type":"{{calculate_price.care_type}}","is_invoice_requested":"{{calculate_price.is_invoice_requested}}","can_claim_expense":"{{calculate_price.can_claim_expense}}","payment_type":"{{calculate_price.payment_type}}","payment_method":"{{calculate_price.payment_method}}"},"key":["{{create_billing[0]}}"]}', NULL, NULL, 'cdfc74cd-8e37-4fbd-b333-622e244a8e63', '2026-09-25 06:43:22.663+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('157f568a-644d-42d0-97ea-5603d4944a50', 'อัพเดทฟิลด์ status, close_cast_time ของ progress ตัวสุดท้าย', 'status_close_cast_time_progress_utzpf_gxpll_wzfyr', 'item-update', 22, 100, '{"payload":{"close_case_time":"{{current_time.currentTime}}","status":"เสร็จสิ้น"},"key":["{{last_no_progress.lastProgressId}}"],"collection":"progress","permissions":"$full"}', 'b2b5659b-e0a3-4fa0-bc49-dbcbc441e14f', NULL, 'cbd6eeeb-ea02-40ee-be82-36164ee8b18c', '2025-09-12 03:26:25.943+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('f3e3c947-30d5-4647-9149-be9a7af26e2b', 'เช็คว่ามี is_mam_after_us_done ส่งมาไหม (เคส spot ที่ทำ us ก่อน)', 'check_is_mam_after_us_done', 'exec', 19, 19, '{"code":"module.exports = async function(data) {\n    if({{$trigger.payload.is_mam_after_us_done}}) {\n        return {{$trigger.payload.is_mam_after_us_done}} // true = ทำ mam หลัง us ไปแล้ว\n    }\n    \n\tthrow new Error(''ไม่ใช่เคสถ่าย spot หลัง us'')\n}"}', '649d04cb-ab4e-4367-a225-2e5236b00570', NULL, 'a6078515-a2aa-435a-9862-4abe646ae8cc', '2025-07-24 11:02:25.503+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('e4322816-86bb-49a7-aa93-300cf7e10ee0', 'Create Data', 'item_create_doctor_work', 'item-create', 37, 18, '{"collection":"doctor_work","payload":{"user_created":"{{$accountability.user}}","exam":"{{read_data_coordinate.exam}}","appointment":"{{read_data_coordinate.appointment}}","status":"{{check_status_coordinated.status}}","doctor":"{{read_data_coordinate.doctor}}","doctor_change":"{{check_status_coordinated.doctorChange}}"},"emitEvents":true,"permissions":"$full"}', '545e4738-97c6-422c-8ead-e941ea4d4796', NULL, 'baa6bf9a-4a45-475e-9aa9-93d402672662', '2025-01-28 13:36:54.089+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('43959dfe-a2d7-4dfe-95fa-90fa552b23ec', 'เช็คค่าว่าเป็นเคสเปลี่ยนแพทย์ไหม', 'check_doctor_change', 'exec', 19, 1, '{"code":"module.exports = async function(data) {\n    const doctor_change = {{$trigger.payload.doctor_change}}\n\n\tif(!doctor_change) {\n    \tthrow new Error(''ไม่ใช่เคสเปลี่ยนแพทย์'')\n    }\n}"}', '8a9fbbc4-e66f-46e1-ad6b-e5b37e7ae79f', NULL, '2ee6cb0b-eb4e-4740-93a3-ddd208b6305d', '2025-10-30 05:26:34.016+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('545e4738-97c6-422c-8ead-e941ea4d4796', 'อัพเดทข้อมูล coordinate', 'item_update_o0jz9', 'item-update', 55, 18, '{"collection":"coordinate","key":["{{$trigger.keys[0]}}"],"payload":{"doctor_work":"{{item_create_doctor_work[0]}}"},"permissions":"$full"}', 'ee0fcad1-0d08-4ef5-9c8f-a93389b2e8c0', NULL, 'baa6bf9a-4a45-475e-9aa9-93d402672662', '2025-01-29 02:13:45.812+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('c5758ad9-6499-406b-9db6-37a71f5450c3', 'เช็คว่า appointment_datetime เป็นวันนี้ หรือไม่', 'exec_a27ow', 'exec', 55, 1, '{"code":"module.exports = async function(data) {\n    // ดึงวันที่ปัจจุบัน\n    const today = new Date().toISOString().split(''T'')[0];\n\n    // ดึงข้อมูล inputDate จาก data ที่ส่งเข้ามาใน Flow\n    const inputDate = data.read_appointment.appointment_datetime;\n\n    if (!inputDate) {\n        throw new Error(\"inputDate ไม่ถูกต้องหรือไม่ได้รับการส่งเข้ามา\");\n    }\n\n    // ตรวจสอบว่าตรงกับวันนี้หรือไม่\n    const formattedInputDate = new Date(inputDate).toISOString().split(''T'')[0];\n\n    if (today === formattedInputDate) {\n        console.log(\"วันนี้\");\n        return true;\n    } \n\t\n    throw new Error(''ไม่ใช่วันนี้'');\n    return false;\n}\n"}', '0b14fc33-7c1d-4c5f-bdf6-0ca0e6f7cfeb', NULL, '123c9014-d9d2-4a4f-9a93-d59f291e1c24', '2024-10-03 03:01:43.338+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('21eb35c4-b207-44dc-a4df-86f7447bcf15', 'ปั้นข้อความแจ้งเตือน', 'message_notification', 'exec', 39, 70, '{"code":"module.exports = async function(data) {\n  // อ่านข้อมูลจาก read_data_queue\n  const queue = {{read_data_queue}};\n\n  // ดึงค่าที่ต้องใช้\n  const number = queue.number || \"\";\n  const firstNameTh = queue.first_name_th?.trim();\n  const lastNameTh = queue.last_name_th?.trim();\n  const firstNameEn = queue.first_name_en?.trim();\n  const lastNameEn = queue.last_name_en?.trim();\n\n  // ถ้ามีชื่อไทยให้ใช้ชื่อไทย ถ้าไม่มีให้ใช้ชื่ออังกฤษแทน\n  let fullName = \"\";\n\n  if (firstNameTh && lastNameTh) {\n    fullName = `${firstNameTh} ${lastNameTh}`;\n  } else if (firstNameEn && lastNameEn) {\n    fullName = `${firstNameEn} ${lastNameEn}`;\n  }\n\n  // ปั้น string สุดท้าย\n  const displayString = `${number} ${fullName}`.trim();\n\n  // ส่งกลับให้ Flow ตัวถัดไปใช้\n  return {\n    display_string: displayString\n  };\n}\n"}', NULL, NULL, '55b25593-7665-4f37-83f5-9e691af6b979', '2025-10-24 10:55:29.54+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('aa77d1a9-5803-4a1d-af68-59f08434ef2f', 'อัพเดทฟิลด์ status, close_case_time ของ progress ตัวสุดท้าย', 'status_close_case_time_progress_gulsg_roxym_vozys', 'item-update', 21, 49, '{"permissions":"$full","payload":{"close_case_time":"{{current_time.currentTime}}","status":"เสร็จสิ้น"},"collection":"progress","key":["{{last_no_progress.lastProgressId}}"]}', '189b2fc0-9b13-4b35-a8ad-b233f808e4a0', NULL, '38e52e80-eabb-4db2-8ee3-6de19379ff4f', '2025-09-02 04:50:04.881+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('ea26567e-aaba-46ce-91f1-40a42849bebf', 'สร้าง notification ที่เจ้าหน้าที่ F14', 'notification_f14', 'item-create', 75, 70, '{"permissions":"$full","collection":"notification","emitEvents":true,"payload":"{{create_notification_payload}}"}', NULL, NULL, '55b25593-7665-4f37-83f5-9e691af6b979', '2025-10-24 10:50:11.881+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('c8078bfc-22df-4ccc-9b67-fed3b293d31b', 'เช็คสถานะ queue ว่าเป็น ยกเลิก หรือไม่', 'check_queue_status', 'exec', 37, 1, '{"code":"module.exports = async function(data) {\n    let queue = {{read_data_queue}};\n\n    if (queue.status == \"3\") {\n        return true;\n    }\n\n    throw new Error(''สถานะคิวไม่ใช่ยกเลิก'');\n    return false;\n}"}', 'da5c973d-083c-4922-b300-04c1f3d84193', NULL, 'f3f4611a-021c-47c0-be3a-e85f03734d53', '2024-10-22 10:54:12.777+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('8a9fbbc4-e66f-46e1-ad6b-e5b37e7ae79f', 'สร้างการแจ้งเตือนไปยังแพทย์', 'create_doctor_notification', 'item-create', 37, 1, '{"collection":"notification","permissions":"$full","emitEvents":true,"payload":{"is_doctor_noti":true,"status":"inbox","appointment":"{{$trigger.payload.appointment}}","from_dept":"Front (F.14)","from_user":"{{$trigger.payload.user_created}}","to_user":"{{$trigger.payload.doctor}}","to_dept":"แพทย์","subject":"ส่งทำ Ultrasound","message":"เคสเปลี่ยนแพทย์"}}', NULL, NULL, '2ee6cb0b-eb4e-4740-93a3-ddd208b6305d', '2025-10-30 05:26:33.999+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('91d4e2ee-5c31-41ea-a878-3766d2783f3e', 'อัพเดต noti ให้เป็นอ่านแล้ว', 'update_notification_read', 'item-update', 55, 1, '{"permissions":"$full","collection":"notification","emitEvents":true,"payload":{"status":"read"},"query":{"filter":{"_and":[{"subject":{"_eq":"ขอเปลี่ยนแพทย์"}},{"appointment":{"_eq":"{{read_current_coordinate.appointment}}"}},{"status":{"_eq":"inbox"}}]}}}', NULL, NULL, '41a5a56f-a402-4c2d-af82-734c4c1b4aaf', '2025-11-12 16:55:50.304+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('d086f883-d9ee-4a25-9973-46defa0a30a3', 'เช็คว่าเป็นคิว M หรือไม่', 'exec_1v3da', 'exec', 37, 1, '{"code":"module.exports = async function(data) {\n    const queue = {{read_data_queue}};\n\n    if (queue.queue_type == \"M\" || queue.queue_type == \"BX\") {\n        return true;\n    }\n\n    throw new Error(''ไม่ใช่คิวประเภท M || BX'');\n    return false;\n}"}', '96f6e62a-deaa-45f1-afe2-b01688d546c4', NULL, '4e842895-1751-490e-b100-8426a00cde26', '2024-10-25 11:54:49.625+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('7de9530c-e17c-446f-b3b0-461fbf4a8b31', 'อ่านข้อมูล queue ที่ถูก trigger', 'read_data_queue', 'item-read', 19, 1, '{"collection":"queue","key":["{{$trigger.keys[0]}}"],"permissions":"$full"}', 'd086f883-d9ee-4a25-9973-46defa0a30a3', NULL, '4e842895-1751-490e-b100-8426a00cde26', '2024-10-25 11:54:49.663+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
