INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('33144962-94a0-4cde-b911-056801de5816', 'อ่าน exam ล่าสุด (ครั้งที่ผ่านมา)', 'read_previous_examination', 'item-read', 55, 1, '{"permissions":"$full","collection":"examination","query":{"filter":{"patient":{"_eq":"{{read_appointment.patient_info}}"},"appointment":{"_neq":null}},"fields":["*","exam_reason_multi.*"],"sort":"-exam_date","limit":1}}', '6397645a-8a44-48b4-b373-fd5d7d0f2dda', NULL, '4e6e586f-780c-4bbc-9372-9b43d1994495', '2026-02-19 03:34:17.364+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
