INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('b8191d54-9433-49fa-84b1-45cfc0ae52c1', 'return ค่า array ของ ID ทั้งหมดจาก appointments', 'map_ids_appointment', 'exec', 55, 1, '{"code":"module.exports = async function(data) {\n  const appointments = {{read_data_appointment}};\n\n  // Extracting the IDs\n  const ids = appointments.map(appointment => appointment.id);\n\n  return ids; \n}\n"}', 'a7bd35c0-c69b-4ccc-a643-9f896371f569', NULL, 'e34ea695-536b-4eb7-8fd0-b26bcbdf030f', '2024-10-03 04:19:51.838+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
