INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('c0764b84-82c6-477f-a75a-09ab8e72e766', 'อ่านข้อมูล queue ทั้งหมดที่เป็นสถานะ รอเรียกคิว, เรียกคิวแล้ว', 'read_data_queue', 'item-read', 5, 19, '{"collection":"queue","query":{"filter":{"queue_datetime":{"_lte":"{{date_today}}"},"_or":[{"status":"0"},{"status":"1"}]}},"permissions":"$full"}', '781a4174-23c0-4904-ab91-de2970dd1d5a', NULL, 'e34ea695-536b-4eb7-8fd0-b26bcbdf030f', '2024-10-24 04:14:38.038+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('a7bd35c0-c69b-4ccc-a643-9f896371f569', 'เข้า Trigger Flow ของ read_environment data', 'read_environment', 'trigger', 73, 1, '{"flow":"f5ad1f92-3584-40cb-8931-926f1cd88ff1"}', '7a0f41be-6e61-4a5f-935a-6e6e86ce4da7', NULL, 'e34ea695-536b-4eb7-8fd0-b26bcbdf030f', '2024-11-05 02:05:30.499+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('24c591c0-e195-467e-9f92-18d80e52e37d', 'เช็คเงื่อนไขว่าไม่ใช่เคสที่สร้างจาก us ส่ง confirm_bx', 'check_not_us', 'exec', 37, 1, '{"code":"module.exports = async function(data) {\n    if(\"{{$trigger.payload.appointment_bx_id}}\" !== \"undefined\") {\n    \tthrow new Error(''เป็นเคส confirm_bx'')\n    }\n\t\n}"}', '47ded662-4d85-43f0-a253-f38ffb725239', NULL, 'b518e2cd-e651-4758-b71e-cee45014725d', '2025-12-16 01:05:44.555+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('5378ec6f-e65b-492c-a442-71ad7ebac5ee', 'เช็คว่ามี statusTriggerFlows และ status เป็น รับเคสแล้ว(ปรึกษาแพทย์) หรือไม่', 'exec_qg6x7_xhzcd', 'exec', 3, 99, '{"code":"module.exports = async function(data) {\n    const statusTriggerFlows = \"{{$trigger.payload.status_trigger_flows}}\";\n    const status = \"{{$trigger.payload.status}}\";\n    \n    //รับเคสแล้ว(ปรึกษาแพทย์)\n    if (statusTriggerFlows === \"trigger\" && status === \"9\") {\n        return true; \n    } \n\n    throw new Error(''ไม่มี statusTriggerFlows หรือ status ไม่เท่ากับ 9''); \n\n};\n"}', '69c72dc9-ee2f-46a7-b635-ed4e514a3b24', '4b3e80ef-7763-45bc-a400-c5772b121e87', 'ed9487b5-5316-42b2-96ee-6c58162b72bb', '2025-06-09 02:00:29.282+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('69c72dc9-ee2f-46a7-b635-ed4e514a3b24', 'เช็คว่า progress ตัวสุดท้ายไม่ใช่ รอปรึกษาแพทย์', 'exec_9j8jk_expqo', 'exec', 21, 99, '{"code":"module.exports = async function(data) {\n\tlet lastProgressTitle = \"{{read_data_last_progress.title}}\"; \n    if (lastProgressTitle != \"รอปรึกษาแพทย์\") {\n        return true; \n    } \n\n    throw new Error(''Progress title ตัวสุดท้ายคือรอปรึกษาแพทย์''); \n\n};\n"}', '7bfea05c-5bad-4136-b0a8-124c5dd5349a', NULL, 'ed9487b5-5316-42b2-96ee-6c58162b72bb', '2025-06-09 02:00:29.04+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('fdc17e3c-7fcf-4f7f-8a26-ebeba2fd609b', 'เคลียร์ค่า queue ใน appointment', 'queue_appointment', 'item-update', 37, 17, '{"collection":"appointment","permissions":"$full","payload":{"queue":[]},"key":["{{$trigger.keys[0]}}"]}', '36f830f9-24ef-4a19-ab51-9c810ee2a857', NULL, 'e2c372dc-14d8-4e55-806a-e906e5dd52b3', '2026-01-08 06:48:36.441+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('aeb3404a-23bf-4c86-b900-1d69240b6808', 'Update Data', 'item_update_et3i6', 'item-update', 55, 1, '{"collection":"nurse_work","permissions":"$full","emitEvents":true,"key":["{{read_data_nurse_work[0].id}}"],"payload":{"appointment_datetime":"{{$trigger.payload.appointment_datetime}}","bx_status":"0"}}', 'd551d694-a08f-476b-ac00-67b57c1e9039', NULL, 'e2c372dc-14d8-4e55-806a-e906e5dd52b3', '2025-12-14 17:39:58.43+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('8c75f87e-455c-4ece-b783-6fba6cc9fd2a', 'เช็ค appointed_dept เพื่อดูว่าส่งมาที่พยาบาลไหม', 'check_appointed_dept', 'condition', 19, 1, '{"filter":{"$trigger":{"payload":{"appointed_dept":{"_eq":"nurse"}}}}}', '613f6a54-c681-454b-9734-2915529f52e3', NULL, 'ce3b63e2-5413-4dc6-9236-b9dcef31efea', '2026-01-27 03:48:36.834+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
