INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('95345a4c-8278-4ffa-9954-df1f9d16a44b', 'ปั้นข้อมูล recommended_procedures', 'create_recommended_procedures', 'exec', 3, 134, '{"code":"module.exports = async function(data) {\n    const examinationGeneral = {{read_data_exam_new.examination_general[0]}}\n    const recommendationDes = examinationGeneral?.recommendation_des ?? []\n    const procedures = recommendationDes.map(({ technique, procedure, side, location_des }) => ({\n  \t\ttechnique,\n  \t\tprocedure,\n  \t\tside,\n  \t\tlocation: location_des,\n\t}));\n    \n    return procedures;\n}\n"}', NULL, NULL, '52bed9fc-4f3a-4b41-9c82-07cea484cb76', '2026-03-24 09:29:05.397+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('82256ef0-d02b-434a-81f4-b8ae9b186941', 'สร้างข้อมูล nurse_work', 'nurse_work', 'item-create', 95, 1, '{"collection":"nurse_work","emitEvents":true,"permissions":"$full","payload":{"appointment":"{{get_key.id}}","status":"{{get_nurse_work_resources.status}}","appointed_dept":"{{get_nurse_work_resources.appointed_dept}}"}}', '23b0c961-832d-450d-b561-c0498cc9f39d', NULL, 'a4478d87-09b2-4841-9b79-c6378eaae11d', '2025-11-27 03:50:45.464+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('a2b87961-208e-4ef9-96b7-02a89f066007', 'อ่านข้อมูล appointment ทั้งหมดที่ appointment_status ไม่ใช่ส่งตรวจ หรือเสร็จสิ้น', 'read_data_appointment', 'item-read', 37, 1, '{"collection":"appointment","query":{"filter":{"_and":[{"appointment_datetime":{"_lte":"{{$last}}"}},{"_or":[{"appointment_status":"ยังไม่ถึงเวลานัด/ยังไม่มา"},{"appointment_status":"รอเรียกคิว"},{"appointment_status":"เรียกแล้ว"}]}]},"limit":1000},"permissions":"$full"}', 'b8191d54-9433-49fa-84b1-45cfc0ae52c1', NULL, 'e34ea695-536b-4eb7-8fd0-b26bcbdf030f', '2024-10-03 04:19:51.904+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('0988be74-3a09-4199-bb29-fd72ed307321', 'return ค่าวันที่และเวลาของ เวลาเริ่มต้นของวันพรุ่งนี้', 'date_today', 'exec', 19, 1, '{"code":"module.exports = async function(data) {\n\tconst now = new Date();\n\tconst startOfTomorrow = new Date(now.getFullYear(), now.getMonth(), now.getDate() + 1, 0, 0, 0).toISOString();\n\treturn startOfTomorrow;\n}"}', 'a2b87961-208e-4ef9-96b7-02a89f066007', NULL, 'e34ea695-536b-4eb7-8fd0-b26bcbdf030f', '2024-10-03 04:19:51.958+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('1ba3594a-94eb-40fd-bb49-dab4bca02584', 'สร้าง progress รอจัดสรรเตียง', 'create_progress_send_in_room', 'item-create', 76, 33, '{"collection":"progress","payload":{"title":"รอจัดสรรเตียง","admission_time":"{{current_time.currentTime}}","status":"รอดำเนินการ","department":"US (Center)","worklist":"{{read_data_queue.worklist[0]}}","is_hide_users":true}}', 'aac18154-bb9a-4a0b-9068-51b235e71f58', NULL, '38e52e80-eabb-4db2-8ee3-6de19379ff4f', '2025-09-02 11:42:04.512+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('61834b87-b881-4f83-b6e0-098e10c3ea07', 'คำนวณราคา', 'calculate_price', 'pricing-operation', 41, 85, '{"billingData":"{{read_data_billing}}","examCost":"{{read_data_examination_cost}}","pacsSyncData":"{{read_data_pacs_sync_info}}","appointmentData":"{{read_appointment}}","discountExam":"{{read_data_discount}}"}', '4c4a5956-4609-4b91-b2de-b59e58c71868', NULL, '482bbfb7-d779-4c65-bd93-e22fb07399c1', '2026-11-19 14:42:57.887+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
