INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('aff576f2-6aa7-4a7e-a705-3251cc925521', 'stamp เวลาที่ nurse_received_appointment_at', 'stamp_nurse_received_appointment_at', 'item-update', 55, 1, '{"collection":"nurse_work","permissions":"$full","emitEvents":true,"key":"{{create_payload.id}}","payload":{"nurse_appointment_received_at":"{{create_payload.timestamp}}"}}', NULL, NULL, 'ce3b63e2-5413-4dc6-9236-b9dcef31efea', '2026-01-27 03:50:04.072+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('1261d3f6-5b50-4b38-8f1b-4bfd17f41f3d', 'return ค่า id ของ progress ตัวสุดท้าย จากข้อมูล worklist ที่ถูกอ่านมาก่อนหน้านี้', 'last_no_progress', 'exec', 39, 18, '{"code":"module.exports = async function(data) {\n    const progressArray = {{read_data_worklist.progress}};\n\n    // เช็คว่า progress array มีค่าหรือไม่ และมีข้อมูลอยู่\n    if (progressArray && progressArray.length > 0) {\n        // จัดเรียง progress ตามไอดีจากน้อยไปมาก\n        const sortedProgressArray = progressArray.sort((a, b) => a - b);\n\n        // ดึง progress ID ตัวสุดท้ายหลังจากจัดเรียง\n        const lastProgressId = sortedProgressArray[sortedProgressArray.length - 1];\n\n        return {\n            lastProgressId: lastProgressId\n        };\n    } else {\n        return {\n            message: ''No progress data found''\n        };\n    }\n};"}', 'a0e1c010-08d5-47ea-941b-2c36ba2a0d84', NULL, 'cbd6eeeb-ea02-40ee-be82-36164ee8b18c', '2025-02-18 16:05:50.019+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('48eff0a9-e03f-41bb-80d7-f18e791d205f', 'สร้าง nurse_work แบบเรียกคิวแล้ว', 'create_nurse_work', 'item-create', 37, 17, '{"payload":{"appointment":"{{$trigger.keys[0]}}","status":"1","CD_Pacs":"{{get_pacs_condition.CD_Pacs}}","scan_Pacs":"{{get_pacs_condition.scan_Pacs}}"},"permissions":"$full","collection":"nurse_work","emitEvents":true}', NULL, NULL, 'b518e2cd-e651-4758-b71e-cee45014725d', '2025-12-12 02:52:19.517+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('f90d0acb-70d4-4bf1-9825-0abc5fac855c', 'เช็คว่ามี Mammogram หรือไม่ แล้ว return แผนกออกไป', 'check_mammogram', 'exec', 57, 132, '{"code":"module.exports = async function (data) {\n  let department = \"Front(F.14)\";\n  const pacsSyncData = {{read_data_pacs_sync_info}} || [];\n\n  pacsSyncData.forEach((item) => {\n    if (\n      item.modality === \"MG\" &&\n      item.is_mark_del === false &&\n      item.end_time\n    ) {\n      department = \"แพทย์\";\n    }\n  });\n\n  return { department };\n};\n"}', '58e5ec36-c069-4cb6-ad84-2b306cd76507', NULL, '38e52e80-eabb-4db2-8ee3-6de19379ff4f', '2025-09-08 15:04:41.063+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('8a777282-4583-469d-8fbe-0fd7793bfda2', 'เช็คเงื่อนไขว่าเป็นการเรียกคิว bx หรือส่งไปที่แผนกพยาบาลหรือไม่', 'check_bx_condition', 'condition', 19, 1, '{"filter":{"_or":[{"$trigger":{"payload":{"bx_status":{"_eq":"3"}}}},{"$trigger":{"payload":{"department_bx":{"_eq":"nurse"}}}}]}}', '24c591c0-e195-467e-9f92-18d80e52e37d', NULL, 'b518e2cd-e651-4758-b71e-cee45014725d', '2025-12-12 02:52:19.531+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('6267c4ca-a736-4625-a567-54fdc7ba0116', 'อัพเดท appointment_bx_id ที่ appointment', 'item_update_e9wk8', 'item-update', 39, 118, '{"collection":"appointment","permissions":"$full","key":["{{read_data_appointment.id}}"],"payload":{"appointment_bx_id":"{{read_data_exam_new.appointment}}"}}', 'cdd197c9-e335-40c4-bd1d-ca94356f34a4', NULL, '52bed9fc-4f3a-4b41-9c82-07cea484cb76', '2025-12-04 09:28:06.666+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('21cbe656-af1a-4a67-8607-17465d9cdcb9', 'เตรียมข้อมูลสำหรับสร้าง nurse_work ', 'get_nurse_work_resources', 'exec', 76, 1, '{"code":"module.exports = async function(data) {\n    if (\"{{$trigger.payload.request}}\" !== \"bx\") {\n        throw new Error(''นัดหมายนี้ไม่เข้าเงื่อนไข''); \n    }\n    const hasCdAcceptance = [\"มี CD\", \"นำผลเก่ามา\"]\n    \n    const department_bx = \"{{$trigger.payload.department_bx}}\";\n    const frontNote1 = {{$trigger.payload.front_note_1}} ?? [];\n\tconst hasCD = frontNote1.some(note => hasCdAcceptance.includes(note))\n    const appointed_dept = department_bx.replace(\"-cd\",\"\");\n    const status = department_bx.includes(\"cd\") || hasCD ? \"7\" : \"0\"; // รอลงข้อมูล : รอเรียกคิว\n    \n    return {\n        appointed_dept,\n        status\n    }\n};\n"}', '82256ef0-d02b-434a-81f4-b8ae9b186941', NULL, 'a4478d87-09b2-4841-9b79-c6378eaae11d', '2025-11-27 03:50:45.484+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('9a6dd89c-ac48-467b-bdba-ca576497c3d5', 'อัพเดท bx_status ของนัดหมาย', 'bx_status', 'item-update', 20, 56, '{"collection":"appointment","permissions":"$full","key":["{{read_appointment_data.id}}"],"payload":{"bx_status":"{{check_department_bx.bx_status}}"}}', NULL, NULL, 'a4478d87-09b2-4841-9b79-c6378eaae11d', '2025-12-10 01:58:12.759+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('9ff4910f-b9ea-4127-9974-bbec14744c91', 'ยิงไปสร้าง file', 'post_to_create_file', 'request', 82, 34, '{"method":"POST","headers":[{"header":"Authorization","value":"Bearer {{$trigger.payload.access_token}}"}],"body":"{{create_API_body}}","url":"{{read_environment.url}}/pacs-sync/pacs-sync-file"}', NULL, NULL, 'f8348b38-4052-4bed-81f1-f1462291ae17', '2025-01-16 09:56:11.038+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('de2e85d8-7511-4b5b-a36a-d91ce587d716', 'PACS Sync Operation', 'pacs_sync_operation_vgk0a', 'pacs-sync-operation', 100, 17, '{"payload":"{{create_API_body}}"}', NULL, NULL, 'f8348b38-4052-4bed-81f1-f1462291ae17', '2025-12-11 16:00:58.171+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('f52edefd-f390-4063-a084-620289aaf6a6', 'ปั้น Body ก่อนยิง API', 'create_API_body', 'exec', 118, 1, '{"code":"module.exports = async function(data) {\n\tconst pacs_sync_info = {{read_pacs_sync_info}};\n\tconst patient_info = {{read_patient_info}};\n    const mergeData = {...pacs_sync_info, patient: patient_info};\n    \n\treturn  [mergeData] ;\n}"}', '64688255-452a-4768-a4a1-f9b3d69ce944', NULL, 'f8348b38-4052-4bed-81f1-f1462291ae17', '2025-01-16 07:45:01.195+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('c74646e2-c4dd-41c5-9561-9f3a3efe79c0', 'return ค่า array ของ ID ทั้งหมดจาก notification', 'map_ids_notification', 'exec', 80, 19, '{"code":"module.exports = async function(data) {\n  const notifications = {{read_data_notification}};\n\n  // Extracting the IDs\n  const ids = notifications.map(notification => notification.id);\n\n  return ids; \n}\n"}', '8a8da9e9-bbbe-4d4f-a398-b26582f6457d', NULL, 'e34ea695-536b-4eb7-8fd0-b26bcbdf030f', '2025-07-01 11:21:43.819+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('95e5e2dc-2c96-492f-8e55-384bf54d8b50', 'อ่านข้อมูล Notification ทั้งหมด', 'read_data_notification', 'item-read', 62, 19, '{"collection":"notification","query":null,"permissions":"$full"}', 'c74646e2-c4dd-41c5-9561-9f3a3efe79c0', NULL, 'e34ea695-536b-4eb7-8fd0-b26bcbdf030f', '2025-07-01 11:21:43.927+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
