INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('cdd197c9-e335-40c4-bd1d-ca94356f34a4', 'สร้างข้อมูล nurse_work', 'nurse_work', 'item-create', 21, 134, '{"collection":"nurse_work","permissions":"$full","emitEvents":true,"payload":{"appointment":"{{read_data_exam_new.appointment}}","status":"3","examination_general":"{{read_data_exam_new.examination_general[0]}}","recommended_procedures":"{{$trigger.payload.recommended_procedures}}","recommended_procedures_backup":"{{$trigger.payload.recommended_procedures}}","appointed_dept":"{{$trigger.payload.selectedDepartment}}","recommendation_des_backup":"{{read_data_exam_new.examination_general[0].recommendation_des}}","radiologist":"{{read_data_exam_new.case_owner_doctor}}","stop_flow_id87":true}}', NULL, NULL, '52bed9fc-4f3a-4b41-9c82-07cea484cb76', '2025-12-04 07:53:12.086+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('4ed71c21-4820-4e87-aa8e-20cac7b48480', 'เช็คสถานะ finance_work', 'exec_vx5iq', 'exec', 37, 1, '{"code":"module.exports = async function(data) {\n    const finance_work_status = \"{{read_data_finance_work.status}}\";\n\n    if (finance_work_status == \"3\") {\n        return true;\n    }\n\n    throw new Error(''ไม่ใช่สถานะ ชำระเงินแล้ว'');\n    return false;\n}"}', 'a957c5f1-a6e8-4f68-add4-a4e33ae169db', NULL, '9eb9360a-fa14-4b41-87db-345589c2ceb8', '2025-12-12 03:54:03.064+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('1ee8d910-7718-414b-98cd-1f76e9fee1ac', 'อัพเดทสถานะนัดหมายทั้งหมดให้เป็น ไม่มาตามนัด', 'update_data_appointment_thwwz', 'item-update', 42, 35, '{"collection":"appointment","permissions":"$full","key":[],"payload":{"appointment_status":"ไม่มาตามนัด"},"query":{"filter":{"id":{"_in":"{{map_ids_in_nurse_work.appointmentIds}}"}}}}', '2f635067-7335-4aff-beaf-1129a764de71', NULL, 'e34ea695-536b-4eb7-8fd0-b26bcbdf030f', '2025-12-02 03:34:59.792+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('8a8da9e9-bbbe-4d4f-a398-b26582f6457d', 'เคลียร์ค่า Notification ทั้งหมด', 'item_delete_notification', 'item-delete', 98, 19, '{"collection":"notification","key":[],"permissions":"$full","query":{"filter":{"id":{"_in":"{{map_ids_notification}}"}}}}', 'ad86bc96-ccfb-47c8-becb-c8a5f6d040e1', NULL, 'e34ea695-536b-4eb7-8fd0-b26bcbdf030f', '2025-12-02 03:30:19.357+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('85bfe0d7-db3e-4bdc-932b-9d9fe4e1345a', 'return body ของ data เพื่อนำไป create ต่อ', 'body_create_data', 'exec', 57, 17, '{"code":"module.exports = async function(data) {\nconst frontNote1 = {{read_data_appointment.front_note_1}};\nlet resultType = [];\n\nif (frontNote1 && frontNote1.includes(\"รับผลเป็น CD\")) {\n    resultType.push(\"2\");\n} if (frontNote1 && frontNote1.includes(\"รับผลตรวจวันนี้\")) {\n    resultType.push(\"1\");\n}\n\nconst dataToCreate = {\n    status: 0,\n    appointments: [\n        {\n            appointment_id: \"{{$trigger.payload.appointment}}\"\n        }\n    ],\n    queues: [\n        \"{{read_data_appointment.queue[0]}}\"\n    ],\n    result_type: resultType\n};\n\nreturn dataToCreate;\n\n}"}', '1913fa4a-1d06-4f53-862c-a7356191662e', NULL, 'ce0d2f42-09c1-4e35-b370-f5db5c3abbbb', '2026-07-03 04:25:25.069+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('e220f43c-4749-4771-8417-4d3af87b5bc6', 'อัพเดทสถานะคิวทั้งหมดให้เป็น ยกเลิกคิว', 'update_data_queue', 'item-update', 44, 19, '{"collection":"queue","permissions":"$full","key":[],"payload":{"status":"3"},"query":{"filter":{"id":{"_in":"{{map_ids_queue}}"}}}}', '95e5e2dc-2c96-492f-8e55-384bf54d8b50', NULL, 'e34ea695-536b-4eb7-8fd0-b26bcbdf030f', '2025-12-02 03:30:20.072+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('34e57379-2546-4c58-86c3-428aa31a7a2a', 'เช็คว่า front_note_1 มี รับผลตรวจวันนี้, รับผลเป็น CD หรือไม่', 'check_front_note_1', 'exec', 39, 17, '{"code":"module.exports = async function(data) {\n    let appointment = {{read_data_appointment}};\n\n    if (appointment.front_note_1.includes(\"รับผลตรวจวันนี้\") || appointment.front_note_1.includes(\"รับผลเป็น CD\")) {\n        return true;\n    }\n\n    throw new Error(''ไม่รับผลตรวจวันนี้ หรือ CD'');\n    return false;\n}"}', '85bfe0d7-db3e-4bdc-932b-9d9fe4e1345a', NULL, 'ce0d2f42-09c1-4e35-b370-f5db5c3abbbb', '2026-07-03 04:25:25.551+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('ec87be42-d8c3-4a99-b7fb-e4925477ed98', 'อ่านข้อมูล queue', 'read_data_queue', 'item-read', 21, 17, '{"permissions":"$full","collection":"queue","key":["{{read_data_appointment.queue[0]}}"]}', '34e57379-2546-4c58-86c3-428aa31a7a2a', NULL, 'ce0d2f42-09c1-4e35-b370-f5db5c3abbbb', '2026-07-03 04:25:25.747+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('da7a847c-b169-4143-a802-c3254a89a848', 'อ่านข้อมูล appointment', 'read_data_appointment', 'item-read', 3, 17, '{"permissions":"$full","collection":"appointment","key":["{{$trigger.payload.appointment}}"]}', 'ec87be42-d8c3-4a99-b7fb-e4925477ed98', NULL, 'ce0d2f42-09c1-4e35-b370-f5db5c3abbbb', '2026-07-03 04:23:17.574+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('b22415f4-7c80-475d-856b-6bcf16596a25', 'ยิง Webhook (Delete) ไปเคลียร์ค่า Notification ทั้งหมด', 'request_l0r35_sipvh_usexz', 'request', 124, 17, '{"method":"DELETE","body":"{\n    \"keys\": {{map_ids_notification}}\n}","url":"{{read_environment.url}}/items/notification","headers":[{"header":"Authorization","value":"Bearer {{read_environment.access_token}}"}]}', NULL, NULL, 'e34ea695-536b-4eb7-8fd0-b26bcbdf030f', '2025-07-01 11:21:43.781+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('722166d7-c75a-48a3-8466-278db03c6376', 'เช็คว่าเป็น nurse_work ที่ถูกสร้างจาก [id-5] ไหม', 'check_confirm_bx', 'exec', 19, 1, '{"code":"module.exports = async function(data) {\n\tconst stopFlow = {{$trigger.payload.stop_flow_id87}}\n\t\n\tif(stopFlow) {\n    \tthrow new Error(\"เคส confirm_bx: หยุดการทำงาน [id-87]\")\n    }\n}"}', 'f31e0e98-ee3b-4afa-8323-2fa3bc4dcb29', NULL, '4e6e586f-780c-4bbc-9372-9b43d1994495', '2026-03-25 05:18:21.763+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('96e5ae9e-f933-4050-a162-dada34a28c2c', 'เช็คเงื่อนไข status เป็นส่งตรวจ + เจอ nurse_work', 'check_bx_conditions', 'exec', 37, 1, '{"code":"module.exports = async function(data) {\n\tconst appointment_status = \"{{$trigger.payload.appointment_status}}\";\n    const nurse_work = {{get_related_nurse_work[0]}};\n\n\tif(appointment_status !== \"ส่งตรวจ\" || !nurse_work) {\n\t\tthrow new Error(\"ไม่เข้าเงื่อนไขการส่งตรวจ เคส BX\")\n    }\n}"}', '6039e4b2-049f-4853-9e5c-210711c1502f', NULL, 'c886e7be-6abc-4501-b5a1-9792bc5e0399', '2026-03-03 09:43:07.315+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('0880e993-49b2-4a0e-8835-09237de17696', 'อ่านข้อมูล exam', 'read_exam_data', 'item-read', 73, 1, '{"permissions":"$full","collection":"examination","query":{"filter":{"appointment":{"_eq":"{{read_appointment[0].id}}"}}}}', '37e1c395-57cf-45b6-b7dd-8a87a9282f2c', NULL, 'd555b629-b0a2-4177-a879-10f65d083aaa', '2026-03-17 03:22:55.428+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('6d693638-dc88-4a29-8368-84a41da39091', 'เช็คว่ามี statusTriggerFlows และ status เป็น รอเรียกคิว หรือไม่', 'status_trigger_flows_status_xqxfz', 'exec', 3, 49, '{"code":"module.exports = async function(data) {\n    const statusTriggerFlows = \"{{$trigger.payload.status_trigger_flows}}\";\n    const status = \"{{$trigger.payload.status}}\";\n    \n    //รอเรียกคิว\n    if (statusTriggerFlows === \"trigger\" && status === \"1\") {\n        return true; \n    } \n\n    throw new Error(''ไม่มี statusTriggerFlows หรือ status ไม่เท่ากับ 1''); \n\n};\n"}', 'aa77d1a9-5803-4a1d-af68-59f08434ef2f', 'b543351e-66d2-42bf-b9ba-8e1108a64000', '38e52e80-eabb-4db2-8ee3-6de19379ff4f', '2025-09-02 04:32:17.616+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('f100f991-e1e1-4da3-a149-ee5902d40e54', 'ถ้า request ไม่ใช่ bx ให้สร้าง exam', 'check_request_bx_exam', 'exec', 55, 1, '{"code":"module.exports = async function(data) {\n    const request = \"{{read_appointment[0].request}}\";\n\n    if (request != \"bx\" ){\n       throw new Error(''request ไม่ใช่ bx'');\n    }\n}"}', '0880e993-49b2-4a0e-8835-09237de17696', '084d8516-7cfd-487e-bc07-a8f7f4115017', 'd555b629-b0a2-4177-a879-10f65d083aaa', '2026-02-02 02:53:30.906+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('e8eb4f11-3d95-4862-bf98-ce0f0aa87bfd', 'หา nurse_work ที่ผูกกับ appointment', 'get_related_nurse_work', 'item-read', 19, 1, '{"permissions":"$full","collection":"nurse_work","query":{"filter":{"appointment":{"_eq":"{{$trigger.keys[0]}}"}},"sort":"date_created","limit":1}}', '96e5ae9e-f933-4050-a162-dada34a28c2c', NULL, 'c886e7be-6abc-4501-b5a1-9792bc5e0399', '2026-03-03 09:29:07.316+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('f667429d-0afc-4e01-83ea-779867f373c1', 'เช็คสถานะ nurse_work, action (ถ้ามี action จะไม่เข้าเงื่อนไขนื่องจาก ถ้าเปลี่ยนสถานะ appointment จากฝั่งพยาบาลจะมา reset สถานะตรงนี้เลยต้องเช็ค action ถ้าเช็ค code search คำว่า "action to flows id:82")', 'exec_epqst', 'exec', 37, 1, '{"code":"module.exports = async function(data) {\n    const nurse_work_status = \"{{read_data_nurse_work[0].status}}\";\n    const action = \"{{$trigger.payload.action}}\"\n    const appointment_status = \"{{$trigger.payload.appointment_status}}\"\n\n    //\"6\": \"ส่งปรึกษาแพทย์\"\n\t//\"8\": \"แพทย์ตอบกลับ\"\n\t//\"9\": \"แพทย์ตอบกลับ/ยกเลิกทำนัด BX\"\n\tif (\n  \t\t[\"6\", \"8\",\"9\"].includes(nurse_work_status) ||\n  \t\taction === \"action to flows id:82\" ||\n  \t\tappointment_status === \"ส่งตรวจ\" ||\n        \"{{$trigger.payload.appointment_datetime}}\" === \"undefined\"\n\t) {\n  \t\tthrow new Error(\"status ไม่เข้าเงื่อนไข\");\n\t}\n}"}', 'aeb3404a-23bf-4c86-b900-1d69240b6808', NULL, 'e2c372dc-14d8-4e55-806a-e906e5dd52b3', '2026-01-08 11:00:12.023+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('7c48ef4a-8562-4b41-88d7-0b1a31715064', 'อัพเดทฟิลด์ appointment_status ของ appointment ที่ผูกอยู่กับ queue', 'item_update_a3q4b', 'item-update', 19, 17, '{"collection":"appointment","key":["{{read_data_queue.appointment}}"],"payload":{"appointment_status":"รอเรียกคิว"},"permissions":"$full"}', NULL, NULL, '4e842895-1751-490e-b100-8426a00cde26', '2024-10-25 11:54:49.554+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('96f6e62a-deaa-45f1-afe2-b01688d546c4', 'เช็คว่าสถานะของคิวเป็น รอเรียกคิว หรือไม่', 'check_queue_status', 'exec', 55, 1, '{"code":"module.exports = async function(data) {\n    const queue = {{read_data_queue}};\n\n    if (queue.status == \"0\") {\n        return true;\n    }\n\n    throw new Error(\"สถานะคิวไม่ใช่รอเรียกคิว\");\n    return false;\n}"}', '7c48ef4a-8562-4b41-88d7-0b1a31715064', NULL, '4e842895-1751-490e-b100-8426a00cde26', '2024-10-25 11:54:49.565+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('e8368cc8-f59b-49e2-bbae-a916353cd652', 'อ่านข้อมูล finance_work', 'read_data_finance_work', 'item-read', 19, 1, '{"permissions":"$full","collection":"finance_work","key":["{{$trigger.keys[0]}}"]}', '4a0e20d9-0f45-4377-8d71-352e93ab575c', NULL, 'ce0d2f42-09c1-4e35-b370-f5db5c3abbbb', '2026-07-03 04:37:19.013+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('37f35e00-2f2e-4d22-94de-3155585a2dd0', 'อ่านข้อมูล Doctor_Work', 'read_data_doctor_work', 'item-read', 58, 1, '{"permissions":"$full","collection":"doctor_work","key":["{{read_data_ultrasound_work.doctor_work}}"]}', NULL, NULL, '52bed9fc-4f3a-4b41-9c82-07cea484cb76', '2025-07-09 03:29:26.106+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('6039e4b2-049f-4853-9e5c-210711c1502f', 'ถ้า request เป็น bx จะไม่ไปต่อ', 'check_request_bx', 'exec', 55, 1, '{"code":"module.exports = async function(data) {\n    const request = \"{{$trigger.payload.request}}\";\n\n    if (request != \"bx\" ){\n        return true;\n    }\n\n    throw new Error(''request เป็น bx'');\n    return false;\n}"}', '6f4ab2f4-6af1-49be-9a14-7ed34a754e7b', NULL, 'c886e7be-6abc-4501-b5a1-9792bc5e0399', '2026-03-17 02:31:52.449+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('4ce4a61e-af81-449a-ba5c-cd43f43d0ffc', 'อ่าน pacs_sync_infos ว่ามีการถ่าย us ไปแล้วหรือยัง', 'read_us_pacs_sync_infos', 'item-read', 75, 36, '{"permissions":"$full","collection":"pacs_sync_info","query":{"filter":{"_and":[{"end_time":{"_neq":null}},{"is_mark_del":{"_eq":false}},{"modality":{"_eq":"US"}},{"exam":{"_eq":"{{read_data_examination.id}}"}}]}}}', 'b6e11f73-e864-42e5-9904-37e6ce51aa7b', NULL, 'e472714e-dd02-4bfc-8038-133053a0a457', '2025-09-29 02:41:23.367+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('6397645a-8a44-48b4-b373-fd5d7d0f2dda', 'ปั้น payload สำหรับสร้าง exam', 'create_exam_payload', 'exec', 19, 17, '{"code":"module.exports = async function(data) {\n    const last_examination = {{read_previous_examination[0]}};\n    const nurse_work = {{$trigger.key}};\n\tconst appointment = \"{{$trigger.payload.appointment}}\"\n    // ผูกกับ nurse_work, appointment ปัจจุบันไว้ก่อน\n    const payload = { \n        nurse_work, \n        appointment,\n        patient: {{read_appointment.patient_info}}\n    } \n    \n    // ถ้าไม่มี exam ครั้งที่แล้ว (มาตรวจครั้งแรก) => ไม่ต้องปั้นอะไรเพิ่ม \n    if(!last_examination) {\n    \treturn payload \n    }\n\n\t// ต้องปั้น exam_reason_multi ตามที่พยาบาลเลือก procedures มา\n\tconst exam_reason_multi = last_examination.exam_reason_multi?.map(reason => reason.exam_reason_id) ?? [];\n    payload.exam_reason_multi = []; // ติดไว้ก่อน => ต้องไปอ่าน recommeded_procedures ว่ามีอะไรบ้าง\n\tpayload.exam_reason_type = \"Special Procedure\";\n\n\tconst targetFields = [\n        \"menstruation_age\",\"menopause_age\",\"first_pregnancy_age\",\"num_pregnancy\",\n\n  \t\t\"hormone_use\",\"hormone_yrs\",\n        \"cont_use\",\"cont_yrs\",\n        \"ca_hormone_use\",\"ca_hormone_yrs\",\n\n      \t\"hysterectomy\",\"ovaries_removed\",\n\n  \t\t\"mother_cancer\",\"mother_cancer_age\",\n        \"daughter_cancer\",\"daughter_cancer_age_more\",\"daughter_cancer_age\",\n  \t\t\"sister_cancer\",\"sister_cancer_age_more\",\"sister_cancer_age\",\n  \t\t\"grandmother_cancer\",\"grandmother_cancer_age\",\n  \t\t\"other_cancer\",\"other_cancer_age_more\",\"other_cancer_age\",\n\n  \t\t\"exam_reason_memotext\",\"limitation\",\n        \"l_side_mass\",\"num_left_mass\",\n  \t\t\"r_side_mass\",\"num_right_mass\",\n\n  \t\t\"ln\",\"lnwn\",\"lnen\",\"lnww\",\"lnee\",\"lw\",\"lm\",\"le\",\"lsww\",\"lsee\",\"lsws\",\"lses\",\"ls\",\"l_axillar\",\"lother\",\n\n        \"rn\",\"rnwn\",\"rnen\",\"rnww\",\"rnee\",\"rw\",\"rm\",\"re\",\"rsww\",\"rsee\",\"rsws\",\"rses\",\"rs\",\"r_axillar\",\"rother\",\n\t]\n    \n    for (const key of targetFields) {\n        if (key in last_examination) {\n        \tpayload[key] = last_examination[key]\n        }\n    }\n\n\treturn payload\n}"}', 'b4b4ffb9-600c-4d9f-8b08-3949c0bc4c81', NULL, '4e6e586f-780c-4bbc-9372-9b43d1994495', '2026-02-23 08:45:28.879+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('d2b985a6-6d92-4fc7-ba94-893b8a8a7d6e', 'อัพเดทฟิลด์ appointment_status ของ appointment ที่ผูกกับ queue ให้เป็น รอเรียกคิว', 'item_update_y9izm', 'item-update', 37, 1, '{"collection":"appointment","payload":{"appointment_status":"รอเรียกคิว"},"key":["{{$trigger.payload.appointment}}"],"permissions":"$full"}', NULL, NULL, '6174f165-0635-4ca6-9981-7d0453c17458', '2024-10-03 02:57:58.965+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('3aae050b-0661-41c4-a52d-7b2af26f0ce4', 'เช็คว่าเป็นคิว M หรือ BX หรือไม่', 'exec_fpgy3', 'exec', 19, 1, '{"code":"module.exports = async function(data) {\n\tlet queue = {{$trigger.payload}}\n\n    if (queue.queue_type == \"M\" ||  queue.queue_type == \"BX\") {\n        return true;\n    }\n\n    throw new Error(''Queue_type not type M || BX'');\n    return false;\n}"}', 'd2b985a6-6d92-4fc7-ba94-893b8a8a7d6e', NULL, '6174f165-0635-4ca6-9981-7d0453c17458', '2024-10-03 02:57:58.982+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('b0b16a52-a467-41ce-bcc8-b2c11f1a2228', 'สร้างข้อมูล patient_result ที่ฟิลด์ queues คือ id ของ queue ที่ถูก trigger', 'create_patient_result', 'item-create', 37, 1, '{"payload":{"status":"8","queues":["{{$trigger.key}}"]},"collection":"patient_result","permissions":"$full"}', NULL, NULL, '39fa8fb9-ea1b-4962-aeb5-1c92a10e8dde', '2024-10-03 02:42:08.974+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('e10e40a3-d832-4875-bbdc-0b88ade461b3', 'เช็คว่าเป็นคิว R หรือไม่', 'check_queue_r', 'exec', 19, 1, '{"code":"module.exports = async function(data) {\n\tlet queue = {{$trigger.payload}}\n\n    if (queue.queue_type == \"R\" ) {\n        return true;\n    }\n\n    throw new Error(''Queue_type not type R'');\n    return false;\n}"}', 'b0b16a52-a467-41ce-bcc8-b2c11f1a2228', NULL, '39fa8fb9-ea1b-4962-aeb5-1c92a10e8dde', '2024-10-03 02:42:08.986+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('0025b1c9-f263-4e36-8320-dabab1825af4', 'อัพเดท status exam เป็น รอเรียกคิว', 'update_exam_status', 'item-update', 109, 1, '{"permissions":"$full","collection":"examination","emitEvents":true,"key":["{{read_exam_data[0].id}}"],"payload":{"status":"0","exam_date":"{{get_current_time}}"}}', NULL, NULL, 'd555b629-b0a2-4177-a879-10f65d083aaa', '2026-03-17 03:22:55.406+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('04355e76-f0c8-4fba-a35a-62d061852017', 'อ่านข้อมูล Nurse work', 'read_nurse_work', 'item-read', 90, 33, '{"permissions":"$full","collection":"nurse_work","query":{"filter":{"appointment":{"_eq":"{{read_appointment[0].id}}"}}}}', '37059709-8059-49ca-b715-95cb1be63225', NULL, 'd555b629-b0a2-4177-a879-10f65d083aaa', '2026-02-02 05:11:24.681+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('a5087141-4e7b-4d8e-9a8d-8e70fa7b40df', 'แก้ไข Center Income', 'patch_center_income', 'item-update', 21, 65, '{"collection":"center_income","key":["{{read_data_billing.center_income}}"],"payload":{"amount":"{{$trigger.payload.e_price}}"},"permissions":"$full"}', NULL, NULL, '4978440d-6b21-4b42-bf79-b63cdb9dd1be', '2025-05-09 05:36:12.146+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('87bee657-35e9-43fa-83c8-bb4e2a09eb31', 'Check PATCH', 'check_patch', 'exec', 3, 65, '{"code":"module.exports = async function(data) {\n    const copyCdChange = \"{{$trigger.payload.copy_cd}}\";\n    \n    if (copyCdChange === \"PATCH\") {\n        return true; \n    } \n\n    throw new Error(''ไม่ใช่ PATCH''); \n\n};\n"}', 'a5087141-4e7b-4d8e-9a8d-8e70fa7b40df', 'f8acc5fa-4af4-4279-affa-14b23c36dbf2', '4978440d-6b21-4b42-bf79-b63cdb9dd1be', '2025-05-09 05:36:12.208+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('6f4ab2f4-6af1-49be-9a14-7ed34a754e7b', 'อัพเดตข้อมูลใน nurse_work', 'update_nurse_work', 'item-update', 73, 1, '{"collection":"nurse_work","permissions":"$full","emitEvents":true,"key":"{{get_related_nurse_work[0].id}}","payload":{"bx_status":"13","is_visit":true}}', NULL, NULL, 'c886e7be-6abc-4501-b5a1-9792bc5e0399', '2026-03-03 09:54:02.447+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('c8a0c4d2-6b9b-40cc-b1c8-1e4443701cf6', 'อ่านข้อมูล exam ที่พึ่งถูกสร้าง', 'read_data_exam_new', 'item-read', 21, 118, '{"permissions":"$full","collection":"examination","key":["{{create_new_exam[0]}}"],"query":{"fields":["*","examination_general.*"]}}', '6267c4ca-a736-4625-a567-54fdc7ba0116', NULL, '52bed9fc-4f3a-4b41-9c82-07cea484cb76', '2025-12-13 15:21:14.668+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('eda07fc0-4e79-435c-a5f2-56cce03a9d6d', 'สร้างข้อมูล exam, appointment, exam_gen', 'create_new_exam', 'item-create', 3, 118, '{"collection":"examination","permissions":"$full","payload":"{{body_create_exam}}"}', 'c8a0c4d2-6b9b-40cc-b1c8-1e4443701cf6', NULL, '52bed9fc-4f3a-4b41-9c82-07cea484cb76', '2025-12-04 09:28:06.678+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('d755017a-31ad-4029-86ac-7adb4fa0ee0a', 'ปั้น body เพื่อไปสร้าง exam', 'body_create_exam', 'exec', 39, 102, '{"code":"module.exports = function(data) {\n    // 1. ฟังก์ชันล้างข้อมูล System Fields\n    const cleanData = (sourceData, removeFields = []) => {\n        if (!sourceData) return null;\n\n        const newData = { ...sourceData };\n        const systemFields = [\n            ''id'',\n            ''user_created'', ''date_created'',\n            ''user_updated'', ''date_updated'',\n            ''last_saved_at''\n        ];\n\n        [...systemFields, ...removeFields].forEach(field => {\n            delete newData[field];\n        });\n\n        return newData;\n    };\n\n    // ฟิลด์ o2m/m2m: item-read คืนเป็น array ของ id แถวลูก ถ้าติดไปตอน create\n    // Directus จะ \"ย้าย\" แถวลูกพวกนั้นมาผูกกับแถวใหม่ (ไม่ใช่ก๊อป)\n    // เช่น examination ทำให้ exam เดิมไปผูกกับนัด BX ใหม่\n    const appointmentRelationFields = [\n        ''examination'', ''queue'', ''referral_form'', ''consent_form'',\n        ''appointment_reschedules'', ''external_exam_records'', ''vital_signs''\n    ];\n    const examRelationFields = [\n        ''pacs_sync_infos'', ''exam_reason_multi'',\n        ''mam'', ''us'', ''mammogram_mass'', ''mammogram_cal'',\n        ''spots'', ''spot_technicians'',\n        ''ultrasound_cyst'', ''ultrasound_mass'', ''procedure''\n    ];\n\n    // 2. เตรียมข้อมูล Appointment\n    const appointmentPayload = cleanData({{read_data_appointment}}, appointmentRelationFields);\n    if (appointmentPayload) {\n        appointmentPayload.appointment_datetime = null;\n        appointmentPayload.appointment_status = \"ยังไม่ถึงเวลานัด/ยังไม่มา\";\n        appointmentPayload.request = \"bx\";\n    }\n\n    // 3. เตรียมข้อมูล Examination General\n    const examGeneralPayload = cleanData({{read_data_examination_general}}, [''exam'']);\n\n    // 4. เตรียมข้อมูล Exam (Parent)\n    const mainExamPayload = cleanData(\n        {{read_data_exam}},\n        [''appointment'', ''examination_general'', ...examRelationFields]\n    );\n\n    if (mainExamPayload) {\n        mainExamPayload.exam_date = null;\n        mainExamPayload.is_duplicate = true;\n    }\n\n    // 5. การประกอบร่าง (Nesting)\n    if (appointmentPayload) {\n        mainExamPayload.appointment = appointmentPayload;\n    }\n\n    if (examGeneralPayload) {\n        mainExamPayload.examination_general = [examGeneralPayload];\n    }\n\n    return mainExamPayload;\n}\n"}', 'eda07fc0-4e79-435c-a5f2-56cce03a9d6d', NULL, '52bed9fc-4f3a-4b41-9c82-07cea484cb76', '2025-12-12 16:03:49.96+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('0c64b43e-fc74-45da-b34e-48b561ff8972', 'เช็ค action เป็น confirm_bx ใช่หรือไม่', 'check_action_fbjlh', 'exec', 3, 102, '{"code":"module.exports = async function(data) {\n\tconst action = \"{{$trigger.payload.action}}\";\n\n    if (action === \"Confirm Bx\") {\n        return true;\n    }\n\n    throw new Error(''action ไม่ใช่ Confirm Bx'');\n    return false;\n}"}', '73f79828-06fe-4d19-9df5-38d73eefe429', NULL, '52bed9fc-4f3a-4b41-9c82-07cea484cb76', '2025-12-04 04:32:54.753+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('f3cd0901-e20c-42bb-b4f3-c59e113b04d8', 'Check POST', 'check_post', 'exec', 3, 49, '{"code":"module.exports = async function(data) {\n    const copyCdChange = \"{{$trigger.payload.copy_cd}}\";\n    \n    if (copyCdChange === \"POST\") {\n        return true; \n    } \n\n    throw new Error(''ไม่ใช่ POST''); \n\n};\n"}', 'aaf08630-1df2-4c5a-93b7-f84e14551963', '87bee657-35e9-43fa-83c8-bb4e2a09eb31', '4978440d-6b21-4b42-bf79-b63cdb9dd1be', '2025-05-09 05:36:12.356+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('37e1c395-57cf-45b6-b7dd-8a87a9282f2c', 'ดึงเวลาปัจจุบันออกมา', 'get_current_time', 'exec', 91, 1, '{"code":"module.exports = async function(data) {\n\treturn new Date().toISOString()\n}"}', '0025b1c9-f263-4e36-8320-dabab1825af4', NULL, 'd555b629-b0a2-4177-a879-10f65d083aaa', '2026-03-26 10:01:17.284+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('062ac778-e47c-486a-82ab-1312b495b58e', 'เช็คว่ามี่ officer แล้วหรือยัง', 'check_have_officer', 'exec', 37, 1, '{"code":"module.exports = async function(data) {\n    const progressData = {{read_data_progress}};\n\n    if (progressData && !progressData.officer) {\n        return true; \n    }\n\n    throw new Error(''progress นี้มี officer แล้ว''); \n}"}', '45fef03d-a498-4b3e-b1a6-b343dfb69654', NULL, '91f7c920-9249-42c7-9215-cf7a2a4eb971', '2026-06-26 11:04:01.153+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('d8088e40-c8e3-40f0-812c-7fa92846329e', 'อ่านข้อมูล Appointment', 'read_data_appointment', 'item-read', 21, 17, '{"collection":"appointment","key":["{{read_data_finance_work.appointment}}"],"permissions":"$full"}', '541d3ee3-55dd-468c-9303-16a815b012e2', NULL, '4978440d-6b21-4b42-bf79-b63cdb9dd1be', '2025-05-09 05:43:38.63+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('097fe629-0442-4516-af79-01c84fa7dd72', 'สร้าง Center Income', 'post_center_income', 'item-create', 39, 49, '{"collection":"center_income","payload":{"full_name":"{{read_data_patient_info.prefix_th}} {{read_data_patient_info.first_name_th}} {{read_data_patient_info.last_name_th}}","type":"1","service_fee":"1","amount":"{{$trigger.payload.e_price}}","location":"{{read_data_finance_work.location}}","date_time_created":"{{read_data_billing.date_created}}","patient_info":"{{read_data_patient_info.id}}","address":"{{read_data_address.address}} {{read_data_address.sub_district}} {{read_data_address.district}} {{read_data_address.province}} {{read_data_address.zipcode}}"},"emitEvents":true,"permissions":"$full"}', '518078a0-98be-47aa-9ab2-863f0990d099', NULL, '4978440d-6b21-4b42-bf79-b63cdb9dd1be', '2025-05-09 05:36:12.289+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('aaf08630-1df2-4c5a-93b7-f84e14551963', 'read_address', 'read_data_address', 'item-read', 21, 49, '{"permissions":"$full","collection":"address","key":["{{read_data_patient_info.addresses[0]}}"]}', '097fe629-0442-4516-af79-01c84fa7dd72', '9ab51cf1-daed-4be8-aad5-a0bda8b2eea8', '4978440d-6b21-4b42-bf79-b63cdb9dd1be', '2026-07-03 10:14:46.18+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('418105e9-a468-4422-b81b-6c662cd1a98e', 'เช็คว่าเป็น create หรือ update', 'check_event', 'exec', 17, 1, '{"code":"module.exports = async function (data) {\n  const event = \"{{$trigger.event}}\";\n  let key = \"\";\n\n  if (event === \"ultrasound_work.items.create\") {\n    key = \"{{$trigger.key}}\";\n  } else {\n    key = \"{{$trigger.keys[0]}}\";\n  }\n\n  return { key };\n};\n"}', 'f1e1420d-c68a-4328-9787-bebbe8f3c0d7', NULL, '38e52e80-eabb-4db2-8ee3-6de19379ff4f', '2025-09-03 03:18:01.408+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
