INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('613f6a54-c681-454b-9734-2915529f52e3', 'สร้าง payload', 'create_payload', 'exec', 37, 1, '{"code":"module.exports = async function(data) {\n\tconst event = \"{{$trigger.event}}\".split(\".\").at(-1)\n    const now = new Date().toISOString()\n    \n    return {\n    \ttimestamp: now,\n        id: event === \"create\" ? \"{{$trigger.key}}\" :  \"{{$trigger.keys[0]}}\"\n    }\n}"}', 'aff576f2-6aa7-4a7e-a705-3251cc925521', NULL, 'ce3b63e2-5413-4dc6-9236-b9dcef31efea', '2026-02-02 07:15:01.634+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('084d8516-7cfd-487e-bc07-a8f7f4115017', 'ปั้น body examination', 'build_exam_body', 'exec', 3, 18, '{"code":"module.exports = async function (data) {\n  const appointment = {{read_appointment[0]}};\n  const rawMobileLocation = appointment.mobile_location;\n\n  const mobileLocationId =\n    rawMobileLocation && typeof rawMobileLocation === \"object\"\n      ? rawMobileLocation.id\n      : rawMobileLocation;\n\n  const isMobile = mobileLocationId != null && mobileLocationId !== \"\";\n\n  const body = {\n    patient: appointment.patient_info,\n    appointment: appointment.id,\n    location: appointment.location,\n  };\n\n  if (isMobile) {\n    body.mobile = true;\n    body.mobile_location = mobileLocationId;\n  }\n\n  return body;\n};\n"}', 'ded0aef6-a9fd-45cd-8a54-df900c90bf81', NULL, 'd555b629-b0a2-4177-a879-10f65d083aaa', '2026-09-24 09:13:10.949+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('8ab12870-8118-4068-9d35-117a674d9e3a', 'เข้า Trigger Flow Progress Created (v.ส่ง id)', 'trigger_flow_progress_created_nxndg_iusor_nwggp_irqhk_xosbz', 'trigger', 77, 98, '{"flow":"89be6643-9611-41be-8186-059689a6c8d3","payload":{"action":"officer","user":"{{read_data_ultrasound_work.case_owner_ultrasound}}","progress":["{{last_no_progress.lastProgressId}}"]}}', NULL, NULL, '38e52e80-eabb-4db2-8ee3-6de19379ff4f', '2026-08-18 09:43:39.956+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('189b2fc0-9b13-4b35-a8ad-b233f808e4a0', 'สร้าง progress ผู้มาตรวจทำ US (เตียง ?)', 'create_progress_start_us', 'item-create', 39, 49, '{"collection":"progress","payload":{"title":"ผู้มาตรวจทำ US (เตียง {{read_data_ultrasound_work.bed}})","admission_time":"{{current_time.currentTime}}","status":"รอดำเนินการ","department":"US (ห้อง US)","worklist":"{{read_data_queue.worklist[0]}}"}}', 'fef52545-fee4-4246-9a7d-648199312db2', NULL, '38e52e80-eabb-4db2-8ee3-6de19379ff4f', '2025-09-02 04:50:04.869+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
