ad_last_examination.sister_cancer}}","grandmother_cancer":"{{read_last_examination.grandmother_cancer}}","other_cancer":"{{read_last_examination.other_cancer}}"},"query":{"filter":{"id":{"_eq":"{{create_examination.id}}"}}}}', NULL, NULL, 'd555b629-b0a2-4177-a879-10f65d083aaa', '2024-12-18 02:17:48.951+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('34421518-f22e-4093-b515-f226e33972bf', 'return ค่า id ของ progress ตัวสุดท้าย จากข้อมูล worklist ที่ถูกอ่านมาก่อนหน้านี้', 'last_no_progress', 'exec', 3, 33, '{"code":"module.exports = async function(data) {\n    const progressArray = {{read_data_worklist.progress}};\n\n    // เช็คว่า progress array มีค่าหรือไม่ และมีข้อมูลอยู่\n    if (progressArray && progressArray.length > 0) {\n        // จัดเรียง progress ตามไอดีจากน้อยไปมาก\n        const sortedProgressArray = progressArray.sort((a, b) => a - b);\n\n        // ดึง progress ID ตัวสุดท้ายหลังจากจัดเรียง\n        const lastProgressId = sortedProgressArray[sortedProgressArray.length - 1];\n\n        return {\n            lastProgressId: lastProgressId\n        };\n    } else {\n        return {\n            message: ''No progress data found''\n        };\n    }\n};"}', '1e00b341-3245-4cf3-9158-2cb01ced0b25', NULL, '38e52e80-eabb-4db2-8ee3-6de19379ff4f', '2025-09-02 02:37:58.791+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('6e7db230-f050-478a-8825-d792086e59ae', 'return ค่าวัน-เวลาของตอนนี้', 'current_time', 'exec', 49, 1, '{"code":"module.exports = async function(data) {\n    return {\n        currentTime: new Date().toISOString()\n    };\n};"}', '05976409-0ba8-4e6a-bea6-415468ba0c1d', NULL, '38e52e80-eabb-4db2-8ee3-6de19379ff4f', '2025-09-02 02:37:58.958+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
