INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('b207a0dd-8d4a-4025-8169-681f48d0164b', 'สร้างข้อมูล Billing', 'create_billing', 'item-create', 58, 18, '{"collection":"billing","emitEvents":true,"permissions":"$full","payload":{"patient":"{{read_data_patient_info.id}}","hn":"{{read_data_patient_info.hn}}","finance_work":"{{create_finance_work[0]}}","patient_category":"{{read_data_patient_info.patient_category}}"}}', '5ea6db41-f2cd-40e6-a299-003b049dafc7', NULL, '96d6e2ad-4b19-4ce1-8e85-0a0921c808b3', '2025-05-20 10:01:16.904+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('5702e65a-983a-4809-b9b1-9d1b6c7e4f8f', 'สร้างข้อมูล Finance_work', 'create_finance_work', 'item-create', 40, 18, '{"collection":"finance_work","permissions":"$full","payload":{"status":"0","location":"{{$trigger.payload.location}}","queue":"{{read_data_queue.id}}"},"emitEvents":true}', 'b207a0dd-8d4a-4025-8169-681f48d0164b', NULL, '96d6e2ad-4b19-4ce1-8e85-0a0921c808b3', '2025-05-20 09:49:45.167+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('700b7d27-89fd-45ac-b4b2-610f451a3724', 'check_result_type_1', 'check_result_type_1', 'exec', 22, 18, '{"code":"module.exports = async function(data) {\n    if ({{check_result_type}} == \"1\") {\n        return true; \n    } \n    throw new Error(''check_result_type ไม่เท่ากับ 1''); \n\n};\n"}', '5702e65a-983a-4809-b9b1-9d1b6c7e4f8f', '53296737-8c1d-4387-af24-25802eac48fe', '96d6e2ad-4b19-4ce1-8e85-0a0921c808b3', '2025-05-20 06:58:51.973+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('665a2583-20b3-412b-8334-41445c2548c6', 'เช็ค result_type', 'check_result_type', 'exec', 4, 18, '{"code":"module.exports = async function (data) {\n  let patientResult = {{$trigger.payload}};\n\n  const resultTypes = patientResult.result_type || [];\n  const queueType = \"{{read_data_queue.queue_type}}\";\n\n  if(queueType === \"R\"){\n      if (resultTypes.includes(\"1\") && resultTypes.includes(\"2\")) {\n        \treturn \"3\";\n      } else if (resultTypes.includes(\"1\")) {\n        \treturn \"1\";\n      } else if (resultTypes.includes(\"2\")) {\n        \treturn \"2\";\n      }\n      }\n\n  throw new Error(\"patientResult ผิดพลาด หรือ queue_type ไม่เท่ากับ R\");\n};\n"}', '700b7d27-89fd-45ac-b4b2-610f451a3724', NULL, '96d6e2ad-4b19-4ce1-8e85-0a0921c808b3', '2025-05-20 06:58:51.989+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('f57791c4-b26d-4ff7-bdb6-0fc9398798e2', 'อ่านข้อมูล Patient Info', 'read_data_patient_info', 'item-read', 37, 1, '{"collection":"patient_info","key":["{{read_data_queue.patient_info}}"],"permissions":"$full"}', '665a2583-20b3-412b-8334-41445c2548c6', NULL, '96d6e2ad-4b19-4ce1-8e85-0a0921c808b3', '2025-05-20 10:01:16.708+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('096df5a6-04d1-41bf-8c63-5d489f5c0225', 'Check unsign from signed', 'check', 'exec', 37, 1, '{"code":"module.exports = async function (data) {\n  const newState = data.$trigger.payload?.state;\n  if (newState === undefined || newState === null || String(newState) === \"3\") {\n    return { found: false };\n  }\n  const rows = [].concat(data.current_rows ?? []);\n  const signed = rows.find((row) => String(row?.state) === \"3\" && row?.exam);\n  return signed ? { found: true, exam: signed.exam } : { found: false };\n};"}', 'b3890795-6e6b-4810-821a-f6582296e377', NULL, '6ff3e33e-fb4c-462b-8ae2-c6852c8f5fc2', '2026-10-04 05:49:13.102+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('5a9c1a73-423f-4bb9-bf57-772721e21d60', 'Read procedure', 'procedure_rows', 'item-read', 1, 18, '{"permissions":"$full","collection":"procedure","key":"{{$trigger.keys}}","query":{"fields":["id","exam"]}}', '43b0d904-4479-41d0-bfdf-34d8e4e17666', NULL, 'b32fd1fe-a344-4737-b7cd-c2e32d5c0fe4', '2026-10-20 02:41:01.337+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('c1e7dcb2-0125-4c82-b544-85bcd78b8c5e', 'วิเคราะห์ pacs_sync_infos ว่าเคยทำ MAM/US หรือยัง', 'process_pacs_sync_infos', 'exec', 37, 17, '{"code":"module.exports = async function(data) {\n\tconst pacsSyncInfos = {{read_pacs_sync_infos}}\n\tconst isMamDone = pacsSyncInfos.some(({ modality, end_time }) =>\n\t\tmodality === \"MG\" && end_time !== null\n\t)\n    const isUsDone = pacsSyncInfos.some(({ modality, end_time }) =>\n\t\tmodality === \"US\" && end_time !== null\n\t)\n\t\n    \n    return { isMamDone, isUsDone }\n}"}', '7926f747-6417-421c-b81e-ad7cd01a4d72', NULL, '53cf63fc-e9d9-4345-8133-658d24c9fda3', '2025-10-02 16:47:30.304+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('c4c22da8-7bb5-41bb-a8d8-5b95d3a7dc02', 'อัพเดต status ของ doctor_work (เคสก่อน US)', 'update_doctor_work_status_before_us_lvluz', 'item-update', 74, 1, '{"collection":"doctor_work","emitEvents":true,"key":"{{$trigger.payload.doctor_work}}","payload":{"status":"4","status_trigger_flows":"trigger"},"permissions":"$full"}', NULL, NULL, '53cf63fc-e9d9-4345-8133-658d24c9fda3', '2026-08-04 08:28:07.572+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('b7e0b4f2-9a16-474f-8736-68414837ceea', 'ปรับ status เป็น "แพทย์ตอบกลับ - รอเรียกคิว"', 'update_status_consult', 'item-update', 55, 1, '{"collection":"examination","permissions":"$full","emitEvents":true,"key":"{{$trigger.payload.exam}}","payload":{"status":"3","doctor_comment":"{{$trigger.payload.doctor_comment}}","doctor_comment_detail":"{{$trigger.payload.doctor_comment_detail}}"}}', 'c4c22da8-7bb5-41bb-a8d8-5b95d3a7dc02', NULL, '53cf63fc-e9d9-4345-8133-658d24c9fda3', '2025-10-02 16:47:30.167+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('bc8dcb73-bce5-4d31-9996-138ead0a7c31', 'เช็คว่าเป็นเคสปรึกษาแพทย์ไหม', 'check_is_doctor_consult', 'exec', 37, 1, '{"code":"module.exports = async function(data) {\n\tconst exam = {{read_examination}}\n\t\n\tif (exam.status !== \"2\") {\n        throw new Error(''ไม่ใช่เคสปรึกษาแพทย์'')\n    }\n}"}', 'b7e0b4f2-9a16-474f-8736-68414837ceea', 'b3f15ab6-200f-4ac5-a4f0-e00b6d17a6b3', '53cf63fc-e9d9-4345-8133-658d24c9fda3', '2025-10-02 16:47:30.431+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('d8e37811-57f8-4617-82c8-e950ecc45be7', 'อ่าน examination', 'read_examination', 'item-read', 19, 1, '{"permissions":"$full","collection":"examination","key":"{{$trigger.payload.exam}}","query":{"fields":["status"]}}', 'bc8dcb73-bce5-4d31-9996-138ead0a7c31', NULL, '53cf63fc-e9d9-4345-8133-658d24c9fda3', '2025-10-02 16:37:57.713+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('6e433783-7898-422a-8f0d-c5306643b483', 'เข้า Trigger Flow Progress Created', 'trigger_flow_progress_created_nxndg_ruefc_dogyw', 'trigger', 57, 86, '{"payload":"{{create_progress_cancel_case}}","flow":"91f7c920-9249-42c7-9215-cf7a2a4eb971"}', NULL, NULL, '7f07d6c2-0785-4b82-b2ba-4003555b0576', '2025-06-18 17:26:12.705+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('c7445fce-beaf-4eae-a06e-9fcef5d9f1d0', 'Is sign to PACS', 'is_sign_to_pacs', 'condition', 19, 1, '{"filter":{"$trigger":{"payload":{"state":{"_eq":"2"}}}}}', '5a9c1a73-423f-4bb9-bf57-772721e21d60', '6e17c823-e386-42d3-9daa-d50988a44d83', 'b32fd1fe-a344-4737-b7cd-c2e32d5c0fe4', '2026-10-20 02:41:01.514+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('4c4a5956-4609-4b91-b2de-b59e58c71868', 'บันทึกราคาลง billing', 'update_billing_price', 'item-update', 5, 101, '{"collection":"billing","permissions":"$full","key":["{{create_billing[0]}}"],"emitEvents":true,"payload":{"a":"{{calculate_price.a}}","a_price":"{{calculate_price.a_price}}","b":"{{calculate_price.b}}","b_price":"{{calculate_price.b_price}}","c":"{{calculate_price.c}}","c_price":"{{calculate_price.c_price}}","d":"{{calculate_price.d}}","d_price":"{{calculate_price.d_price}}","e":"{{calculate_price.e}}","e_price":"{{calculate_price.e_price}}","total":"{{calculate_price.total}}","is_out_patient":"{{calculate_price.is_out_patient}}","is_overtime":"{{calculate_price.is_overtime}}","is_foreigner":"{{calculate_price.is_foreigner}}","foreigner_fee":"{{calculate_price.foreigner_fee}}","care_type":"{{calculate_price.care_type}}","is_invoice_requested":"{{calculate_price.is_invoice_requested}}","can_claim_expense":"{{calculate_price.can_claim_expense}}","payment_type":"{{calculate_price.payment_type}}","payment_method":"{{calculate_price.payment_method}}"}}', '7efc4dbb-1352-450f-9fa6-ed34a7856fa2', NULL, '482bbfb7-d779-4c65-bd93-e22fb07399c1', '2026-11-19 14:43:49.904+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('eded5a2a-0be6-458e-b5e5-baabd14302c6', 'อ่านรายการถ่าย PACS ของ exam', 'read_data_pacs_sync_info', 'item-read', 23, 85, '{"permissions":"$full","collection":"pacs_sync_info","query":{"filter":{"exam":{"_eq":"{{read_nurse_work.examination}}"}}}}', '61834b87-b881-4f83-b6e0-098e10c3ea07', NULL, '482bbfb7-d779-4c65-bd93-e22fb07399c1', '2026-11-19 14:42:58.071+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('e1d35ce7-202a-41f9-b0cc-2ccb3bc781f5', 'อ่านข้อมูล exam_cost', 'read_data_examination_cost', 'item-read', 39, 51, '{"permissions":"$full","collection":"exam_costs"}', '8fbf5f92-9d76-4a9a-85f1-ea1ef70f81b5', NULL, '52bed9fc-4f3a-4b41-9c82-07cea484cb76', '2025-07-06 04:21:38.13+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('184e4429-2e9c-4950-9507-9648edbd29ef', 'คิดเงิน (MAM)', 'calculate_price_backup', 'exec', 58, 85, '{"code":"module.exports = async function (data) {\n  const billingData = {{read_data_billing}};\n  const examCost = {{read_data_examination_cost}};\n  const pacsSyncData = {{read_data_pacs_sync_info}} || {};\n  const appointmentData = {{read_data_appointment}};\n  const discountExam = {{read_data_discount}};\n  const location = {{read_data_finance_work.location}}; \n\n  const total = pacsSyncData.reduce(\n  (acc, item) => {\n    acc.mamAmount += Number(item.confirm_num_of_mam ?? 0);\n    acc.spotAmount += Number(item.confirm_num_of_spot ?? 0);\n    acc.implantAmount += Number(item.confirm_num_of_implant ?? 0);\n    if (item.modality === \"US\" && item.is_mark_del === false) {\n      acc.ultrasoundAmount += 1;\n    }\n    return acc;\n  },\n  { mamAmount: 0, spotAmount: 0, implantAmount: 0, ultrasoundAmount: 0 }\n);\n  const CopyCDAmount = Array.isArray(appointmentData.front_note_1)\n  ? appointmentData.front_note_1.some((note) =>\n      note.toLowerCase().includes(\"รับผลเป็น cd\")\n    )\n    ? 1\n    : 0\n  : 0;\n\n  const findExamPrice = (exam_type_id) => {\n    const exam = examCost.find((item) => item.type === exam_type_id);\n    if (!exam) return 0;\n      // 1 = TYR\n    return Number(location === 1 ? exam.price_tyr : exam.price_ics);\n  };\n\n  let a_price = 0,\n    b_price = 0,\n    c_price = 0,\n    d_price = 0;\n    e_price = 0;\n\n  const usedTypes = new Set();\n\n  // e_price (Copy CD)\n  if(CopyCDAmount > 0) {\n    e_price = findExamPrice(\"H\");\n    usedTypes.add(\"H\");\n  }\n\n  // d_price (Ultrasound)\n  if (total.mamAmount > 0 && total.ultrasoundAmount > 0) {\n    d_price = findExamPrice(\"D\");\n    usedTypes.add(\"D\");\n  } else if (total.mamAmount === 0 && total.ultrasoundAmount > 0) {\n    d_price = findExamPrice(\"C\");\n    usedTypes.add(\"C\");\n  }\n\n  // a_price (Mammogram)\n  if (total.mamAmount > 0) {\n    if (total.mamAmount <= 2) {\n      a_price = findExamPrice(\"A\");\n      usedTypes.add(\"A\");\n    } else {\n      a_price = findExamPrice(\"B\");\n      usedTypes.add(\"B\");\n    }\n  }\n\n  // b_price (SPOT)\n  if (total.spotAmount > 0) {\n    b_price = findExamPrice(\"E\");\n    usedTypes.add(\"E\");\n  }\n\n  // c_price (Implant)\n  if (total.implantAmount > 0 && total.mamAmount > 2) {\n    c_price = findExamPrice(\"F\");\n    usedTypes.add(\"F\");\n  } else if (total.implantAmount > 0 && total.mamAmount > 0) {\n    c_price = findExamPrice(\"G\");\n    usedTypes.add(\"G\");\n  }\n\n  const sortedUsedTypes = Array.from(usedTypes).sort();\n  const isOutpatient = appointmentData.care_type !== 2;\n  let care_type = appointmentData.care_type;\n  const isOvertime = billingData?.is_overtime || false;\n  const isForeigner = billingData?.is_foreigner || false;\n\n  let subtotal =\n    a_price +\n    b_price +\n    c_price +\n    d_price +\n    //e_price +\n    (isOutpatient ? 100 : 0) +\n    (isOvertime ? 400 : 0);\n\n  let foreigner_fee = isForeigner ? subtotal * 0.25 : 0;\n  subtotal += foreigner_fee;\n\n  // Discount logic\n  let discountAmount = 0;\n  if (Array.isArray(discountExam)) {\n    for (const d of discountExam) {\n      const types = d.typeList?.split(\",\").map((x) => x.trim()).sort();\n      if (\n        types?.length === sortedUsedTypes.length &&\n        types.every((v, i) => v === sortedUsedTypes[i])\n      ) {\n        discountAmount = Number(d.discount || 0);\n        break;\n      }\n    }\n  }\n\n  let finalTotal = location === \"TYR\" ? subtotal : Math.max(0, subtotal - discountAmount);\n\n  const is_invoice_requested = appointmentData.issue_an_invoice;\n  let payment_type = appointmentData.payment_type;\n  let can_claim_expense = null;\n  let payment_method = null;\n\n  if(payment_type){\n     if(payment_type == 1 || payment_type == 2){\n         payment_method = 1;\n     }\n     else if(payment_type == 3 || payment_type == 4 || payment_type == 5 || payment_type == 6\n            || payment_type == 18 || payment_type == 19 || payment_type == 20 || payment_type == 21\n            || payment_type == 22 || payment_type == 23){\n         payment_method = 3;\n     }\n     else if(payment_type == 7){\n         payment_method = 2;\n     }\n  }\n\n\tif(payment_type){\n        if(payment_type == 8){\n            finalTotal = 0;\n        }\n    }\n\n  return {\n    a: total.mamAmount,\n    a_price: a_price.toFixed(2),\n    b: total.spotAmount,\n    b_price: b_price.toFixed(2),\n    c: total.implantAmount,\n    c_price: c_price.toFixed(2),\n    d: total.ultrasoundAmount,\n    d_price: d_price.toFixed(2),\n    e: CopyCDAmount,\n    e_price: e_price.toFixed(2),\n    is_out_patient: isOutpatient,\n    is_overtime: isOvertime,\n    is_foreigner: isForeigner,\n    foreigner_fee: foreigner_fee.toFixed(2),\n    discount_amount: discountAmount.toFixed(2),\n    total: finalTotal.toFixed(2),\n    exam_types_used: sortedUsedTypes,\n    care_type: care_type,\n    is_invoice_requested: is_invoice_requested,\n    can_claim_expense: can_claim_expense,\n    payment_type: payment_type,\n    payment_method: payment_method,\n    //hasOutpatient: hasOutpatient,\n  };\n};\n"}', NULL, NULL, '52bed9fc-4f3a-4b41-9c82-07cea484cb76', '2025-07-06 04:21:37.781+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('e6f2a170-4c0e-4460-8e58-bd5216bf593a', 'อ่านราคาค่าตรวจ', 'read_data_examination_cost', 'item-read', 41, 69, '{"permissions":"$full","collection":"exam_costs"}', '5dadbe5f-9ae9-4875-b317-79bfb12c8621', NULL, '482bbfb7-d779-4c65-bd93-e22fb07399c1', '2026-11-19 14:42:58.685+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
