INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('43b0d904-4479-41d0-bfdf-34d8e4e17666', 'Get exam id', 'exam_ref', 'exec', 19, 18, '{"code":"module.exports = async function (data) {\n  const result = data.$last;\n  const row = Array.isArray(result) ? result[0] : result;\n  if (!row?.exam) throw new Error(\"procedure has no exam: \" + JSON.stringify(result));\n  return { exam: typeof row.exam === \"object\" ? row.exam.id : row.exam };\n};"}', '4407e6f5-aea8-4d4e-867d-560299c6b8d1', NULL, 'b32fd1fe-a344-4737-b7cd-c2e32d5c0fe4', '2026-10-20 02:47:45.497+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('ad6d3d7a-3ddd-4de9-abda-eaba4c8facc5', 'Pick nurse_work', 'nurse_ref', 'exec', 1, 35, '{"code":"module.exports = async function (data) {\n  const result = data.$last;\n  const row = Array.isArray(result) ? result[0] : result;\n  if (!row?.id) throw new Error(\"nurse_work not found: \" + JSON.stringify(result));\n  return { id: row.id };\n};"}', '6d8aa984-4567-4e9d-9c05-51bf6ea62b3b', NULL, 'b32fd1fe-a344-4737-b7cd-c2e32d5c0fe4', '2026-10-20 02:47:44.625+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
