INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('b9550ac5-7ec8-412d-8836-0dad8ef58c79', 'เช็คว่ามี statusTriggerFlows และ status เป็น รอSigntopacs หรือไม่', 'status_trigger_flows_status_signtopacs', 'exec', 3, 54, '{"code":"module.exports = async function(data) {\n    const statusTriggerFlows = \"{{$trigger.payload.status_trigger_flows}}\";\n    const status = \"{{$trigger.payload.status}}\";\n    \n    //รับเคส\n    if (statusTriggerFlows === \"trigger\" && status === \"1\") {\n        return true; \n    } \n\n    throw new Error(''ไม่มี statusTriggerFlows หรือ status ไม่เท่ากับ 1''); \n\n};\n"}', '3b0aba87-5b6f-4e22-9240-8e18db95bccc', NULL, '7f07d6c2-0785-4b82-b2ba-4003555b0576', '2025-03-08 15:48:23.567+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
