INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('0a889b5a-d657-47c0-be24-e1053ff8c4af', 'เช็คสถานะของ appointment ว่าเป็นส่งตรวจ หรือไม่', 'exec_a46nd', 'exec', 37, 1, '{"code":"module.exports = async function(data) {\n    let appointment = {{read_data_appointment}};\n\n    if (appointment.appointment_status == \"ส่งตรวจ\") {\n        return true;\n    }\n\n    throw new Error(''สถานะไม่ใช่ส่งตรวจ'');\n    return false;\n}"}', 'bd91b682-1cea-46d3-ae81-8d8ecb0f4b79', NULL, '745702ca-86a5-4630-86d5-0c21951b61ce', '2024-10-03 02:46:57.681+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('b6e11f73-e864-42e5-9904-37e6ce51aa7b', 'เช็คว่า data ที่มาจาก read_us_pacs_sync_infos มี length > 0 ไหม', 'check_us_pacs_sync_infos_length', 'exec', 93, 36, '{"code":"module.exports = async function(data) {\n\tconst usPacs = {{read_us_pacs_sync_infos}}\n\n\tif(Array.isArray(usPacs) && usPacs.length === 0) {\n    \tthrow new Error(''ไม่พบการทำ ultrasound ของเคสนี้'')\n    }\n}"}', 'a726a6d2-5fc9-4e27-b5bf-315170076e05', NULL, 'e472714e-dd02-4bfc-8038-133053a0a457', '2025-09-29 02:41:23.329+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('d046f335-999e-4ef3-9361-53be155f14b9', '	Skip - not unsign', 'skip', 'log', 1, 35, '{"message":"not unsign"}', NULL, NULL, '6ff3e33e-fb4c-462b-8ae2-c6852c8f5fc2', '2026-10-04 06:10:24.562+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('2f5943b6-8fd7-4434-909c-9bd3c88fa862', 'Save corrected', 'save_corrected', 'item-update', 37, 36, '{"collection":"examination_general","permissions":"$full","key":["{{next_value.id}}"],"payload":{"corrected":"{{next_value.corrected}}","correcteddate":"{{next_value.date}}"}}', NULL, NULL, '6ff3e33e-fb4c-462b-8ae2-c6852c8f5fc2', '2026-10-04 06:31:10.555+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('9e092224-7141-4251-b8af-7bbe9b4bdb21', '	Compute next corrected', 'next_value', 'exec', 37, 18, '{"code":"module.exports = async function (data) {\n  const row = [].concat(data.examination_general ?? [])[0];\n  if (!row?.id) return { id: null };\n  const bangkokNow = new Date(Date.now() + 7 * 60 * 60 * 1000);\n  return {\n    id: row.id,\n    corrected: (Number(row.corrected) || 0) + 1,\n    date: bangkokNow.toISOString().slice(0, 19),\n  };\n};"}', '2f5943b6-8fd7-4434-909c-9bd3c88fa862', NULL, '6ff3e33e-fb4c-462b-8ae2-c6852c8f5fc2', '2026-10-04 06:31:10.741+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
