INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('09cafffb-679b-4613-a53e-9828069295e5', 'return body ของ data เพื่อนำไป create ต่อ', 'body_create_data', 'exec', 34, 52, '{"code":"module.exports = async function(data) {\nconst frontNote1 = {{$trigger.payload.front_note_1}};\nlet resultType = [];\n\nif (frontNote1 && frontNote1.includes(\"รับผลเป็น CD\")) {\n    resultType.push(\"2\");\n} if (frontNote1 && frontNote1.includes(\"รับผลตรวจวันนี้\")) {\n    resultType.push(\"1\");\n}\n\nconst dataToCreate = {\n    status: 0,\n    appointments: [\n        {\n            appointment_id: \"{{$trigger.keys[0]}}\"\n        }\n    ],\n    queues: [\n        \"{{read_data_appointment.queue[0]}}\"\n    ],\n    result_type: resultType\n};\n\nreturn dataToCreate;\n\n}"}', '79a92916-f129-477a-848d-0aad358718b4', NULL, '745702ca-86a5-4630-86d5-0c21951b61ce', '2024-10-03 02:51:33.59+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('9e154126-47a8-4692-982d-3ffd7ec5d792', 'เช็คว่า front_note_1 มี รับผลตรวจวันนี้, รับผลเป็น CD หรือไม่', 'check_front_note_1', 'exec', 13, 53, '{"code":"module.exports = async function(data) {\n    let appointment = {{read_data_appointment}};\n\n    if (appointment.front_note_1.includes(\"รับผลตรวจวันนี้\") || appointment.front_note_1.includes(\"รับผลเป็น CD\")) {\n        return true;\n    }\n\n    throw new Error(''ไม่รับผลตรวจวันนี้ หรือ CD'');\n    return false;\n}"}', '09cafffb-679b-4613-a53e-9828069295e5', NULL, '745702ca-86a5-4630-86d5-0c21951b61ce', '2024-10-03 02:51:33.642+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
