INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('ff06a3b9-939f-4b4c-be8b-de419b41e81c', 'เช็คว่ามี statusTriggerFlows และ สถานะเป็น F14/แนะนำ Bx || F14/ปล่อยกลับบ้าน หรือไม่', 'status_trigger_flows_status_signtopacs_ferrt', 'exec', 3, 70, '{"code":"module.exports = async function(data) {\n    const statusTriggerFlows = \"{{$trigger.payload.status_trigger_flows}}\";\n    const status = \"{{$trigger.payload.status}}\";\n    \n    //9 = F14/แนะนำ Bx 3 = F14/ปล่อยกลับบ้าน\n    if ((status === \"9\" || status === \"3\")&& statusTriggerFlows !== \"undefined\") {\n        return true; \n    } \n\n    throw new Error(''ไม่มี statusTriggerFlows หรือ status ไม่ใช่ F14/แนะนำ Bx || F14/ปล่อยกลับบ้าน''); \n};\n"}', '4c952df6-87e4-4d70-b156-4f3ff6fe6d89', 'c8a677e3-5147-4fbc-b034-135fc70f518f', '7f07d6c2-0785-4b82-b2ba-4003555b0576', '2025-06-18 17:26:13.138+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('17985bc1-e566-49c1-ad4e-d63077ce9769', 'เช็คว่า F14 Report คือ ยกเลิกเคส หรือไม่', 'check_cancel_case_report_trfwb', 'exec', 20, 55, '{"code":"module.exports = async function(data) {\n    const F14Report = \"{{$trigger.payload.F14report}}\";\n\n    //ยกเลิกเคส\n    if (F14Report === \"2\") {\n        return true;\n    }\n\n    throw new Error(''ไม่ใช่ report ยกเลิกเคส'');\n    return false;\n}"}', 'f0b5cbf3-18c5-4990-afd6-56bbe1e029e7', NULL, 'cdfc74cd-8e37-4fbd-b333-622e244a8e63', '2025-03-18 08:43:56.619+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
