INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('c5a36c4d-9311-4ec3-85ec-d91722f6e7c5', 'เช็คว่า F14 Report คือ ปล่อยเคส หรือไม่', 'exec_758kk_uzkbh', 'exec', 21, 20, '{"code":"module.exports = async function(data) {\n    const F14Report = \"{{$trigger.payload.F14report}}\";\n\n    //ปล่อยเคส\n    if (F14Report === \"0\") {\n        return true;\n    }\n\n    throw new Error(''ไม่ใช่ report เคสปล่อยกลับบ้าน'');\n    return false;\n}"}', '7cc45765-3563-48b4-8dbe-0a2098211b4d', '17985bc1-e566-49c1-ad4e-d63077ce9769', 'cdfc74cd-8e37-4fbd-b333-622e244a8e63', '2025-03-18 08:30:47.33+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
