INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('072fe4df-fb8c-4bfa-8482-d1f7f68c3313', 'เช็คเงื่อนไขและ return id', 'get_key', 'exec', 22, 1, '{"code":"module.exports = async (data) => {\n  const p = data.$trigger.payload ?? {};\n  if (String(p.request ?? \"\").toLowerCase() !== \"bx\" || !p.department_bx)\n    throw new Error(\"ไม่เข้าเงื่อนไข\");\n  return { id: data.$trigger.key ?? data.$trigger.keys?.[0] };\n};\n"}', 'f481f3dd-ead1-428c-9608-3449eb4a74db', NULL, 'a4478d87-09b2-4841-9b79-c6378eaae11d', '2026-11-17 03:54:04.469+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('3e0f380b-d284-4176-8a28-c04a9db991a8', 'อ่านข้อมูล nurse_work', 'read_nurse_work', 'item-read', 37, 1, '{"permissions":"$full","collection":"nurse_work","query":{"fields":["id","examination","bx_doctor","appointment.id","appointment.location"]},"key":["{{$trigger.keys[0]}}"]}', 'd59c0108-3512-4ba5-9f16-993c2cc93d17', NULL, '8312ecaf-0d37-4640-87ed-65804fcc2384', '2026-11-16 10:10:10.176+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
