INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('8e1c74b8-08a3-4279-8e26-e41053885df9', 'อ่านข้อมูล nurse_work', 'read_nurse_work', 'item-read', 37, 1, '{"permissions":"$full","collection":"nurse_work","key":["{{$trigger.keys[0]}}"]}', '2051d51c-667d-4498-8a23-5fb9628b3e0d', NULL, '482bbfb7-d779-4c65-bd93-e22fb07399c1', '2026-11-19 14:36:39.786+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('f251a7f6-ce3a-485d-b867-72d133b3f73c', 'คิดเงิน (MAM)', 'calculate_price_backup', 'exec', 39, 86, '{"code":"module.exports = async function (data) {\n  const billingData = {{read_data_billing}};\n  const examCost = {{read_data_examination_cost}};\n  const pacsSyncData = {{read_data_pacs_sync_info}} || {};\n  const appointmentData = {{read_data_appointment}};\n  const discountExam = {{read_data_discount}};\n  const location = {{read_data_finance_work.location}}; \n\n  const total = pacsSyncData.reduce(\n  (acc, item) => {\n    acc.mamAmount += Number(item.confirm_num_of_mam ?? 0);\n    acc.spotAmount += Number(item.confirm_num_of_spot ?? 0);\n    acc.implantAmount += Number(item.confirm_num_of_implant ?? 0);\n    if (item.modality === \"US\" && item.is_mark_del === false) {\n      acc.ultrasoundAmount += 1;\n    }\n    return acc;\n  },\n  { mamAmount: 0, spotAmount: 0, implantAmount: 0, ultrasoundAmount: 0 }\n);\n  const CopyCDAmount = Array.isArray(appointmentData.front_note_1)\n  ? appointmentData.front_note_1.some((note) =>\n      note.toLowerCase().includes(\"รับผลเป็น cd\")\n    )\n    ? 1\n    : 0\n  : 0;\n\n  const findExamPrice = (exam_type_id) => {\n    const exam = examCost.find((item) => item.type === exam_type_id);\n    if (!exam) return 0;\n      // 1 = TYR\n    return Number(location === 1 ? exam.price_tyr : exam.price_ics);\n  };\n\n  let a_price = 0,\n    b_price = 0,\n    c_price = 0,\n    d_price = 0;\n    e_price = 0;\n\n  const usedTypes = new Set();\n\n  // e_price (Copy CD)\n  if(CopyCDAmount > 0) {\n    e_price = findExamPrice(\"H\");\n    usedTypes.add(\"H\");\n  }\n\n  // d_price (Ultrasound)\n  if (total.mamAmount > 0 && total.ultrasoundAmount > 0) {\n    d_price = findExamPrice(\"D\");\n    usedTypes.add(\"D\");\n  } else if (total.mamAmount === 0 && total.ultrasoundAmount > 0) {\n    d_price = findExamPrice(\"C\");\n    usedTypes.add(\"C\");\n  }\n\n  // a_price (Mammogram)\n  if (total.mamAmount > 0) {\n    if (total.mamAmount <= 2) {\n      a_price = findExamPrice(\"A\");\n      usedTypes.add(\"A\");\n    } else {\n      a_price = findExamPrice(\"B\");\n      usedTypes.add(\"B\");\n    }\n  }\n\n  // b_price (SPOT)\n  if (total.spotAmount > 0) {\n    b_price = findExamPrice(\"E\");\n    usedTypes.add(\"E\");\n  }\n\n  // c_price (Implant)\n  if (total.implantAmount > 0 && total.mamAmount > 2) {\n    c_price = findExamPrice(\"F\");\n    usedTypes.add(\"F\");\n  } else if (total.implantAmount > 0 && total.mamAmount > 0) {\n    c_price = findExamPrice(\"G\");\n    usedTypes.add(\"G\");\n  }\n\n  const sortedUsedTypes = Array.from(usedTypes).sort();\n  const isOutpatient = appointmentData.care_type !== 2;\n  let care_type = appointmentData.care_type;\n  const isOvertime = billingData?.is_overtime || false;\n  const isForeigner = billingData?.is_foreigner || false;\n\n  let subtotal =\n    a_price +\n    b_price +\n    c_price +\n    d_price +\n    //e_price +\n    (isOutpatient ? 100 : 0) +\n    (isOvertime ? 400 : 0);\n\n  let foreigner_fee = isForeigner ? subtotal * 0.25 : 0;\n  subtotal += foreigner_fee;\n\n  // Discount logic\n  let discountAmount = 0;\n  if (Array.isArray(discountExam)) {\n    for (const d of discountExam) {\n      const types = d.typeList?.split(\",\").map((x) => x.trim()).sort();\n      if (\n        types?.length === sortedUsedTypes.length &&\n        types.every((v, i) => v === sortedUsedTypes[i])\n      ) {\n        discountAmount = Number(d.discount || 0);\n        break;\n      }\n    }\n  }\n\n  let finalTotal = location === \"TYR\" ? subtotal : Math.max(0, subtotal - discountAmount);\n\n  const is_invoice_requested = appointmentData.issue_an_invoice;\n  const hasOutpatient = Array.isArray(appointmentData.outpatient) && appointmentData.outpatient.length > 0;\n  let payment_type = null;\n  let can_claim_expense = null;\n  let payment_method = null;\n  if(appointmentData.payment_type != 0 && appointmentData.payment_type != 8){\n      can_claim_expense = true;\n      if(care_type == 1){\n      \tpayment_type = appointmentData.payment_type;\n      }else{\n      \tif(appointmentData.payment_type == 1){\n        \tpayment_type = 18;\n        }\n        else  if(appointmentData.payment_type == 2){payment_type = 19;}\n        else  if(appointmentData.payment_type == 3){payment_type = 20;}\n        else  if(appointmentData.payment_type == 4){payment_type = 21;}\n        else  if(appointmentData.payment_type == 5){payment_type = 22;}\n        else if(appointmentData.payment_type == 6){payment_type = 23;}\n        else if(appointmentData.payment_type == 7){payment_type = 0;}\n      }\n  }else if(appointmentData.payment_type == 8){\n      can_claim_expense = false;\n      if(care_type == 1){\n         payment_type = 7;\n      }\n      else{\n      \t payment_type = 24;\n      }\n  }\n\n  if(hasOutpatient){\n      care_type = 3;\n      payment_method = 2;\n      can_claim_expense = false;\n      if(appointmentData.outpatient.includes(1)){\n      \t\tpayment_type = 8;\n      }\n      else if(appointmentData.outpatient.includes(2)){\n      \t\tpayment_type = 9;\n      }\n      else if(appointmentData.outpatient.includes(3)){\n      \t\tpayment_type = 10;\n      }\n      else if(appointmentData.outpatient.includes(4)){\n      \t\tpayment_type = 11;\n      }\n      else if(appointmentData.outpatient.includes(5)){\n      \t\tpayment_type = 16;\n      }\n      else if(appointmentData.outpatient.includes(6)){\n      \t\tpayment_type = 17;\n      }\n  }\n\n\n  if(payment_type){\n     if(payment_type == 1 || payment_type == 2){\n         payment_method = 1;\n     }\n     else if(payment_type == 3 || payment_type == 4 || payment_type == 5 || payment_type == 6\n            || payment_type == 18 || payment_type == 19 || payment_type == 20 || payment_type == 21\n            || payment_type == 22 || payment_type == 23){\n         payment_method = 3;\n     }\n     else if(payment_type == 7){\n         payment_method = 2;\n     }\n  }\n\n\tif(payment_type){\n        if(payment_type == 8){\n            finalTotal = 0;\n        }\n    }\n\n  return {\n    a: total.mamAmount,\n    a_price: a_price.toFixed(2),\n    b: total.spotAmount,\n    b_price: b_price.toFixed(2),\n    c: total.implantAmount,\n    c_price: c_price.toFixed(2),\n    d: total.ultrasoundAmount,\n    d_price: d_price.toFixed(2),\n    e: CopyCDAmount,\n    e_price: e_price.toFixed(2),\n    is_out_patient: isOutpatient,\n    is_overtime: isOvertime,\n    is_foreigner: isForeigner,\n    foreigner_fee: foreigner_fee.toFixed(2),\n    discount_amount: discountAmount.toFixed(2),\n    total: finalTotal.toFixed(2),\n    exam_types_used: sortedUsedTypes,\n    care_type: care_type,\n    is_invoice_requested: is_invoice_requested,\n    can_claim_expense: can_claim_expense,\n    payment_type: payment_type,\n    payment_method: payment_method,\n    hasOutpatient: hasOutpatient,\n  };\n};\n"}', NULL, NULL, '32de3302-0f95-4186-81e2-955100e34997', '2025-02-19 08:15:04.692+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('3b882040-0243-4f38-be1b-9b77d460b03f', 'สร้างข้อมูล Finance Work', 'create_finance_work', 'item-create', 3, 19, '{"collection":"finance_work","payload":{"reason":"{{$trigger.payload.reason || null}}","additional_information":"{{$trigger.payload.additional_information || null}}","exam":"{{read_data_coordinate.exam}}","appointment":"{{read_data_coordinate.appointment}}","status":"0","location":"{{read_data_coordinate.location}}"},"permissions":"$full","emitEvents":true}', '6a14a28c-c401-4f9d-9260-0438a333070a', NULL, '32de3302-0f95-4186-81e2-955100e34997', '2025-02-06 16:32:17.94+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('d3d569a5-5c42-4aa7-89f9-14cd7176625b', 'สร้าง Coordinate ที่ F14 แบบ "รอปรึกษาแพทย์"', 'item_create_g5kpn_nbqmp', 'item-create', 57, 53, '{"collection":"coordinate","payload":{"exam":"{{$trigger.keys[0]}}","appointment":"{{read_data_examination.appointment}}","status":"8","data_tag":"1","location":"{{$trigger.payload.location}}"},"emitEvents":true,"permissions":"$full"}', NULL, NULL, 'e472714e-dd02-4bfc-8038-133053a0a457', '2025-03-18 07:37:47.365+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('b54c528e-42c7-4f7f-a3aa-f8d8f6b335f0', 'เช็คว่าเคสนี้เคยสร้าง Coordinate ใช่หรือไม่', 'exec_87597_jfegj_fykuh', 'exec', 57, 18, '{"code":"module.exports = async function (data) {\n  const coordinateList = {{read_data_coordinate}};\n\n  if (coordinateList.length > 0) {\n    return true;\n  }\n\n  throw new Error(\"เคสนี้ไม่เคยสร้าง Coordinate\");\n};\n"}', '4c97f054-082f-4dc9-83a9-108b15a12788', 'bfc3dd87-a97d-41b4-a2b1-0fce6637f8b0', 'e472714e-dd02-4bfc-8038-133053a0a457', '2025-09-10 03:42:33.149+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('419b1bd0-140a-4e20-bac2-584b353ac34a', 'เช็คว่าสถานะ Coordinat ถูกอัพเดทเป็น เสร็จสิ้น ใช่หรือไม่', 'check_status_coordinate', 'exec', 37, 1, '{"code":"module.exports = async function(data) {\n    let payload = {{$trigger.payload}};\n\n\t//4 = เสร็จสิ้น\n    if (payload.status == \"4\" && payload.status) {\n        return true;\n    }\n\n    throw new Error(''coordinate ไม่ใช่สถานะ เสร็จสิ้น'');\n    return false;\n}"}', '3b882040-0243-4f38-be1b-9b77d460b03f', NULL, '32de3302-0f95-4186-81e2-955100e34997', '2025-02-06 16:33:48.755+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
