INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('34a54a3d-c779-4928-a141-00d0bd44d311', 'เช็คว่า status เป็นกรณี "ถ่ายเพิ่ม" หรือไม่', 'check_status_recieve_for_spot', 'exec', 61, 1, '{"code":"module.exports = async function(data) {\nconst status = \"{{$trigger.payload.status}}\";\n\nconst acceptedStatuses = [\n  \"11\", // spot ก่อน us\n  \"18\"  // spot หลัง us\n];\n    \n    if(acceptedStatuses.includes(status)) {\n        return true\n    } else {\n        throw new Error(''ไม่ใช่สถานะ รับเคส'');\n    return false\n    }\n\n\n}"}', '12e2b43a-c1d8-4caf-84a4-6525553c1e86', 'fe4147c7-62f4-42dc-8bb3-e8d898655970', '74c5ff61-80ae-49e8-a670-1e23e42a78be', '2025-04-29 11:49:08.443+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('c01ea2d0-ac85-430e-aa19-0a0e848f4371', 'เก็บค่าเวลา ณ ปัจจุบัน', 'get_timestamp', 'exec', 18, 18, '{"code":"module.exports = async function(data) {\n\tconst now = new Date();\n    \n\treturn now.toISOString();\n}"}', 'd0aed853-9e61-4baf-8926-c3c91df65dbd', NULL, '74c5ff61-80ae-49e8-a670-1e23e42a78be', '2025-01-31 07:28:57.392+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('752941d2-0719-4cbc-8f35-f3d79e31ab9e', 'เปลี่ยน status ของ exam เป็น "ส่งต่อแพทย์"', 'update_exam_status_refer_med', 'item-update', 97, 35, '{"key":"{{$trigger.keys[0]}}","emitEvents":true,"payload":{"status_trigger_flows":"trigger","status":"ส่งต่อแพทย์","location":"{{$trigger.payload.location}}","is_ultrasound":"{{$trigger.payload.is_ultrasound}}"},"collection":"examination","permissions":"$full"}', NULL, NULL, '74c5ff61-80ae-49e8-a670-1e23e42a78be', '2025-04-21 07:20:38.083+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('23a61051-137a-4bdc-85de-ac1da8bda431', 'เช็คว่า status เป็นกรณี "ปิดเคส" หรือไม่', 'check_status_close', 'exec', 41, 35, '{"code":"module.exports = async function(data) {\nconst status = \"{{$trigger.payload.status}}\";\n\nconst acceptedStatuses = [\n  \"ส่ง MAM - ปิดเคส\", \n  \"15\", // spot ก่อน us\n  \"16\", // ปรึกษาแพทย์\n  \"20\", // spot หลัง us\n];\n\n    if(acceptedStatuses.includes(status)) {\n        return true\n    } else {\n        throw new Error(''ไม่ใช่สถานะ ปิดเคส'');\n    return false\n    }\n}"}', '7b5c1c90-56d0-4740-93d6-9fe58388afaa', NULL, '74c5ff61-80ae-49e8-a670-1e23e42a78be', '2025-04-22 12:53:46.027+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
