INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('27facdb2-9e65-4b42-832b-b8a22b1fc5af', 'sort data by id', 'sort_data_by_id', 'exec', 1, 21, '{"code":"module.exports = async function (data) {\n  const exams = {{read_all_patient_info_data}};\n\n  const sorted = [...exams].sort((a, b) => b.id - a.id);\n\n  return sorted[0] ?? null;\n};"}', '829a3a11-2a96-488a-8244-143301d5f7a2', NULL, 'f68004b6-ccad-4ccb-bea1-0a41a0067056', '2026-01-27 04:43:04.508+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
