INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('764cde67-2c01-4775-a7e1-05a3f5069055', 'เข้า Trigger Flow Progress Created (v.ส่ง id)', 'trigger_flow_progress_created_nxndg_ruefc_dogyw_rmugs_eltht_dwjnt', 'trigger', 74, 70, '{"payload":{"action":"doctor","user":"{{read_data_doctor_work.doctor}}","progress":"{{create_progress_consult}}"},"flow":"89be6643-9611-41be-8186-059689a6c8d3"}', NULL, NULL, '7f07d6c2-0785-4b82-b2ba-4003555b0576', '2026-08-18 13:21:44.522+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('05e337ad-4cd9-46f0-984b-42a84d8fb54f', 'สร้างข้อมูล center_income (CD)', 'center_income_cd', 'item-create', 22, 37, '{"collection":"center_income","emitEvents":true,"payload":{"first_name":"{{read_data_patient_info.first_name_th}}","last_name":"{{read_data_patient_info.last_name_th}}","full_name":"{{read_data_patient_info.first_name_th}} {{read_data_patient_info.last_name_th}}","type":"1","service_fee":"1","amount":100,"location":"{{read_data_finance_work.location}}","date_time_created":"{{current_time.currentTime}}","patient_info":"{{read_data_patient_info.id}}","address":"{{read_data_address.address}} {{read_data_address.sub_district}} {{read_data_address.district}} {{read_data_address.province}} {{read_data_address.zipcode}}"},"permissions":"$full"}', '402b78e1-95cf-4a1f-95d9-e83366111013', NULL, '69f5e99d-d7b5-4afd-94ef-770ec1a60747', '2025-04-22 05:58:23.164+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('dcc6ecad-947b-41da-b7ef-dbd1ff9f8d69', 'เช็คสถานะ appointment ว่าเป็น ไม่มาตามนัด หรือยกเลิกนัด หรือไม่', 'check_cancel_appointment', 'exec', 6, 54, '{"code":"module.exports = async function(data) {\n    let appointmentStatus = \"{{read_data_appointment.appointment_status}}\";\n    if (appointmentStatus == \"ไม่มาตามนัด\") {\n        return \"ไม่มาตามนัด\"; \n    } \n    else if (appointmentStatus == \"ยกเลิกนัด\") {\n        return \"ยกเลิกนัด\"; \n    } \n\n    throw new Error(''ไม่เข้าเงื่อนไข''); \n\n};\n"}', '47c03473-f631-487c-a871-2118e0a24849', NULL, 'd3f538b5-8d62-4058-9536-6fb9697e90d8', '2024-10-21 08:27:59.743+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('2241d73b-e784-43ee-b570-2516f746c131', 'เช็คว่า appointment_status ของ appointment ที่ถูกอ่านมาก่อนหน้านี้ เป็นส่งตรวจหรือไม่', 'check_have_queue_guymc_lnkbm', 'exec', 6, 37, '{"code":"module.exports = async function(data) {\n    let appointmentStatus = \"{{read_data_appointment.appointment_status}}\";\n    if (appointmentStatus == \"ส่งตรวจ\") {\n        return true; \n    } \n\n    throw new Error(''นัดหมายนี้ไม่ใช่ส่งตรวจ''); \n\n};\n"}', 'd663531c-2a58-4cee-9bcb-c57bfc981dd2', 'dcc6ecad-947b-41da-b7ef-dbd1ff9f8d69', 'd3f538b5-8d62-4058-9536-6fb9697e90d8', '2024-10-21 08:27:59.819+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('c80ec306-91ce-4c7d-a50a-d739013ac9a9', 'เช็คว่าเคสนี้มีหมอรับเคสไปแล้วหรือยัง', 'exec_87597', 'exec', 75, 1, '{"code":"module.exports = async function(data) {\n    const exam = {{read_data_examination}};\n\n    if (exam.case_owner_doctor) {\n        return true;\n    }\n\n    throw new Error(''exam นี้ยังไม่มีหมอ'');\n    return false;\n}"}', '37c847ac-8392-440e-911f-92a69edd3949', 'e92e6855-1a2a-4fec-a587-f95abd2f7c11', 'e472714e-dd02-4bfc-8038-133053a0a457', '2025-03-24 10:12:58.106+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('3bbcff28-3c07-4b89-9b93-739c1837be74', 'return ค่า id ของ progress ตัวสุดท้าย จากข้อมูล worklist ที่ถูกอ่านมาก่อนหน้านี้', 'last_no_progress', 'exec', 39, 19, '{"code":"module.exports = async function(data) {\n    const progressArray = {{read_data_worklist.progress}};\n\n    // เช็คว่า progress array มีค่าหรือไม่ และมีข้อมูลอยู่\n    if (progressArray && progressArray.length > 0) {\n        // จัดเรียง progress ตามไอดีจากน้อยไปมาก\n        const sortedProgressArray = progressArray.sort((a, b) => a - b);\n\n        // ดึง progress ID ตัวสุดท้ายหลังจากจัดเรียง\n        const lastProgressId = sortedProgressArray[sortedProgressArray.length - 1];\n\n        return {\n            lastProgressId: lastProgressId\n        };\n    } else {\n        return {\n            message: ''No progress data found''\n        };\n    }\n};"}', '2241d73b-e784-43ee-b570-2516f746c131', NULL, 'd3f538b5-8d62-4058-9536-6fb9697e90d8', '2024-10-21 08:27:59.857+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('13d37aff-8aee-448d-bfc4-63761444ba84', 'อ่านข้อมูล queue ของ appointment ที่อ่านมาก่อนหน้านี้', 'read_data_queue', 'item-read', 3, 19, '{"collection":"queue","key":["{{read_data_appointment.queue[0]}}"],"permissions":"$full"}', 'e75dc90c-08ed-4d04-afc6-cb09e38d03bd', NULL, 'd3f538b5-8d62-4058-9536-6fb9697e90d8', '2024-10-21 08:27:59.916+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
