INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('cc42d515-f654-4505-a0ef-d42da5165a42', 'ย้ายไฟล์ไปที่ folder Referral form', 'request_62g7q', 'request', 26, 34, '{"method":"PATCH","url":"{{read_environment.url}}/files/{{get_file_data.data.data.referral_form[0].directus_files_id.id}}","body":"{\n     \"folder\": \"fc4d1cc1-491a-45e6-b582-f66179a65ff9\"\n}","headers":[{"header":"Authorization","value":"Bearer {{read_environment.access_token}}"}]}', NULL, NULL, 'a9851cbc-1c3d-4e30-b4e4-0a1446166bb6', '2024-10-09 06:54:17.602+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('1cb214ce-ee14-4934-8da7-08db3f281dd2', 'อ่านข้อมูล appointment ที่ฟิลด์ referral_form', 'get_file_data', 'request', 73, 1, '{"url":"{{read_environment.url}}/items/appointment/{{check_trigger}}?fields=referral_form.*.*","headers":[{"header":"Authorization","value":"Bearer {{read_environment.access_token}}"}]}', '818ed4f8-2288-4c4e-b789-baf00ac3d029', NULL, 'a9851cbc-1c3d-4e30-b4e4-0a1446166bb6', '2024-10-09 03:23:05.467+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
