INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('0b57264f-7820-47a0-9b5f-21c6a1b68d9b', 'return ค่า id ของ progress ตัวสุดท้าย จากข้อมูล worklist ที่ถูกอ่านมาก่อนหน้านี้', 'last_no_progress', 'exec', 21, 34, '{"code":"module.exports = async function(data) {\n    const progressArray = {{read_data_worklist.progress}};\n\n    // เช็คว่า progress array มีค่าหรือไม่ และมีข้อมูลอยู่\n    if (progressArray && progressArray.length > 0) {\n        // จัดเรียง progress ตามไอดีจากน้อยไปมาก\n        const sortedProgressArray = progressArray.sort((a, b) => a - b);\n\n        // ดึง progress ID ตัวสุดท้ายหลังจากจัดเรียง\n        const lastProgressId = sortedProgressArray[sortedProgressArray.length - 1];\n\n        return {\n            lastProgressId: lastProgressId\n        };\n    } else {\n        return {\n            message: ''No progress data found''\n        };\n    }\n};"}', 'b921e43f-39fb-4dfb-b5f1-03f4c1a2b1a3', NULL, 'ed9487b5-5316-42b2-96ee-6c58162b72bb', '2025-02-26 10:48:49.07+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('804a1935-d583-4f57-8729-d53d908a8a4c', 'เข้า Trigger Flow Progress Created (v.ส่ง id)', 'trigger_flow_progress_created_v_id_oqcir', 'trigger', 75, 35, '{"flow":"89be6643-9611-41be-8186-059689a6c8d3","payload":{"action":"officer","user":"{{read_data_examination.case_owner_tech}}","progress":"{{last_no_progress.lastProgressId}}"}}', NULL, NULL, 'cbd6eeeb-ea02-40ee-be82-36164ee8b18c', '2026-08-18 07:51:46.705+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('78d524d5-1a58-422c-8099-1fa03ce36c00', 'return ค่าวัน-เวลาของตอนนี้', 'current_time', 'exec', 4, 52, '{"code":"module.exports = async function(data) {\n    const now = new Date();  \n    now.setUTCHours(now.getUTCHours() + 7);\n    const localTime = now.toISOString().slice(0, -1);\n    \n    return {\n        currentTime: localTime \n    };\n};"}', 'c88e3fee-92ad-4628-bf28-077119a73670', NULL, '69f5e99d-d7b5-4afd-94ef-770ec1a60747', '2026-07-31 12:38:37.147+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('26703b92-5cc6-4584-96af-4e4370035e2b', 'เช็ค pid ว่ามีตัวอักษรหรือไม่', 'check_pid', 'exec', 3, 34, '{"code":"module.exports = async function(data) {\n    const pid = \"{{read_patient_info_data.pid}}\";\n    const trimmedPid = String(pid || \"\").trim();\n\n    // ไปต่อเฉพาะ pid ที่ขึ้นต้นด้วย K หรือ T แล้วตามด้วยตัวเลขเท่านั้น เช่น K123456, T123456\n    if (!/^[KT][0-9]+$/.test(trimmedPid)) {\n        throw new Error(`Validation Error: pid ''${pid}'' ไม่ได้อยู่ในรูปแบบ K หรือ T ตามด้วยตัวเลข`);\n    }\n\n    // ตัดตัวอักษรนำหน้า (K/T) ออก ให้เหลือแค่ตัวเลข\n    const numericOnlyPid = trimmedPid.slice(1);\n\n    // ส่งค่ากลับไปเพื่อใช้ Flow ถัดไป โดยใช้ pid ที่ตัด K/T ออกแล้ว\n    return {\n        status: \"success\",\n        original_pid: pid,\n        pid: numericOnlyPid\n    };\n}\n"}', '696acf1f-f08d-4b68-8bda-1a5736f0b64e', NULL, '745702ca-86a5-4630-86d5-0c21951b61ce', '2026-07-17 11:10:40.934+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('09d9ac8c-e63d-48c5-975d-f7093a0f0df1', 'เช็คว่าเคสนี้สร้าง Ultrasound_work ไปแล้วใช่หรือไม่', 'exec_87597_jfegj_bsbjc', 'exec', 130, 54, '{"code":"module.exports = async function (data) {\n  const ultrasoundWorkList = {{read_ultrasound_work}};\n\n  if (ultrasoundWorkList.length > 0) {\n    return true;\n  }\n\n  throw new Error(\"เคสนี้ไม่เคยสร้าง Ultrasound_Work\");\n};\n"}', '97f4f4bd-6669-4d16-a833-5e9df49f4b8f', NULL, 'e472714e-dd02-4bfc-8038-133053a0a457', '2026-08-20 10:13:37.972+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('280fef7a-1654-40da-baa5-5920798d50ad', 'อ่านข้อมูล Ultrasound_work', 'read_ultrasound_work', 'item-read', 112, 54, '{"collection":"ultrasound_work","key":[],"permissions":"$full","query":{"filter":{"exam":{"_eq":"{{read_data_coordinate[0].exam}}"},"appointment":{"_eq":"{{read_data_coordinate[0].appointment}}"}}}}', '09d9ac8c-e63d-48c5-975d-f7093a0f0df1', NULL, 'e472714e-dd02-4bfc-8038-133053a0a457', '2026-08-20 10:13:38.234+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('6f0c124f-40f2-4f4d-adb1-531485414b89', 'อัพเดทสถานะ doctor_work ของหมอคนนั้นเป็น "ส่ง us แล้ว"', 'update_doctor_work_sent_us', 'item-update', 111, 1, '{"collection":"doctor_work","payload":{"status":"8"},"key":["{{read_doctor_work[0].id}}"],"permissions":"$full"}', 'e8935944-6534-41f1-a15c-15a42517f7ed', NULL, 'e472714e-dd02-4bfc-8038-133053a0a457', '2025-08-26 11:19:13.691+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('cc9f080a-8264-4672-8d43-d5949d3cbf13', 'เช็คว่า exam เป็นสถานะ ส่งต่อแพทย์ หรือไม่', 'exec_hb7dh', 'exec', 38, 1, '{"code":"module.exports = async function(data) {\n    const examStatus = \"{{$trigger.payload.status}}\";\n\n    if (examStatus === \"ส่งต่อแพทย์\") {\n        return true;\n    }\n\n    throw new Error(''ไม่ใช่สถานะ ส่งต่อแพทย์'');\n    return false;\n}"}', '3755a54d-74a8-45db-8c11-364bb0948e3c', 'f5a42e53-4f80-48c8-8ff5-8e084ff671df', 'e472714e-dd02-4bfc-8038-133053a0a457', '2025-01-23 02:23:25.798+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('764ea632-a224-4f15-ac2c-d9b79b958c87', 'เข้า Trigger Flow Progress Created (v. ส่ง id)', 'trigger_flow_progress_created_nxndg_qrrfa_fplcz_wylle', 'trigger', 75, 83, '{"flow":"89be6643-9611-41be-8186-059689a6c8d3","payload":{"action":"officer","user":"{{read_data_coordinate.user_updated}}","progress":["{{last_no_progress.lastProgressId}}"]}}', NULL, NULL, 'ed9487b5-5316-42b2-96ee-6c58162b72bb', '2026-08-18 13:28:04.03+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
