INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('51b29370-86ea-44df-aa4c-1973eb15f61f', 'เช็ค action เป็น แพทย์อ่านผลเพิ่ม ใช่หรือไม่', 'check_action_wbhho', 'exec', 40, 1, '{"code":"module.exports = async function(data) {\n\tconst action = \"{{$trigger.payload.action}}\";\n\n    if (action === \"แพทย์อ่านผลเพิ่ม\") {\n        return true;\n    }\n\n    throw new Error(''action ไม่ใช่ แพทย์อ่านผลเพิ่ม'');\n    return false;\n}"}', '37f35e00-2f2e-4d22-94de-3155585a2dd0', NULL, '52bed9fc-4f3a-4b41-9c82-07cea484cb76', '2025-07-09 03:29:26.169+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('26f270f2-9862-4e41-81d6-1c43f7856778', 'อัพเดต status ของ doctor_work (เคสก่อน US)', 'update_doctor_work_status_before_us', 'item-update', 37, 49, '{"collection":"doctor_work","emitEvents":true,"key":"{{$trigger.payload.doctor_work}}","payload":{"status":"4","status_trigger_flows":"trigger"},"permissions":"$full"}', NULL, NULL, '53cf63fc-e9d9-4345-8133-658d24c9fda3', '2025-10-03 05:41:18.185+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('7ee67adf-edd1-45db-8f5c-997b1204a38e', 'อัพเดต examination เป็น "spot ก่อน us"', 'update_exam_spot_before_us_by_doctor', 'item-update', 19, 49, '{"collection":"examination","permissions":"$full","emitEvents":true,"key":"{{$trigger.payload.exam}}","payload":{"status":"10","doctor_comment":"{{$trigger.payload.doctor_comment}}","doctor_comment_detail":"{{$trigger.payload.doctor_comment_detail}}"}}', '26f270f2-9862-4e41-81d6-1c43f7856778', NULL, '53cf63fc-e9d9-4345-8133-658d24c9fda3', '2025-10-02 17:30:32.379+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('2ae8d69d-b5f0-4062-86a6-4181c0a0d3fc', 'อัพเดต examination เป็น "spot หลัง us"', 'update_exam_spot_after_us', 'item-update', 19, 33, '{"collection":"examination","permissions":"$full","emitEvents":true,"key":"{{$trigger.payload.exam}}","payload":{"status":"17","doctor_comment":"{{$trigger.payload.doctor_comment}}","doctor_comment_detail":"{{$trigger.payload.doctor_comment_detail}}"}}', '7bfac020-f52d-4b2e-95c8-f12c842c4ec7', NULL, '53cf63fc-e9d9-4345-8133-658d24c9fda3', '2025-10-02 17:21:12.436+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('7926f747-6417-421c-b81e-ad7cd01a4d72', 'เช็คว่าทำ us มาแล้วหรือยัง', 'check_is_us_done', 'exec', 55, 17, '{"code":"module.exports = async function(data) {\n\tif(!{{process_pacs_sync_infos.isUsDone}}) {\n    \tthrow new Error(''เคสนี้ยังไม่ได้ทำ Us'')\n    }\n}"}', '2ae8d69d-b5f0-4062-86a6-4181c0a0d3fc', '7ee67adf-edd1-45db-8f5c-997b1204a38e', '53cf63fc-e9d9-4345-8133-658d24c9fda3', '2025-10-02 17:21:12.655+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('b3f15ab6-200f-4ac5-a4f0-e00b6d17a6b3', 'อ่าน pacs_sync_infos', 'read_pacs_sync_infos', 'item-read', 19, 17, '{"permissions":"$full","collection":"pacs_sync_info","query":{"filter":{"_and":[{"exam":{"_eq":"{{$trigger.payload.exam}}"}},{"is_mark_del":{"_eq":false}}]}}}', 'c1e7dcb2-0125-4c82-b544-85bcd78b8c5e', NULL, '53cf63fc-e9d9-4345-8133-658d24c9fda3', '2025-10-02 11:16:41.509+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('4f866197-0bc0-490e-b80b-68ae16e65775', 'เช็คว่าเป็น pacs_sync_info ที่ถูกลบไหม', 'is_deletetd_pacs_sync_info', 'condition', 19, 1, '{"filter":{"$trigger":{"payload":{"is_mark_del":{"_eq":true}}}}}', 'e650b0d4-aca7-49fd-a745-0c5708559677', NULL, '77f15364-7d4f-4550-96f8-ce32bac20075', '2026-09-01 02:59:01.63+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('a406bf23-e9b1-4fb3-85d9-628dd9a6dc5a', 'เช็คว่ามี nurse_work แล้วยัง', 'check_nurse_work', 'exec', 58, 1, '{"code":"module.exports = async (data) => {\n  if (data.existing_nurse_work?.length) throw new Error(\"มี nurse_work แล้ว\");\n  return true;\n};\n"}', '21cbe656-af1a-4a67-8607-17465d9cdcb9', NULL, 'a4478d87-09b2-4841-9b79-c6378eaae11d', '2026-11-17 03:56:40.936+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('f481f3dd-ead1-428c-9608-3449eb4a74db', 'อ่านข้อมูล nurse_work(กันซ้ำ)', 'existing_nurse_work', 'item-read', 40, 1, '{"query":{"filter":{"appointment":{"_eq":"{{get_key.id}}"}},"fields":["id"],"limit":1},"permissions":"$full","collection":"nurse_work"}', 'a406bf23-e9b1-4fb3-85d9-628dd9a6dc5a', NULL, 'a4478d87-09b2-4841-9b79-c6378eaae11d', '2026-11-17 03:56:41.26+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('35806b94-002a-4efa-b928-2586fa724cb7', 'สร้างข้อมูล exam', 'creat_exam_data', 'item-create', 37, 40, '{"collection":"examination","emitEvents":true,"permissions":"$full","payload":{"appointment":"{{read_appointment_data.id}}","status":"0"}}', '8058cade-55e9-4cb3-a17e-6bda6e0897a2', NULL, 'a4478d87-09b2-4841-9b79-c6378eaae11d', '2025-12-02 15:43:48.712+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('4a0e20d9-0f45-4377-8d71-352e93ab575c', 'เช็คสถานะ finance_work', 'check_status', 'exec', 37, 1, '{"code":"module.exports = async function(data) {\n    let finance_work = {{read_data_finance_work}};\n\n    if (finance_work.status == 1) {\n        return true; \n    } \n    throw new Error(''สถานะคิว ไม่ใช่ กำลังดำเนินการ''); \n\n};\n"}', 'da7a847c-b169-4143-a802-c3254a89a848', NULL, 'ce0d2f42-09c1-4e35-b370-f5db5c3abbbb', '2026-07-03 04:37:18.841+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('785021fc-633a-4cdd-aec9-e27999481a4d', 'อ่าน pacs_sync_info ที่ active ทั้งหมดของ exam นี้', 'read_current_active_pacs_sync_info', 'item-read', 55, 1, '{"permissions":"$full","collection":"pacs_sync_info","query":{"filter":{"exam":{"_eq":"{{read_current_pacs_sync_info.exam}}"},"is_mark_del":{"_eq":false}},"sort":"date_created","fields":["id","is_mark_del","accession_id","end_time"]}}', 'd44b81d1-22a3-43eb-ac15-b91bcc7a4eca', NULL, '77f15364-7d4f-4550-96f8-ce32bac20075', '2026-09-01 03:49:02.502+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('6ba3d7be-37ea-4744-af18-47f1b6a0fe6b', 'เช็ค pid ว่ามีตัวอักษรหรือไม่', 'check_pid', 'exec', 59, 19, '{"code":"module.exports = async function(data) {\n    const pid = \"{{read_patient_info_data.pid}}\";\n    const trimmedPid = String(pid || \"\").trim();\n\n    // ไปต่อเฉพาะ pid ที่ขึ้นต้นด้วย K หรือ T แล้วตามด้วยตัวเลขเท่านั้น เช่น K123456, T123456\n    if (!/^[KT][0-9]+$/.test(trimmedPid)) {\n        throw new Error(`Validation Error: pid ''${pid}'' ไม่ได้อยู่ในรูปแบบ K หรือ T ตามด้วยตัวเลข`);\n    }\n\n    // ตัดตัวอักษรนำหน้า (K/T) ออก ให้เหลือแค่ตัวเลข\n    const numericOnlyPid = trimmedPid.slice(1);\n\n    // ส่งค่ากลับไปเพื่อใช้ Flow ถัดไป โดยใช้ pid ที่ตัด K/T ออกแล้ว\n    return {\n        status: \"success\",\n        original_pid: pid,\n        pid: numericOnlyPid\n    };\n}\n"}', '0198f454-4b30-4782-b119-7de7e562e215', NULL, 'a4478d87-09b2-4841-9b79-c6378eaae11d', '2026-10-27 09:06:29.589+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('e650b0d4-aca7-49fd-a745-0c5708559677', 'อ่านข้อมูล pacs_sync_info ที่ถูกลบ', 'read_current_pacs_sync_info', 'item-read', 37, 1, '{"permissions":"$full","collection":"pacs_sync_info","key":"{{$trigger.keys[0]}}","query":{"fields":["id","modality","is_mark_del","accession_id","end_time","patient","exam"]}}', '785021fc-633a-4cdd-aec9-e27999481a4d', NULL, '77f15364-7d4f-4550-96f8-ce32bac20075', '2026-09-01 03:49:02.683+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('8058cade-55e9-4cb3-a17e-6bda6e0897a2', 'เช็คเงื่อนไขอัพเดท bx_status ของนัดหมาย', 'check_department_bx', 'exec', 55, 40, '{"code":"module.exports = async function (data) {\n  const departmentBx = \"{{read_appointment_data.department_bx}}\";\n\n  if (departmentBx === \"tech-cd\") {\n    return {\n      bx_status: \"2\",\n    };\n  }\n\n  if (departmentBx === \"tech\") {\n    const frontNote1 = {{read_appointment_data.front_note_1}};\n    const acceptances = [\"มี CD\", \"นำผลเก่ามา\"];\n    \n    return {\n      bx_status: frontNote1.some(note => acceptances.includes(note)) ? \"2\" : \"1\",\n    };\n  }\n\n  throw new Error(\"นัดหมายนี้ไม่เข้าเงื่อนไข\");\n};\n"}', '9a6dd89c-ac48-467b-bdba-ca576497c3d5', NULL, 'a4478d87-09b2-4841-9b79-c6378eaae11d', '2025-12-10 01:54:00.6+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('3ca604a4-0492-4b3f-8b5a-b18b3a63b40e', 'สร้าง progress รอจัดสรรแพทย์', 'create_progress_send_doctor', 'item-create', 76, 84, '{"payload":{"title":"รอจัดสรรแพทย์","admission_time":"{{current_time.currentTime}}","status":"รอดำเนินการ","department":"แพทย์","worklist":"{{read_data_queue.worklist[0]}}","is_hide_users":true},"collection":"progress"}', '1a9c5c91-9c11-4904-8cce-8b42f14d3364', NULL, 'cbd6eeeb-ea02-40ee-be82-36164ee8b18c', '2025-02-24 01:59:00.195+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('5d09baa0-00c2-4362-9e31-2173a3ee1dd0', 'เช็คว่า Progress ตัวสุดท้ายไม่ใช่ ถ่าย Mam เพิ่ม', 'exec_wvr55_crgxd_hbuny_rtbvh', 'exec', 40, 84, '{"code":"module.exports = async function(data) {\n   const lastProgress = {{read_data_last_progress}};\n    \n    if (lastProgress.title !== \"ถ่าย Mammogram เพิ่ม\") {\n        return true; \n    } \n\n    throw new Error(''lastProgress เป็นคือ ถ่าย Mammogram เพิ่ม''); \n};\n"}', '08041e42-7564-472d-9b09-b7157ec6106c', NULL, 'cbd6eeeb-ea02-40ee-be82-36164ee8b18c', '2025-09-15 10:27:10.276+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('bb60e92f-c206-4d90-b223-026e9a47c34b', 'สร้าง progress แพทย์วินิจฉัย', 'create_progress_doctor_dx', 'item-create', 57, 68, '{"payload":{"title":"แพทย์วินิจฉัย","admission_time":"{{current_time.currentTime}}","status":"รอดำเนินการ","department":"แพทย์","worklist":"{{read_data_queue.worklist[0]}}"},"collection":"progress"}', '4e485d5f-dfff-4c60-a19c-d8ec12425270', NULL, 'cbd6eeeb-ea02-40ee-be82-36164ee8b18c', '2025-09-04 09:37:00.057+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('f409b9e0-544b-43f6-8fc3-94b8e29d19e8', 'เข้า Trigger Flow Progress Created (v.ส่ง id)', 'trigger_flow_progress_created_v_id_nnlog', 'trigger', 74, 52, '{"flow":"89be6643-9611-41be-8186-059689a6c8d3","payload":{"action":"doctor","user":"{{read_data_examination.case_owner_doctor}}","progress":"{{create_progress_send_mam}}"}}', NULL, NULL, 'cbd6eeeb-ea02-40ee-be82-36164ee8b18c', '2026-06-29 11:33:03.467+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('bf99a228-27ef-4409-b1ca-70e69af99508', 'เช็คว่าเป็น ยกเลิกปรึกษาแพทย์ ใช่หรือไม่', 'check_cancel_consult', 'condition', 19, 1, '{"filter":{"$trigger":{"payload":{"cancel_consult":{"_eq":true}}}}}', '86e45252-4e23-4831-9a6b-275dc582cb99', NULL, 'c3ded7f7-dab3-4851-ad14-91e829225c91', '2026-11-11 03:43:28.101+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('01a0f9bd-69af-425c-8e63-dc98ecbecd34', 'เช็คว่าเป็นถ่าย Mam หลัง us หรือไม่', 'exec_wvr55_crgxd_hbuny', 'exec', 21, 68, '{"code":"module.exports = async function(data) {\n   const examData = {{read_data_examination}};\n    \n    if (examData.is_mam_after_us_done) {\n        return true; \n    } \n\n    throw new Error(''is_mam_after_us_done เป็น false''); \n};\n"}', 'a09c26fc-c355-4208-834a-7a93f070f553', '3988243c-b228-405b-8175-3a64a4931261', 'cbd6eeeb-ea02-40ee-be82-36164ee8b18c', '2025-09-04 09:37:00.461+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('5867ad24-bd9a-4a36-a436-891813f842d9', 'เช็คว่า status เป็นค่า ส่งต่อแพทย์ ใช่หรือไม่', 'exec_wvr55_crgxd', 'exec', 3, 68, '{"code":"module.exports = async function(data) {\n    const statusTriggerFlows = \"{{$trigger.payload.status_trigger_flows}}\";\n    const statusExam = \"{{$trigger.payload.status}}\";\n    \n    if (statusExam === \"ส่งต่อแพทย์\" && statusTriggerFlows !== \"undefined\") {\n        return true; \n    } \n\n    throw new Error(''statusExam ไม่เท่ากับ ส่งต่อแพทย์''); \n\n};\n"}', '01a0f9bd-69af-425c-8e63-dc98ecbecd34', '727c0ffd-9a67-40ba-bc8e-f7a902b53989', 'cbd6eeeb-ea02-40ee-be82-36164ee8b18c', '2025-02-24 01:59:00.287+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('cc1d6a5c-8466-41cf-ba16-6aac6a095a24', 'สร้าง progress ผู้มาตรวจถ่าย Mammogram', 'create_progress_send_mam', 'item-create', 39, 52, '{"payload":{"title":"ผู้มาตรวจถ่าย Mammogram","admission_time":"{{current_time.currentTime}}","status":"รอดำเนินการ","department":"Tech","worklist":"{{read_data_queue.worklist[0]}}"},"collection":"progress"}', '7c93ad07-a673-454f-bbc5-f389a6619918', NULL, 'cbd6eeeb-ea02-40ee-be82-36164ee8b18c', '2025-02-19 02:07:50.652+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('e149a194-30b0-44a0-a570-fd23f0664ddf', 'เช็คว่า status เป็นค่า ส่ง MAM - รอเรียกคิว ใช่หรือไม่', 'exec_wvr55', 'exec', 3, 52, '{"code":"module.exports = async function(data) {\n    const statusTriggerFlows = \"{{$trigger.payload.status_trigger_flows}}\";\n    const statusExam = \"{{$trigger.payload.status}}\";\n    \n    //ส่ง MAM - รอเรียกคิว\n    if (statusExam === \"ส่ง MAM - รอเรียกคิว\") {\n        return true; \n    } \n\n    throw new Error(''statusExam ไม่เท่ากับ ส่ง MAM - รอเรียกคิว''); \n\n};\n"}', '4f1ec4f1-0d64-4064-8fc2-1f337a9473e7', '5867ad24-bd9a-4a36-a436-891813f842d9', 'cbd6eeeb-ea02-40ee-be82-36164ee8b18c', '2025-02-19 01:40:18.55+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('293d3eb0-fe12-499b-a2c1-87c34eb25257', 'อัพเดทฟิลด์ status, close_cast_time ของ progress ตัวสุดท้าย', 'status_close_cast_time_progress', 'item-update', 21, 35, '{"payload":{"close_case_time":"{{current_time.currentTime}}","status":"เสร็จสิ้น"},"key":["{{last_no_progress.lastProgressId}}"],"collection":"progress","permissions":"$full"}', '4b04350f-a32a-4547-a314-e0da694df9b8', NULL, 'cbd6eeeb-ea02-40ee-be82-36164ee8b18c', '2025-02-18 16:19:40.811+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('a41c76b1-cf58-4015-a85e-2dfd517794dc', 'เช็ค bx_status', 'check_is_refer_procedure', 'exec', 19, 1, '{"code":"module.exports = async function (data) {\n  const p = data.$trigger.payload ?? {};\n  if (\n    String(p.bx_status) !== \"5\" ||\n    p.status_trigger_flows !== \"trigger\" ||\n    !p.bx_doctor\n  ) {\n    throw new Error(\"ไม่ใช่เคสพยาบาลส่งทำหัตถการ\");\n  }\n};\n"}', '3e0f380b-d284-4176-8a28-c04a9db991a8', NULL, '8312ecaf-0d37-4640-87ed-65804fcc2384', '2026-11-17 08:18:39.442+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('a09c26fc-c355-4208-834a-7a93f070f553', 'อัพเดทฟิลด์ status, close_cast_time ของ progress ตัวสุดท้าย', 'status_close_cast_time_progress_utzpf_gxpll_urskn', 'item-update', 39, 68, '{"payload":{"close_case_time":"{{current_time.currentTime}}","status":"เสร็จสิ้น"},"key":["{{last_no_progress.lastProgressId}}"],"collection":"progress","permissions":"$full"}', 'bb60e92f-c206-4d90-b223-026e9a47c34b', NULL, 'cbd6eeeb-ea02-40ee-be82-36164ee8b18c', '2025-09-04 09:37:00.069+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('86e45252-4e23-4831-9a6b-275dc582cb99', 'อัพเดทข้อมูล doctor_work', 'doctor_work', 'item-update', 37, 1, '{"collection":"doctor_work","permissions":"$full","payload":{"status":"23"},"query":{"filter":{"_and":[{"nurse_work":{"_eq":"{{$trigger.keys[0]}}"}},{"status":{"_eq":"19"}}]}},"emitEvents":true}', NULL, NULL, 'c3ded7f7-dab3-4851-ad14-91e829225c91', '2026-11-11 03:44:24.511+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('868a457b-88f8-48b8-b12c-9ebe1ca68af0', 'อ่านข้อมูล exam', 'read_data_exam', 'item-read', 3, 34, '{"permissions":"$full","collection":"examination","key":["{{read_data_ultrasound_work.exam}}"],"query":{"fields":["*","examination_general.*"]}}', '21dc2cd3-f869-4a02-b467-3045393791ca', NULL, '52bed9fc-4f3a-4b41-9c82-07cea484cb76', '2025-07-06 04:21:38.415+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('9e7dc062-9503-4bef-a177-17058c1ede7e', 'เช็คเงื่อนไขสร้าง nurse_work (tech)', 'exec_oecsf_qquub', 'exec', 19, 40, '{"code":"module.exports = async function(data) {\n    if (\"{{read_appointment_data.request}}\" === \"bx\" && (\"{{read_appointment_data.department_bx}}\" === \"tech\" \n        || \"{{read_appointment_data.department_bx}}\" === \"tech-cd\")) {\n        return true; \n    } \n    throw new Error(''นัดหมายนี้ไม่เข้าเงื่อนไข''); \n\n};\n"}', '35806b94-002a-4efa-b928-2586fa724cb7', NULL, 'a4478d87-09b2-4841-9b79-c6378eaae11d', '2025-12-02 15:43:48.722+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('2514bc28-9e80-4840-a5db-e2f32083e624', 'เช็คว่า appointment มีคิวหรือไม่', 'check_have_queue', 'exec', 37, 1, '{"code":"module.exports = async function(data) {\n    let appointmentQueue = {{read_data_appointment.queue}};\n    if (appointmentQueue && appointmentQueue.length > 0) {\n        return true; \n    } \n\n    throw new Error(''นัดหมายนี้ไม่มีคิว''); \n\n};\n"}', '1be48ccd-0eeb-4a56-996c-d0e13e981767', NULL, 'd3f538b5-8d62-4058-9536-6fb9697e90d8', '2024-10-21 05:25:30.305+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('d44b81d1-22a3-43eb-ac15-b91bcc7a4eca', 'สร้าง payload สำหรับ bulk update', 'create_payload', 'exec', 19, 17, '{"code":"module.exports = async function(data) {\n  // 1. ดึง active pacs_sync_info + exam_id ออกมา \n  const rawList = data.read_current_active_pacs_sync_info || []; \n  const examId = data.read_current_pacs_sync_info.exam;\n\n  if (!examId || rawList.length === 0) {\n    return [];\n  }\n\n  // 2. แยกรายการที่ถูกตรึงค่า => อันที่ดำเนินการเสร็จแล้ว (มี end_time + ยังไม่โดนลบ)\n  const lockedAccessionIds = new Set(\n    rawList\n      .filter(({ end_time, is_mark_del, accession_id }) => \n              end_time !== null && !is_mark_del && accession_id\n      )\n      .map(({ accession_id }) => accession_id)\n  );\n\n  // 3. เตรียมตัวแปรรัน Index และ Array สำหรับผลลัพธ์ที่จะเอาไป Bulk Update\n  let currentIndex = 0;\n  const updatePayload = [];\n\n  // 4. วน Loop ประมวลผลข้อมูลแต่ละก้อน\n  for (const item of rawList) {\n    // เคส 4.1: รายการที่มี end_time (ถูกตรึงค่าไว้) ไม่ต้องเปลี่ยน accession_id\n    if (item.end_time !== null) {\n      continue;\n    }\n\n    // เคส 4.2: รายการปกติที่ต้องรัน accession_id ใหม่\n    let newAccessionId = \"\";\n    \n    // วนหาเลข Index ถัดไปที่ยังไม่ชนกับเลขที่โดนตรึงเอาไว้ (lockedAccessionIds)\n    while (true) {\n      const paddedIndex = String(currentIndex).padStart(3, \"0\");\n      const candidateId = `${examId}${paddedIndex}`;\n\n      currentIndex++;\n\n      // ถ้าเลขนี้ไม่ได้ซ้ำกับเลขที่โดนตรึงไว้ ให้ใช้เลขนี้\n      if (!lockedAccessionIds.has(candidateId)) {\n        newAccessionId = candidateId;\n        break;\n      }\n    }\n\n    // เพิ่มในรายการที่จะอัปเดตเฉพาะตัวที่ค่าเปลี่ยนไปจากเดิม\n    if (item.accession_id !== newAccessionId) {\n      updatePayload.push({\n        id: item.id,\n        accession_id: newAccessionId,\n        sync_file_name: null,\n        pacs_sync_time: null,\n        status: 0\n      });\n    }\n  }\n\n  return updatePayload;\n};"}', '0d4e66a2-a176-43dc-b875-f5b8af3f3704', NULL, '77f15364-7d4f-4550-96f8-ce32bac20075', '2026-09-01 03:55:32.973+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('bdbadc5d-6cbb-4d76-af20-5cd041f543bb', 'เช็ค Triggerflows และสถานะ us_work ว่าเป็น ถ่ายสำเร็จ ใช่หรือไม่', 'triggerflows_us_work', 'exec', 4, 18, '{"code":"module.exports = async function(data) {\n\t// ถ่ายสำเร็จ\n    const ultrasoundStatus = {{$trigger.payload.status}};\n\tconst triggerFlows = \"{{$trigger.payload.status_trigger_flows}}\";\n\n    if (ultrasoundStatus == \"6\" && triggerFlows !== \"undefined\") {\n        return true;\n    }\n\n    throw new Error(''สถานะไม่ใช่ ถ่ายสำเร็จ หรือ  triggerFlows ไม่มีค่า'');\n    return false;\n}"}', '51b72105-e1ca-4f18-be10-3b869a176dff', NULL, '52bed9fc-4f3a-4b41-9c82-07cea484cb76', '2025-07-06 04:21:38.606+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('2cbe2557-1ecf-4401-a61f-9402a46c62ac', 'สร้างข้อมูล  appointment', 'create_new_appointment', 'item-create', 62, 118, '{"collection":"appointment","permissions":"$full","payload":"{{body_create_exam_edit_appointment}}","emitEvents":true}', NULL, NULL, '52bed9fc-4f3a-4b41-9c82-07cea484cb76', '2025-12-16 04:39:26.356+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('caa25817-008b-4de8-915d-9ad6e0a8f803', 'เช็คว่าเป็นเคสส่งปรึกษาแพทย์ไหม', 'check_is_consult', 'exec', 20, 1, '{"code":"module.exports = async function (data) {\n  const p = data.$trigger.payload ?? {};\n  if (p.status === undefined || p.status === null || String(p.status) !== \"6\") {\n    throw new Error(\"ไม่ใช่เคสส่งปรึกษาแพทย์\");\n  }\n};\n"}', '95dbac9a-fd39-4050-9d43-efdc024069a5', NULL, '7f4f84da-8f9f-4d4d-8e01-f14aec4515e0', '2026-11-17 08:19:58.2+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('51b72105-e1ca-4f18-be10-3b869a176dff', 'เช็ค action เป็น ปล่อยกลับบ้าน หรือ confirm_bx ใช่หรือไม่', 'check_action', 'exec', 22, 18, '{"code":"module.exports = async function(data) {\n\tconst action = \"{{$trigger.payload.action}}\";\n\n    if (action === \"ปล่อยกลับบ้าน\" || action === \"Confirm Bx\") {\n        return true;\n    }\n\n    throw new Error(''action ไม่ใช่ ปล่อยกลับบ้าน หรือ Confirm Bx'');\n    return false;\n}"}', '9a23c65b-d297-445b-a47a-9d2a4492a93c', '51b29370-86ea-44df-aa4c-1973eb15f61f', '52bed9fc-4f3a-4b41-9c82-07cea484cb76', '2025-07-06 04:21:38.543+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('5ae06187-ae46-4034-a2f7-94a830f8f6a0', 'อ่านข้อมูล nurse_work', 'read_nurse_work', 'item-read', 37, 1, '{"collection":"nurse_work","permissions":"$full","query":{"fields":["id","examination","bx_doctor","appointment.id","appointment.location"]},"key":["{{$trigger.keys[0]}}"]}', '6085a9c3-f4e6-4269-9848-b0b3fa0bd7e6', NULL, '96612f43-f36a-46b0-8f7d-98a336cf4416', '2026-11-16 12:26:59.065+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
INSERT INTO public.directus_operations (id, name, key, type, position_x, position_y, options, resolve, reject, flow, date_created, user_created) VALUES ('f21260e8-0ae2-42fa-89e6-e4d5fba5b48c', 'เช็คว่า bx_status = 17 หรือไม่', 'exec_j4gyy', 'exec', 19, 1, '{"code":"module.exports = async function (data) {\n  const p = data.$trigger.payload ?? {};\n  if (\n    String(p.bx_status) !== \"17\" ||\n    p.status_trigger_flows !== \"trigger\" ||\n    !p.bx_doctor\n  ) {\n    throw new Error(\"ไม่ใช่เคสพยาบาลส่งต่อแพทย์อ่านผลก่อนเจาะ\");\n  }\n};\n"}', '5ae06187-ae46-4034-a2f7-94a830f8f6a0', NULL, '96612f43-f36a-46b0-8f7d-98a336cf4416', '2026-11-17 08:17:29.708+00', 'f0e0b60d-69de-45ef-aab0-14da792a6145');
